(window.COSMIC_I18N = window.COSMIC_I18N || {}).ko = Object.freeze({"moon":{"aries":"양자리에 있는 달","taurus":"황소자리에 있는 달","gemini":"쌍둥이자리에 있는 달","cancer":"게자리에 있는 달","leo":"사자자리에 있는 달","virgo":"처녀자리에 있는 달","libra":"천칭자리에 있는 달","scorpio":"전갈자리에 있는 달","sagittarius":"사수자리에 있는 달","capricorn":"염소자리에 있는 달","aquarius":"물병자리에 있는 달","pisces":"물고기자리에 있는 달"},"sky":{"classic":{"fire":["{moon}은 앞으로 나아갈 용기를 북돋우며 행동하기 전에 방향을 분명히 정하라고 권합니다.","{moon}은 생기 넘치는 에너지를 불어넣고, 그 에너지는 뚜렷한 목표를 만날 때 더욱 빛납니다.","{moon}은 모든 것이 완벽해질 때까지 기다리지 않고 전진하려는 마음을 깨웁니다.","{moon}은 진심 어린 도전을 응원하며 신중한 추진력의 가치를 일깨웁니다.","{moon}은 서두를 일이 아니라 진정 용기를 낼 만한 일이 무엇인지 비춰 줍니다.","{moon}은 하늘에 강렬한 리듬을 더하며 분별력 있게 그 흐름을 따르라고 권합니다."],"earth":["{moon}은 단순한 기준과 현실적인 행동으로 돌아가라고 권합니다.","{moon}은 인내심과 자기 속도로 나아가는 즐거움을 소중히 여깁니다.","{moon}은 꾸준히 쌓아 올리는 것에 다시 시선을 돌리게 합니다.","{moon}은 평온함과 안정감, 세부 사항을 돌보는 정성을 북돋웁니다.","{moon}은 자신에게 좋은 것을 포기하지 않으면서도 실용적인 선택을 하도록 돕습니다.","{moon}은 눈에 띄지 않는 진전도 아주 튼튼한 바탕이 될 수 있음을 일깨웁니다."],"air":["{moon}은 대화를 활발하게 하고 새로운 생각이 오가게 합니다.","{moon}은 다양한 의견과 예상 밖의 관점을 열린 마음으로 만나게 합니다.","{moon}은 호기심을 북돋우면서도 생각의 중심을 잃지 말라고 권합니다.","{moon}은 오늘의 대화에 특별한 의미를 더합니다.","{moon}은 가벼운 마음과 작은 질문에서 시작되는 발견을 응원합니다.","{moon}은 상상력을 억누르지 않으면서 생각을 정리하라고 권합니다."],"water":["{moon}은 감정을 더욱 선명하게 느끼게 하며 부드럽게 받아들이도록 이끕니다.","{moon}은 현재를 이해하는 데 도움이 될 추억을 깨웁니다.","{moon}은 자신의 내면에 귀 기울이고 가까운 사람들과 진솔한 시간을 보내도록 권합니다.","{moon}은 느낌과 침묵에 한층 깊은 의미를 더합니다.","{moon}은 마음에 여유를 줄 때 직관이 빛나도록 돕습니다.","{moon}은 자신의 필요도 잊지 않으면서 소중한 관계를 돌보라고 권합니다."]},"funny":{"fire":["{moon}은 이미 버스에 타고 있으면서도 버스를 향해 달릴 만큼의 에너지를 드립니다.","{moon}은 아무리 짧은 줄이라도 공인되지 않은 인내력 시험장으로 바꿉니다.","{moon}은 주전자가 물을 끓이기도 전에 프로젝트 다섯 개를 시작하자고 제안합니다.","{moon}은 피자 한 판을 고르는 중대한 결정을 위해 마음속에 거대한 불을 지핍니다.","{moon}은 메시지를 다시 읽기도 전에 보내기 버튼부터 누르라고 속삭입니다.","{moon}은 모두에게 용기를 나눠 주지만 자기 차례를 기다리는 사람만은 예외로 둡니다."],"earth":["{moon}은 포근한 담요와 빽빽한 일정표가 얼마든지 공존할 수 있다고 선언합니다.","{moon}은 장보기 목록을 최고 등급의 전략 문서로 격상합니다.","{moon}은 좋아하는 안락의자에서 일어나지 않고도 야망을 품을 수 있다고 일깨웁니다.","{moon}은 서랍 하나 정리한 일을 위대한 개인적 승리로 치켜세웁니다.","{moon}은 누군가 소파를 옮기겠다고 위협할 때일수록 침착하게 생각하라고 권합니다.","{moon}은 간식 시간을 공식 최우선 일정으로 바꿉니다."],"air":["{moon}은 대화를 열두 개나 시작해 놓고 첫 대화가 왜 시작됐는지 잊어버립니다.","{moon}은 별 의미 없는 알림 두 개 사이에서 천재적인 아이디어 세 개를 터뜨립니다.","{moon}은 결국 지도와 도표까지 필요한 일화를 이야기하게 만듭니다.","{moon}은 단체 채팅방이 따라잡기도 전에 온갖 의견을 쏟아 냅니다.","{moon}은 단순한 안녕하세요 한마디를 인생의 의미에 관한 토론으로 바꿉니다.","{moon}은 적절한 말을 찾아 준 다음 지나치게 많은 말까지 덤으로 드립니다."],"water":["{moon}은 오래된 상자 하나를 정리하는 일에 장엄한 드라마 음악을 깔아 줍니다.","{moon}은 날짜도 기억나지 않는 어린 시절 어느 일요일을 그리워하게 만듭니다.","{moon}은 흐릿한 사진 한 장을 개인 박물관에 전시할 소중한 추억으로 바꿉니다.","{moon}은 찬장에서 잊혔던 컵이 돌아온 일마저 감동적으로 만듭니다.","{moon}은 살짝 기운 화분에게 무슨 일 있느냐고 묻게 만듭니다.","{moon}은 고작 알겠어라고만 적힌 메시지에도 깊은 의미를 부여합니다."]},"piquant":{"fire":["{moon}은 조급함이 시간 관리 문제 따위가 아니라 개성이라고 굳게 믿게 만듭니다.","{moon}은 그냥 지나가려던 사람을 상대로 존재하지도 않는 경기를 시작하게 합니다.","{moon}은 주소도 확인하기 전에 달려 나가라고 부추깁니다.","{moon}은 조용한 대화마다 보이지 않는 초시계를 설치합니다.","{moon}은 세상이 감탄해야 할 재능으로 당신의 조급함을 착각합니다.","{moon}은 다른 사람들이 규칙을 이해하기도 전에 승리를 선언하도록 허락합니다."],"earth":["{moon}은 당신의 안락한 공간을 철통 경비 구역으로 바꿉니다.","{moon}은 쿠션 하나 바꾸려면 주민 공청회가 필요하다고 확신시킵니다.","{moon}은 익숙한 습관을 방해하는 모든 제안에 우주적 거부권을 행사합니다.","{moon}은 안정감만 찾다 보면 좋아하는 가구와 결혼하게 될 수도 있다고 일깨웁니다.","{moon}은 평소 일정을 개정 불가능한 헌법으로 격상합니다.","{moon}은 즉흥적인 행동을 반드시 신고해야 할 사건으로 보게 만듭니다."],"air":["{moon}은 아이디어를 천 개나 주고 그중 하나를 끝내는 일은 남에게 맡깁니다.","{moon}은 토론을 시작한 뒤 애초에 토론할 필요가 있었는지 다시 토론을 엽니다.","{moon}은 휴대전화 화면보다 더 빨리 의견을 바꾸도록 격려합니다.","{moon}은 갈림길을 계속 늘려서 목적지에 도착하는 일을 선택 사항으로 만듭니다.","{moon}은 마지막 한마디를 주고 거기에 마지막 열네 마디를 더 얹어 줍니다.","{moon}은 책임자도 없이 당신의 생각들을 무기한 회의에 소집합니다."],"water":["{moon}은 평범한 침묵을 네 쪽짜리 감정 보고서로 바꿉니다.","{moon}은 모두가 이미 종결 처리한 추억을 다시 회의 안건에 올립니다.","{moon}은 메시지 끝의 마침표 하나를 역사적 사건으로 해석하도록 돕습니다.","{moon}은 오래된 과자 포장지에까지 향수를 불어넣습니다.","{moon}은 멀리서 들린 한숨 하나를 두고 비상대책위원회를 소집합니다.","{moon}은 방에 들어가기도 전에 분위기를 느끼게 하고 그걸 장편소설로 쓰게 만듭니다."]}},"mercury":{"classic":["수성이 역행하는 시기에는 메시지를 보내기 전에 다시 읽어 보세요. 작은 확인이 오해를 줄일 수 있습니다.","수성 역행 아래에서 오래된 대화가 다시 떠오를 수도 있습니다. 그때의 맥락을 차분히 살펴보세요.","수성 역행은 모두가 같은 뜻으로 이해했다고 단정하기보다 세부 사항을 확인하라고 권합니다."],"funny":["수성 역행은 두 번 읽어 보라고 권합니다. 수수께끼 같은 메시지는 사실 단어 하나가 빠진 것일지도 몰라요.","옛 이야기가 다시 나왔나요? 수성 역행이 미완성 대화가 담긴 서랍을 찾아냈나 봅니다.","수성 역행은 의사소통을 시험합니다. 우주를 탓하기 전에 메시지 수신자부터 확인해 보세요."],"piquant":["수성 역행이 애매한 메시지를 보내고 곧장 사라져도 된다는 우주적 허가증은 아닙니다.","수성 역행과 함께 과거가 돌아오기도 합니다. 그렇다고 가져온 모든 파일을 열어야 하는 건 아니죠.","수성 역행은 말을 다시 살펴보라고 합니다. 상대가 마음속 생각의 자막까지 추측할 의무는 없으니까요."]},"signs":{"aries":{"classic":{"career":["당신의 진취적인 태도는 직장에서 새로운 길을 열 수 있어요. 다만 다른 사람을 움직이기 전에 목표를 분명히 해 보세요.","프로젝트가 좀처럼 시작되지 않을 때 당신의 에너지가 빛나요. 혼자 해결할 일과 함께 결정할 일을 구분해 보세요.","업무상의 어려움은 당신의 도전 정신을 자극해요. 다른 사람의 생각에도 귀를 기울이면 영향력이 더욱 커질 수 있어요.","경쟁은 당신의 결의를 깨워요. 자신의 가치를 끊임없이 증명하는 수단보다 성장의 원동력으로 삼아 보세요.","지시가 모호할 때는 일단 행동하고 싶어져요. 핵심 질문 몇 가지만 던져도 불필요한 우회를 줄일 수 있어요.","빠른 성과를 바라는 마음에는 유연한 계획이 필요해요. 큰 목표를 눈에 보이는 단계로 나누고 작은 진전도 인정해 주세요.","회의가 길어질 때 당신의 솔직함이 분위기를 바꿀 수 있어요. 다만 적절한 순간을 골라 의견을 내세요.","먼저 나서는 모습이 당신답습니다. 동료들이 뒤쫓는 대신 함께 나아갈 수 있도록 방법도 공유해 보세요."],"love":["당신의 자발적인 애정 표현은 관계에 활기를 불어넣어요. 상대방에게도 자기만의 속도를 허락해 주세요.","소중한 사람에게 마음을 숨기지 않는 편이군요. 진심 어린 경청도 사랑을 전하는 강한 방법이에요.","너무 빨리 뱉은 말이 본뜻보다 날카롭게 들릴 수 있어요. 의견 차이를 대결로 만들기 전에 다시 표현해 보세요.","당신은 뜨거운 감정을 좋아하지만 조용한 순간도 깊은 친밀감을 키울 수 있어요.","생각이 다를 때에도 솔직함에 여지를 남겨 주세요. 설득하기 전에 이해하려는 노력이 중요해요.","독립심은 당신에게 중요한 균형이에요. 상대방이 알아서 짐작하리라 기대하지 말고 필요한 공간을 말해 주세요.","먼저 다가가려는 마음이 강하면 모든 주도권을 혼자 쥐게 될 수 있어요. 상대방의 뜻밖의 제안도 기다려 보세요.","잘못을 인정한다고 강인함이 줄어들지는 않아요. 소박한 행동 하나가 긴 설명보다 마음을 누그러뜨릴 수 있어요."],"wellbeing":["강한 에너지만큼 회복의 시간도 필요해요. 바쁜 일정 사이에 진짜 휴식을 마련해 보세요.","조급함이 올라올 때 목적지 없는 산책으로 속도를 늦춰 보세요.","도전으로 가득한 하루에는 평범한 피로를 무시하기 쉬워요. 쉬고 싶은 마음을 장애물처럼 여기지 마세요.","행동을 좋아하는 당신에게도 아무것도 이루지 않아도 되는 시간이 필요해요.","예상 밖의 일이 생기면 다시 움직이기 전에 잠시 숨을 고르세요. 그 짧은 틈이 평정을 되찾게 할 수 있어요.","무엇이든 빨리하려는 습관이 식사까지 따라올 수 있어요. 좋아하는 음식을 천천히 음미해 보세요.","기다림을 배운다고 전진을 포기하는 것은 아니에요. 결과보다 과정의 리듬을 즐기는 활동을 해 보세요.","프로젝트 때문에 잠을 뒤로 미루고 있다면 일상에 수면 시간을 다시 마련해 주세요."],"wisdom":["용기는 어떤 싸움을 선택할지 알 때 더 깊어집니다.","강한 추진력도 방향이 분명해야 멀리 나아갑니다.","생각하며 내딛는 한 걸음이 성급한 질주보다 멀리 갈 수 있습니다.","성숙함은 모든 경쟁에 뛰어들지 않을 줄 아는 것입니다.","조급함은 바람을 알려 주고 인내는 그 바람에 길을 열어 줍니다.","함께 나아가려면 첫걸음을 잠시 늦춰야 할 때도 있습니다.","솔직한 말은 경청할 자리를 남길 때 더욱 가치 있습니다.","진정한 출발은 움직이기 전, 의도를 분명히 하는 데서 시작됩니다."],"roast":["당신의 열정이 너무 앞서가면 주변 사람들은 계획을 이해할 시간조차 얻지 못해요.","모든 의견 충돌을 즉시 해결하려 하면 시간을 두고 나올 답을 기다릴 여유가 없어져요.","좋은 아이디어라도 실행 속도까지 강요하면 본래의 힘이 줄어들 수 있어요.","이기려는 욕구가 평범한 대화마저 불필요한 경쟁으로 바꿀 때가 있어요.","솔직함은 적절한 표현과 함께할 때 더욱 빛나요.","당신이 효율성이라 부르는 것은 가끔 질문을 끝까지 듣기도 전에 내린 결정 같아요.","일이 뜻대로 되지 않으면 잠시 쉬는 대신 에너지를 더 쏟아붓곤 해요.","프로젝트를 힘차게 시작하는 데 능하지만 차근차근 마무리하는 일에는 더 많은 인내가 필요해요."]},"funny":{"career":["직장에서 당신의 인내심은 로딩 화면만큼 짧아요. 새로고침을 여섯 번 누르고는 인터넷이 자신에게 시비를 건다고 생각하죠.","동료가 짧은 회의라고 말하면 당신은 반사적으로 결승선부터 찾습니다.","긴급이라고 표시된 업무를 보면 기분이 좋아져요. 드디어 자기 삶의 방식을 이해하는 문서가 나왔거든요.","두 사람이 복사기에 먼저 가려고 할 때 이미 경쟁은 시작돼요. 상대는 참가한 줄도 모릅니다.","말썽 부리는 스프레드시트와는 딱 5초 협상합니다. 그다음엔 닫기 버튼으로 협박하죠.","이 프로젝트는 분명 팀 작업이었어요. 그런데 당신은 이미 역할을 나누고 시작한 뒤 왜 아무도 못 따라오냐고 묻습니다.","상사가 천천히 하라고 하면 당신 귀에는 신기하게도 신기록을 세우라는 말로 들려요.","커피를 마시러 쉬는 건 좋죠. 단, 부서 사람들 중 제일 먼저 도착해야 합니다."],"love":["당신에게 낭만적인 데이트란 누가 먼저 도착하는지 겨루는 활동이에요. 미니골프마저 올림픽 종목이 됩니다.","상대방이 식당을 고르는 사이 당신은 메뉴 세 개를 보고 머릿속으로 이미 예약까지 마쳤어요.","당신의 다툼은 빨리 끝나요. 5분간 불꽃이 튀고 나면 아무 일 없었다는 듯 아이스크림을 권하죠.","애정은 당신을 대담하게 만들어요. 사랑스러운 문자를 보내자마자 휴대전화를 놓기도 전에 답장을 확인하죠.","나중에 보자는 말에는 당장 날짜와 시간, 서면 확약까지 요청합니다. 물론 웃으면서요.","촛불 아래 저녁 식사는 평화롭다가도 디저트를 고르는 순간 열띤 토론회로 변해요.","서프라이즈가 있다는 말이 끝나기도 전에 찬장에서 단서를 찾습니다. 기다림은 당신의 연애 사전에 없거든요.","누군가 장난을 치면 즉시 반격할 말을 준비해요. 그러고서야 애정 표현이었다는 걸 떠올립니다."],"wellbeing":["당신이 생각하는 이상적인 휴식은 기록 측정만 없앤 경주예요. 속도는 그대로죠.","명상을 하려고 하면 머릿속 모든 생각에 빨리 조용히 하라고 명령을 내립니다.","느긋한 산책도 계단 하나를 발견하는 순간 탐험대 출정식으로 변해요.","낮잠은 어딘가 수상해요. 재배치할 쿠션이 이렇게 많은데 왜 가만히 있어야 할까요?","조용히 있는 시간은 정확히 8초예요. 그 뒤에는 다른 사람들도 지루하냐고 묻습니다.","물 한 잔은 당신이 금방 끝낼 일 세 가지를 처리하는 동안 기다려요. 물잔도 이런 긴장감엔 동의한 적이 없습니다.","침착하게 호흡하는 건 좋은 생각이에요. 그걸 숨 오래 쉬기 대회로만 만들지 않는다면요.","잠깐 바람 쐬러 간다면 가족에게 미리 알려 주세요. 가벼운 산책이 목표 있는 등산으로 변할 수 있으니까요."],"wisdom":["용기는 넘치지만 기다리기 버튼은 아직 발견되지 않았어요.","진짜 챔피언은 토스터에게도 가끔 승리를 양보합니다.","인내심은 적이 아니에요. 답장이 조금 느릴 뿐이죠.","표지판과의 논쟁에서 이겨도 길은 바뀌지 않아요.","우주는 당신의 독촉 문자를 읽지 않고도 자기 속도로 움직입니다.","꿈을 향해 달리세요. 다만 문이 열려 있는지 먼저 확인하세요.","관객도 메달도 없는 조용한 승리 역시 승리예요.","침묵이 꼭 당신을 향한 도발은 아닙니다."],"roast":["당신의 내비게이션은 경로를 다시 계산한다는 말을 두 번 하지 못해요. 당신 성격을 아니까요.","과자 상자가 열리지 않으면 항복할 시간을 딱 10초 줍니다.","당신이 말하는 건설적인 대화란 모두가 집에 가려고 결국 당신 의견에 동의하는 대화예요.","초인종이 다 울리기도 전에 문 앞에 서 있어요. 택배 기사도 놀라죠.","보드게임도 반드시 이겨야 해요. 규칙은 첫 승리 뒤에 설명해도 된다고 믿거든요.","줄을 설 때마다 별도 대회를 엽니다. 누가 한숨을 가장 크게 쉴까요?","천천히라는 말은 당신에게 매 층 멈추는 엘리베이터만큼 못 미더워요.","짜증 나는 알림에는 화를 냈다가도 좋은 소식이면 즉시 용서합니다."]},"piquant":{"career":["당신의 조급함은 착수 회의 전에 프로젝트를 시작해 버렸어요. 프로젝트는 지금 법적 책임자가 누구인지 묻고 있습니다.","당신에게 마감 기한이란 개인적인 도발입니다. 달력은 경호원을 요청했어요.","생각 좀 해 보자는 동료의 말은 당신에게 공격 개시 신호죠. 생각은 책상 밑에 숨었습니다.","장애물을 보면 예절을 가르치겠다며 돌진해요. 그런데 그 장애물은 열려 있는 문이었습니다.","당신에게 너무 작은 경기는 없어요. 클립 나눠 주는 속도까지 재죠. 문구 창고는 메달 지급을 거부합니다.","당신의 번개 같은 결정 뒤에서 품질 관리팀은 떨어진 지침을 줍고 있어요. 망원경을 요청했답니다.","회의는 시작 30초만 지나도 지루해져요. 당신은 이미 투표하고 승리한 뒤 회의실을 떠났죠.","타고난 리더십은 프린터에게까지 발휘됩니다. 명령을 내리면 프린터는 외교적 용지 걸림으로 답하죠."],"love":["당신의 로맨틱한 솔직함은 정지 버튼 없는 경보기처럼 울려요. 섬세함은 발언 기회도 얻지 못했습니다.","둘이 볼 영화를 고르는 일도 당신에겐 논쟁 대회예요. 휴전 전에 엔딩 크레딧이 올라갑니다.","조금만 의견이 달라도 역사적인 연설처럼 자기주장을 펼칩니다. 쟁점은 머그컵 색깔이었는데요.","서프라이즈를 기다려 달라는 말에 이미 포장을 뜯었어요. 신비감은 사직서를 냈습니다.","다정한 대화도 마지막 말을 차지하기 위한 경주로 바꿔요. 상대는 차를 마저 마시려고 당신에게 승리를 양보합니다.","당신의 거창한 고백 뒤에서는 즉각적인 답변을 요구하는 작은 목소리가 들려요. 달력의 심장도 그런 마감은 못 맞춥니다.","답장이 늦으면 가설 네 개와 대응책 세 개를 세웁니다. 휴대전화는 중재자를 요청했어요.","넘치는 애정으로 두 달 치 일정까지 짜 버렸군요. 일요일이 독립을 선언했습니다."],"wellbeing":["당신의 휴식은 이웃보다 오래 가만히 있겠다는 도전으로 시작해요. 이웃은 경기 중인 줄도 모릅니다.","쉬려고 산책하면서 상상 속 모든 보행자를 추월해요. 나무들이 심판을 요청합니다.","소파가 5분간 품어 주자 이제는 야망이 부족하다고 나무라요. 쿠션들이 노조를 결성합니다.","줄이 천천히 움직이면 시공간과 협상을 시작합니다. 우주는 접수한 요청을 기각했어요.","초시계 없는 휴식은 수상하죠. 주전자 옆에 결승선을 설치해 버립니다.","당신의 폭발적인 에너지 앞에서 해먹이 차분함을 설명하려 해요. 당신은 그 말까지 끊습니다.","침묵을 견디지 못해 토론을 열려고 해요. 화분은 입장 표명을 거절했습니다.","행동 본능 덕분에 서랍 정리도 시간과의 경주가 됐어요. 서랍은 부탁한 적이 없습니다."],"wisdom":["당신의 인내심은 소집 통지서를 받기도 전에 떠났어요. 사건은 아직 종결되지 않았습니다.","무턱대고 돌진하는 게 아니라고요? 생각을 전투가 끝난 뒤에 정찰대로 보내는 것뿐이죠.","마지막 한마디는 트로피가 아니에요. 당신은 이미 받침대를 주문했지만요.","천천히 하라는 말은 당신 귀에 더 빨리 할 수 있다는 걸 증명하라는 뜻으로 들려요.","토스터를 이긴 승리는 공식 인정되지 않아요. 당신은 이의 신청서를 냈습니다.","당신의 용기 뒤에서 상식은 반사 조끼를 요구하고 있어요.","모든 장애물이 당신에게 시비를 거는 건 아니에요. 어떤 것은 그냥 가구입니다.","차례를 기다린다고 항복하는 건 아니에요. 당신의 백기는 아직 포장도 안 뜯겼지만요."],"roast":["당신의 인내심은 3초짜리 알림만큼 짧아요. 모래시계조차 연장을 신청합니다.","내비게이션이 다른 길을 제안했다고 선전포고를 했군요. 로터리는 방어 태세에 들어갔습니다.","친구들과 즐기려던 보드게임에 부정행위 조사위원회와 승리 찬가를 도입했어요.","커피머신이 늦어지면 적에게 하듯 말을 걸어요. 머신은 항의의 표시로 디카페인을 내놓습니다.","잘 안 열리는 문을 개인적인 모욕으로 받아들이죠. 그런데 당기세요라는 표지판이 불리한 증언을 합니다.","당신의 솔직함 뒤에서는 외교가 논쟁의 톨게이트에 갇혀 있어요.","빨간 신호등도 당신의 추진력에 대한 공개 비판이라고 생각해요. 교통 당국은 토론 중단을 요청합니다.","승부욕에 불타 고양이에게 달리기 시합을 신청했어요. 고양이는 일어나지도 않고 우승을 선언했습니다."]},"roastMy":["양자리인 당신은 조급한 사람이 아닙니다. 스스로 약속을 잡는 긴급 상황 그 자체죠. 엘리베이터 버튼을 일곱 번 누르고 건물에 팀워크가 부족하다고 비난합니다. 문이 열리자 뛰어들어요. 겨우 한 층 올라갈 예정이었는데요.","당신은 아무도 경기하지 않을 때에도 이기는 걸 좋아해요. 계단 오르기에 시간을 재고 모르는 사람을 추월한 뒤 참가해 줘서 고맙다고 하죠. 그 사람은 장바구니를 들고 걷고 있었을 뿐이에요. 올림픽 위원회는 당신의 신청서를 반려했습니다.","당신의 솔직함은 도서관에서 울리는 북만큼 섬세해요. 작은 장식품이 어떠냐는 질문에 사회적 논쟁을 시작하죠. 결국 꽃병을 설득해 자리를 옮깁니다. 벽은 논쟁 소음으로 민원을 제기하려고 합니다.","당신은 생각하기 전에 달려들고 그걸 용기라고 부릅니다. 가구가 길을 막자 목소리를 높여 협상하죠. 가구는 꿈쩍도 하지 않아요. 당신은 판정 논란 속에 가구의 승리를 인정합니다.","기능이 있는 물건이라면 무엇과도 다툴 수 있어요. 내비게이션과 알람 시계, 커피머신이 적군 목록에 올라 있죠. 어느 쪽도 싸움을 수락하지 않았습니다. 토스터는 국제적인 휴전을 요청했어요.","당신의 열정은 전염성이 있지만 아무도 소풍을 대회로 바꿔 달라고 하지 않았어요. 팀을 나누고 점수를 만들고 돗자리를 가장 잘 펼친 사람에게 상을 줍니다. 친구들은 그냥 앉아서 먹기 시작하죠. 당신은 스포츠 정신 부족을 고발합니다.","당신은 기다림을 거의 예술적으로 싫어해요. 계산대 앞의 세 사람이 거대한 지정학적 장애물로 변하죠. 효율성에 관한 연설을 머릿속으로 준비합니다. 막상 차례가 오자 뭘 주문하려 했는지 잊어버려요.","당신은 이미 지휘자가 있는 곳에서도 지휘권을 잡고 싶어 해요. 누군가 나들이를 준비하면 동선을 다시 짜고 더 역동적인 버전을 발표하죠. 일행은 엉뚱한 장소에 일찍 도착합니다. 당신은 최단 시간 기록을 자랑해요.","당신의 분노는 순식간에 치솟고 더 빨리 사라집니다. 누군가의 말에 열렬히 항의하다가 2분 뒤 활짝 웃으며 과자를 권하죠. 상대는 아직도 무슨 일로 다퉜는지 찾고 있어요. 당신의 홍보팀은 회의록을 삭제했습니다.","당신은 반대 의견을 들으면 공식 도전장을 받은 듯 행동해요. 친구가 다른 영화를 좋아하자 영화의 미래가 걸린 듯 자기 취향을 변호합니다. 친구는 조용히 쉬려고 결국 동의하죠. 당신은 대화의 위대한 승리라고 발표합니다."]},"taurus":{"classic":{"career":["당신의 꾸준함은 프로젝트를 단단하게 만들어요. 하지만 상황이 바뀌면 방법을 다시 살펴볼 줄도 알아야 해요.","업무 습관을 흔드는 제안을 받으면 바로 거절하기보다 차분히 평가할 시간을 가져 보세요.","장기적인 과제에는 당신의 끈기가 잘 어울려요. 작은 진전이라도 주변에 정기적으로 알려 주세요.","안정성을 추구하는 마음이 선택에 영향을 줍니다. 새로운 가능성을 닫아 버리지만 않는다면 강점이 될 거예요.","팀 전체가 급해질 때 당신의 침착함은 도움이 돼요. 다만 신중함과 제자리걸음은 구분해 보세요.","꼼꼼하게 일하려는 마음은 훌륭해요. 세부 사항만 끝없이 손보기보다 충분히 완성된 결과를 내는 편이 나을 때도 있어요.","업무 방식이 바뀌면 편하게 적응하기 위해 무엇이 필요한지 솔직히 설명해 보세요.","검증된 해결책을 선호하는 당신에게 작은 실험 하나가 새로운 가능성을 열어 줄 수 있어요."],"love":["당신의 성실한 애정은 반복되는 작은 행동에서 드러나요. 소중한 사람의 뜻밖의 바람도 존중해 주세요.","누군가와 가까워지면 오래갈 관계를 만들고 싶어 해요. 솔직한 대화가 그 믿음을 키워 줍니다.","함께하는 습관이 사랑을 표현하는 언어가 될 수 있어요. 다만 의무로 만들지는 마세요.","소박한 시간을 즐기는 마음이 관계를 풍요롭게 해요. 가끔은 상대방에게 계획을 맡겨 보세요.","의견이 다를 때 굳은 입장을 지키기보다 방어하지 않고 들어 볼 여유가 필요해요.","안정감이 필요하다는 마음을 다정하게 표현할 수 있어요. 주변의 모든 것이 그대로여야 하는 건 아니니까요.","당신은 실질적인 배려로 마음을 많이 전해요. 느끼는 감정을 말로도 전해 보세요.","관계가 새로운 단계에 들어섰다면 예전 모습에만 매달리지 말고 한 걸음씩 적응해 보세요."],"wellbeing":["당신에게 편안함은 중요해요. 바깥세상과 단절되지 않는 아늑한 공간을 만들어 보세요.","하루가 바빠질수록 좋아하는 음식을 여유롭게 즐기는 순간이 중심을 되찾게 해 줄 수 있어요.","익숙한 산책길도 주변을 천천히 살펴보면 특별한 휴식이 될 수 있어요.","반복되는 일상은 안정감을 줍니다. 부담 없는 작은 변화도 가끔 들여보세요.","요청이 많을 때는 쉬는 시간을 침범하는 일에 거절할 권리도 있어요.","좋아하는 소파에서 화면이나 할 일 목록 없이 진짜 휴식을 누려 보세요.","부드러운 음악과 편안한 조명, 서두를 필요 없는 시간처럼 단순한 감각적 즐거움도 소중해요.","해야 할 일이 너무 많다면 속도를 늦추고 마음을 편하게 해 주는 활동으로 돌아가 보세요."],"wisdom":["끈기는 방향을 바꿀 줄 알 때 지혜가 됩니다.","편안함은 피난처일 때 소중하지 경계선이 되어서는 안 됩니다.","굳은 신념이 대화의 문까지 닫을 필요는 없어요.","안정감은 적응하는 능력 속에서도 자라납니다.","현재를 음미한다고 시간을 붙잡아야 하는 건 아닙니다.","스스로 선택한 변화는 이미 소중한 것들과 공존할 수 있습니다.","예상 밖의 일이 일상의 따뜻함을 더 풍요롭게 할 수도 있습니다.","천천히 걸어도 계속 걷는다면 멀리 갈 수 있습니다."],"roast":["습관에 대한 애착이 지나치면 간단한 대안조차 복잡하게 느껴져 변화를 거부하게 돼요.","한 번 결심하면 타당한 근거조차 당신의 생각을 바꾸기 어려워요.","편안함만 추구하면 더는 맞지 않는 상황에 머물게 될 수 있어요.","어떤 시도든 확실한 보장부터 찾다 보면 좋아할 만한 새로운 것을 발견하지 못할 수 있어요.","좋은 것을 즐기는 데 집중하다 보면 때때로 자발적인 즐거움을 놓쳐요.","겉으로는 차분해 보여도 내면의 단호함이 다른 사람의 의견이 들어올 자리를 좁힐 때가 있어요.","모든 일을 예측 가능하게 만들려는 욕구는 즉흥적인 사람들을 지치게 할 수 있어요.","더 쉬운 방법이 나왔는데도 늘 하던 방식을 다듬는 편을 택하는군요."]},"funny":{"career":["당신의 책상에는 세 가지 우선순위가 있어요. 효율성, 편안한 의자, 그리고 내 컵은 절대 움직이지 말 것.","누군가 새 소프트웨어를 쓰자고 하면 기존 프로그램이 무슨 죄를 지었느냐고 묻습니다.","점심시간 회의는 당신의 업무 질서를 떠받치는 기둥에 대한 공격입니다.","안정감이 중요하죠. 가장 좋아하는 파일철은 너무 오래 함께해서 기념패를 달아 줘야 할 지경이에요.","새로운 방식이 나오면 시연과 2주간의 숙고, 그리고 스테이플러의 의견까지 요구합니다.","이 일정표는 쉽게 바뀌지 않아요. 당신이 승인했으니 거의 돌에 새긴 수준이거든요.","인내심이 필요한 업무엔 당신을 뽑아요. 하지만 자리를 옮겨야 한다면 채용부터 다시 시작해야 합니다.","제대로 일하는 걸 좋아하는 모습이 당신답죠. 다만 다른 방식으로도 잘할 수 있다는 사실을 믿기 어려울 뿐이에요."],"love":["당신의 주요 사랑 표현은 디저트를 나눠 주는 거예요. 단, 나눈다는 말이 마지막 한 입을 가져가도 된다는 뜻은 아니죠.","집에 누군가를 초대하면 소파 견학은 필수입니다. 그 훌륭한 성능에 대한 설명도 포함이고요.","완벽한 저녁은 맛있는 식사로 시작해 아무도 다시 나가자고 하지 않는 것으로 끝납니다.","당신에게 낭만이란 상대방이 가장 좋아하는 피자 토핑을 정확히 기억하는 일이에요.","계획이 바뀌어도 미소를 유지합니다. 원래 가려던 식당과 작별할 시간만 조금 필요할 뿐이에요.","둘만의 작은 습관이 너무 좋아서 무기한 정기 일정으로 등록하고 싶어 해요.","배려가 넘쳐서 쿠션 하나하나의 최적의 편안함을 알고 있어요. 사랑하는 사람은 그다음 순서죠.","즉흥적으로 하자는 말에 다정하게 대답해요. 물론이죠, 그런데 어느 일정표를 따를까요?"],"wellbeing":["당신이 앉는 소파 자리는 습관에 너무 잘 맞아서 어떤 옷보다도 편안해요.","산책 코스에는 자연스럽게 빵집과 앉아 쉴 수 있는 장소가 포함됩니다.","온도와 조명, 담요의 촉감까지 승인되어야 비로소 완전한 휴식이에요.","일요일의 거대한 목표는 리모컨을 잃지 않으면서 물건을 최대한 적게 옮기는 것입니다.","운동하러 가자는 제안에는 벤치에 앉아 경치를 감상하는 진지한 대안을 내놓아요.","잘못 놓인 쿠션 하나가 분위기를 망쳐요. 건축가처럼 진지하게 원상복구합니다.","바람 쐬는 건 좋지만 돌아왔을 때 앉을 자리가 있는지부터 확인해야 해요.","누가 낮잠을 방해하면 재판 중 방해받은 판사처럼 엄숙하게 한쪽 눈을 뜹니다."],"wisdom":["당신의 마음의 평화는 아무도 감자튀김에 손대지 않는 곳에서 시작됩니다.","좋은 계획이란 앉을 자리를 마련해 주는 계획입니다.","끈기는 고귀해요. 8년째 다른 식당을 거부하는 일은 조금 덜 고귀하지만요.","행복은 담요 한 장에 있을 수 있어요. 아무도 빌려 가지 않는다면 더 좋죠.","생각을 바꾸는 건 의무가 아니지만 한번 해 보면 어떨까요?","작은 모험은 소파에서 두 블록만 나가도 시작될 수 있어요.","음식이 식어 가면 당신의 인내심은 갑자기 왕관을 잃습니다.","편안하다고 해서 모든 가구를 영원히 보관할 필요는 없어요."],"roast":["식당 주인이 세 번 바뀌었는데도 충성심으로 옛 메뉴를 간직하고 있어요.","앱에서 주요 버튼 위치를 바꾸면 정식 항의 편지를 쓸까 심각하게 고민합니다.","당신의 전용 의자는 손님들이 앉기 전에 허락부터 구해야 할 정도로 유명해요.","마지막 케이크 한 조각은 외교적으로 민감한 사안입니다. 투표를 열고 거부권은 직접 챙기죠.","새 베개가 오면 엄격한 시험을 진행해요. 오래된 베개는 자신 있게 결과를 기다립니다.","그 편한 옷은 일요일을 너무 많이 함께 보내서 사실상 가구의 일부입니다.","아침 일과를 설명하는 말을 들으면 박물관에서 보호하는 전통을 소개받는 기분이에요.","누군가 지름길을 알려 줘도 늘 잘 다니던 길을 왜 버리냐고 묻습니다."]},"piquant":{"career":["당신의 고집은 한번 해 보자는 말을 외교 분쟁으로 만들었어요. 새로운 아이디어는 입국 비자를 기다립니다.","자기 방식을 박물관 학예사처럼 열렬히 지킵니다. 소프트웨어는 버전이 바뀌었는데 당신은 그대로예요.","사무실 자리 이동을 조약 위반으로 여깁니다. 의자는 대사관을 열었어요.","회의에서 새 방법을 제안하면 증빙 서류 세 장과 구버전 복귀 보증을 요구합니다.","잘 굴러가는 절차는 당신에게 신성합니다. 결함마저 문화유산 보호 대상이에요.","당신의 직장인다운 침착함 뒤에는 내 습관에 손대지 말라는 보이지 않는 표지판이 있죠. 신입사원들은 다른 출구로 나갔습니다.","지름길은 못 미더워요. 15년의 전통을 지킬 수 있는데 굳이 10분을 절약할 이유가 있나요?","이 책상은 과자 한 봉지까지 국경이 분명한 안정된 영토예요. 당신은 과자 상자 주위에 경계선을 그었습니다."],"love":["당신의 이상적인 로맨스는 애정과 담요, 손대지 않은 접시의 완벽한 조합입니다. 모험은 사전 예약이 필요해요.","둘만의 습관을 문화재처럼 지켜요. 저녁 식사를 한 시간 옮기려면 국민투표를 해야 합니다.","나눔이 아름다운 가치라는 데 동의하죠. 마지막 한 입이 남을 때까지는요. 그 순간 재산권을 발견합니다.","새로운 장소에 가자는 제안을 받으면 가는 내내 단골 식당의 장점을 설명합니다.","깜짝 저녁이 감동적이긴 해요. 다만 소파 전용 자리가 위험하다면 로맨스도 설계도를 제출해야 합니다.","당신의 한결같은 다정함 뒤에서 최애 쿠션은 국보급 가구보다 더 철저한 보호를 받습니다.","다정한 말은 좋지만 마지막 디저트 조각을 고르는 중에는 삼가 주세요.","당신의 충성심은 모범적이에요. 같은 영화와 같은 소파 자리, 같은 담요 논쟁으로 늘 돌아오니까요."],"wellbeing":["당신의 휴식에는 주소와 담요, 지정석이 있어요. 가구들은 이미 거주지 등록을 마쳤습니다.","낮잠을 국제 정상회담처럼 지켜요. 방해하려면 서면 신청서 세 부가 필요합니다.","소파는 당신을 대신해 회의에 참석할 정도로 습관을 잘 알아요. 다만 거실 밖으로 나가는 건 거부합니다.","누가 즉흥적인 산책을 제안하면 신발을 원래 자리에 둘 수 있는지부터 묻습니다.","따뜻한 음료는 큰 위안이 되죠. 하지만 늘 쓰던 컵이 점령당했다면 다른 컵은 국경을 넘지 못해요.","당신의 안락함을 향한 사랑 뒤에는 담요의 최적 온도를 지키는 군대가 있어요. 온도조절기는 조용히 복종합니다.","평화로운 일요일은 특기죠. 아무도 깜짝 일정을 넣지 않는다는 조건으로요. 달력은 봉인됐습니다.","유연성을 연습한다며 쿠션을 바꿔 보려 해요. 위원회는 아직 제안을 심의 중입니다."],"wisdom":["당신의 고집은 상식에 평생 구독을 신청했어요. 상식은 청구서에 이의를 제기합니다.","당신은 의견을 바꾸지 않아요. 다른 사람들이 지칠 때까지 기다리도록 허락할 뿐이죠.","편안함은 아름다운 가치예요. 하지만 헌법으로 만들려면 쿠션 의회가 필요합니다.","세상이 움직이면 당신은 먼저 안락의자에 브레이크가 있는지 확인해요.","습관은 자연법칙이 아니에요. 그런데 당신은 이미 민법전을 써 놨군요.","당신의 평온함 뒤에는 마지막 타르트 조각을 지키는 방위위원회가 있습니다.","새로운 것들이 문을 두드리면 소파의 추천서를 가져오라고 하죠.","앞으로 나아간다고 슬리퍼를 배신하는 건 아니에요. 그래도 공증부터 요구하겠죠."],"roast":["당신의 소파에는 전용 좌석과 손님용 내규가 있어요. 쿠션들이 법을 집행합니다.","당신의 변화 거부는 꾸준함의 극치예요. 꿀병의 새 라벨 하나가 국가 비상사태가 됩니다.","마지막 치즈 조각은 음식이 아니에요. 삼엄하게 감시되는 전략 자산입니다.","누군가 담요에 손대면 반납 확인서를 요구해요. 담요는 망명을 신청했습니다.","새로운 제안이 당신의 방탄문 같은 눈빛에 부딪칩니다. 호기심마저 돌아서요.","전설적인 침착함 뒤에는 리모컨의 정확한 자리를 지키는 경비원이 있습니다.","식사는 나누는 시간이죠. 나누는 것이 남의 접시 음식일 때는요.","습관에 대한 충성심이 너무 깊어서 낡은 쿠션마저 교체받을 권리를 요구합니다."]},"roastMy":["황소자리인 당신의 소파는 더 이상 가구가 아닙니다. 하나의 자치 행정구역이죠. 자리와 담요, 손님 출입 절차가 따로 있어요. 누군가 실수로 앉자 쿠션 위원회가 즉시 퇴거 명령을 내립니다.","당신의 고집은 문에 자물쇠를 하나 더 단 모습과 같아요. 실용적인 제안을 받으면 증거와 추천서, 3계절의 시험 기간을 요구하죠. 결국 아이디어는 물러납니다. 당신은 기존 방식이 다시 옳았다고 선언해요.","맛있는 걸 좋아하죠. 특히 마지막 한 조각을 아무도 탐내지 않을 때요. 태연한 눈으로 접시를 감시하다가 전략적으로 위치를 바꿉니다. 친구가 나눠 먹자고 하자 국제 협력의 한계를 새롭게 깨닫습니다.","당신은 새로운 것에도 열려 있다고 주장해요. 식당을 바꾸는 데도 동의하죠. 같은 자리와 같은 메뉴, 같은 분위기만 있다면요. 간판이 다르다는 것만으로도 대단한 모험입니다. 접시는 용기 훈장을 요구해요.","당신의 안락함에는 헌법이 있고 최고 수호자는 바로 당신입니다. 슬리퍼는 소파 옆에 대기하고 담요는 규정대로 접혀 있으며 차는 정시에 나와요. 손님이 창문을 엽니다. 당신은 직물 비상대책회의를 소집합니다.","평범한 습관도 명변호사처럼 변호할 수 있어요. 리모컨을 몇 센티미터 옮기려는 사람에게 그 자리의 역사를 설명합니다. 10분 뒤 상대는 포기해요. 리모컨은 당신의 헌신에 감사를 표합니다.","당신은 느리게 움직이는 게 아닙니다. 공식적인 안락함의 속도를 존중할 뿐이죠. 모두 현관에서 기다리는데 당신은 여행용 쿠션을 찾고 있어요. 그냥 산책이라는 말을 듣자 앉을 자리가 있느냐고 묻습니다.","당신의 완벽한 일요일에는 어떤 깜짝 계획도 들어올 수 없어요. 집으로 배달되는 놀라움이라면 예외겠죠. 즉흥적인 활동을 제안받으면 담요를 정치 고문처럼 바라봅니다. 담요가 반대해요. 당신은 가족 만장일치 결정이라고 발표합니다.","당신은 누군가 자기 몫을 탐낼 때까지는 너그러운 사람입니다. 조언과 담요, 맛집 정보도 기꺼이 나눠 줘요. 그러다 손 하나가 과자에 다가옵니다. 우호 조약은 무기한 정지됩니다.","당신의 안정 사랑은 인테리어와 안 어울리는 낡은 의자도 보존하게 만들어요. 역사와 영혼, 거주권이 있다고 주장하죠. 새 의자는 문밖에서 기다립니다. 오래된 의자는 방금 거실 장관으로 임명됐어요."]},"gemini":{"classic":{"career":["당신의 호기심은 남들이 따로 보는 아이디어를 연결해 줍니다. 유망한 생각을 깊이 발전시킬 시간도 마련해 보세요.","여러 프로젝트가 한꺼번에 나타나면 열정이 분산될 수 있어요. 새 일을 맡기 전에 우선순위를 정해 보세요.","업무 대화가 창의력을 자극할 수 있어요. 이후 진행을 위해 분명한 결정도 남겨 두세요.","다양한 업무가 당신의 사고를 활발하게 해요. 단순한 틀이 시작한 일을 마치는 데 도움이 될 거예요.","복잡한 문제를 보면 여러 각도를 탐색하죠. 그다음 한 가지 해법을 선택해 충분히 시도해 보세요.","설명하는 재능만큼 동료들의 질문에도 세심하게 귀를 기울이면 더 빛나요.","새 정보가 처음 생각과 다르다면 유연하게 바꿀 수 있어요. 왜 생각이 달라졌는지도 전해 주세요.","인맥을 넓히면 시야가 커져요. 모든 새 만남을 좇기보다 몇몇 관계를 깊게 가꿔 보세요."],"love":["당신은 대화를 통해 친밀감을 키워요. 모든 침묵을 말로 채우지 않고 받아들이는 여유도 가져 보세요.","누군가 궁금해지면 질문이 쏟아져요. 대화가 면접이 아니라 서로 나누는 시간이 되게 해 보세요.","늘 새로움이 있는 관계가 당신을 설레게 해요. 변함없는 마음도 그만큼 소중할 수 있어요.","가벼운 유머는 가까워지는 데 도움이 돼요. 상대가 진지한 이야기를 원하는 순간도 알아차려 주세요.","감정이 엇갈릴 때는 잠시 물러서서 일시적인 호기심과 오래가는 바람을 구분해 보세요.","새로움을 좋아하는 마음은 관계에 생기를 줍니다. 이미 함께 만든 작은 습관도 잊지 마세요.","생각이 바뀌었다면 상대가 짐작하게 두지 말고 그 과정을 간단히 설명해 주세요.","진심을 말하는 일은 자연스럽죠. 답변을 미리 준비하지 않고 듣는 경험이 또 다른 친밀함을 줄 거예요."],"wellbeing":["늘 움직이는 생각에도 고요한 시간이 필요해요. 정한 휴식 시간에는 자극을 조금 줄여 보세요.","아이디어가 너무 많아질 때 몇 줄 적어 보면 생각의 실마리를 찾는 데 도움이 될 수 있어요.","휴대전화 없이 짧게 걷는 동안에도 당신의 호기심은 충분히 즐거울 수 있어요.","관심사가 다양해 활력이 넘쳐요. 한 가지 활동만 천천히 즐기는 시간도 마련해 보세요.","대화로 가득한 하루를 보냈다면 자기 속도에 맞춰 잠시 고요함을 찾아보세요.","끊임없이 새로운 것을 찾고 싶어도 조용한 저녁 동안은 기다려도 괜찮아요. 모든 것을 지금 알아야 할 필요는 없어요.","잠들기 전까지 생각이 이어진다면 편안한 저녁 습관을 만들어 보세요.","알림에서 벗어나 잠시 쉬면 진정한 관심과 단순한 산만함을 구별하기 쉬워질 거예요."],"wisdom":["호기심은 한곳에 머무를 때 더욱 깊어집니다.","서로 반대되는 생각도 선택을 비출 수는 있지만 대신할 수는 없습니다.","말은 상대가 답할 자리를 남길 때 사람을 가깝게 합니다.","모든 길을 탐색한다고 동시에 다 걸어야 하는 건 아닙니다.","자유로운 정신은 스스로 선택한 일을 마칠 줄도 압니다.","생각을 바꾸는 건 강점이 될 수 있어요. 이유를 설명할 수 있다면요.","새로움은 문을 열고 집중은 그 안에 머무르게 합니다.","끝까지 듣는 일은 가장 아름다운 호기심일 수 있습니다."],"roast":["호기심이 너무 멀리 뻗으면 정작 중요한 프로젝트는 결론을 기다리게 돼요.","질문을 하나 던질 때 이미 세 가지 답을 준비해 놓고 상대의 대답은 놓치곤 해요.","관점을 쉽게 바꾸다 보니 주변 사람들은 당신의 진짜 입장이 무엇인지 헷갈릴 수 있어요.","새로운 것만 찾다 보면 이제 막 흥미로워지는 일을 너무 빨리 떠날 수 있어요.","침묵 앞에서는 눈빛 하나면 충분한 자리에 말을 더하는 경향이 있어요.","모든 것을 설명하려는 습관은 조용한 동행을 좋아하는 사람을 지치게 할 수도 있어요.","선택지가 여러 개라고 결정을 미뤄도 그 선택들이 더 좋아지는 것은 아니에요.","수많은 대화를 여는 건 자연스럽지만 한 대화를 끝까지 이어가는 데는 노력이 필요해요."]},"funny":{"career":["업무용 브라우저에 탭 열일곱 개가 열려 있어요. 전부 왜 열었는지 안다고 주장하지만 음악이 나오는 탭만은 못 찾습니다.","회의록을 부탁받으면 조연과 반전까지 등장하는 흥미진진한 연대기를 작성해요.","새 앱을 발견하면 30분간 푹 빠집니다. 그러고는 똑같은 기능을 약속하는 다른 앱을 발견하죠.","커피 시간은 사실 사무실 소식 수집 시간이죠. 커피는 식어 가지만 정보망은 정상 가동 중입니다.","간단한 질문에도 가능한 답 세 가지와 미묘한 차이, 아무도 요구하지 않은 네 번째 답을 내놓아요.","프로젝트가 잘 나가다가 더 흥미로운 아이디어 하나가 복도를 지나가면 갑자기 집중이 옮겨갑니다.","동료가 이야기를 꺼내기도 전에 배경과 목격자, 옆 부서의 버전까지 이미 알고 있죠.","여러 일을 동시에 하는 게 재미있어요. 열다섯 가지 일 아래 깔린 첫 번째 일을 마치는 것이 진짜 보물찾기입니다."],"love":["데이트는 상대에 대해 말해 달라는 질문으로 시작해요. 두 시간 뒤에도 당신은 자기 소개 일화의 도입부를 이야기하고 있죠.","어디서 먹을지 물으면 식당 세 곳을 추천했다가 마음을 바꾸고 그사이 도자기 수업까지 찾아냅니다.","다정한 대화도 화산 이야기에서 이웃 이야기, 이불 접는 최선의 방법으로 이어질 수 있어요.","깜짝 이벤트를 너무 좋아해서 직접 계획을 바꿔 놓고는 놀란 척하기도 해요.","보고 싶다는 메시지에 답하려다가 오늘 있었던 일 여섯 가지를 순서대로 이야기합니다.","모든 걸 이야기하는 모습이 사랑스럽죠. 다만 상대는 이제 두 쉼표 사이에 나 먼저 잘게요를 끼워 넣는 기술을 익혔습니다.","휴대전화 없는 저녁을 약속하자마자 흥미진진한 기사를 발견해요. 물론 이번 한 번만은 예외죠.","무슨 생각 하냐는 질문을 받으면 의자를 준비하라고 하세요. 답변은 여러 장으로 구성돼 있으니까요."],"wellbeing":["눈을 감고 쉬려는 순간 머릿속에 새 창이 열립니다.","머리를 비우려고 산책에 나갔다가 아이디어 열두 개와 들을 팟캐스트 제목을 가지고 돌아와요.","침묵하는 시간도 흥미롭다고 생각하지만 시작하기 전에 모임 사람들과 장점을 토론하고 싶어 해요.","휴대전화를 내려놓으면 휴식이 시작돼요. 다른 데서 무슨 일이 일어나는지 궁금해지는 순간 끝나지만요.","책더미를 보면 네 권을 동시에 읽기 시작합니다. 작가 모두를 존중하는 당신만의 방법이죠.","따뜻한 차를 마시는 조용한 순간은 완벽해요. 그런데 갑자기 펭귄에 관한 중요한 질문이 떠올랐네요.","아무 생각 없이 호흡하는 건 쉬워 보여요. 당신의 머릿속은 이미 그렇지 않다는 발표를 준비합니다.","평화로운 저녁을 보낸다면 분 단위 일정을 공유할 단체 채팅방만은 만들지 마세요."],"wisdom":["당신의 머릿속에는 천 갈래 길이 있지만 완료 버튼은 하나뿐이에요.","한 문장에서 상반된 의견 두 개를 말하면 이미 원탁회의입니다.","침묵에 굳이 자막을 달아 줄 필요는 없어요.","새 아이디어를 들이기 전에 옛 아이디어부터 상자 밖으로 꺼내 보세요.","호기심은 모험이지 열린 탭 수를 겨루는 대회가 아니에요.","마음을 바꿔도 괜찮아요. 세상에 알려 주는 건 여전히 예의죠.","자세히 안다고 전부 다 말해야 하는 건 아닙니다.","경청은 다음 일화를 준비하는 일을 멈출 때 시작됩니다."],"roast":["동네에서 당신이 아는 소문이 너무 많아서 주민들이 주간 뉴스레터 발행을 부탁할 지경이에요.","짧게 말할게요라는 말을 들으면 친구들은 휴대전화 충전기를 찾기 시작합니다.","읽기 목록에는 왜 저장했는지 잊었는데도 제목만 여전히 흥미로운 기사가 가득해요.","당신이 할 말 없다는 문장은 건너뛸 수 없는 광고보다 짧게 지속됩니다.","영화를 고를 때 코미디를 지지하다가 다큐멘터리를 추천하고 결국 드라마를 보자고 하죠.","2분짜리 음성 메시지에도 서론과 곁가지 이야기, 다음 메시지를 예고하는 결론이 들어갑니다.","모임이 끝나자마자 누군가에게 전하려고 최고의 대화들을 벌써 새롭게 구성하고 있어요.","마지막 말을 할 기회를 주면 완전히 새로운 화제를 시작하는 데 사용합니다."]},"piquant":{"career":["당신의 수다는 팀 회의를 연속극으로 바꿨습니다. 회의는 지난 시즌 줄거리 요약을 요청해요.","한 전략을 확신에 차서 주장하다가 10분 뒤 정반대 전략을 지지합니다. 화이트보드는 독립 심판을 요구했어요.","메시지 하나에도 답변 여섯 개와 여담 세 개, 예기치 않은 질문 하나가 떠올라요. 보내기 버튼은 초안 밑에 파묻혔습니다.","동료가 두 마디로 말해 달라고 하자 괄호 안의 말은 글자 수에 포함되느냐고 묻습니다. 동료는 이미 노트북을 닫았어요.","새 아이디어는 다음 아이디어가 나타날 때까지만 사랑받아요. 버려진 프로젝트들이 행정 지원 모임을 결성했습니다.","당신의 업무 호기심 뒤에서는 탭 스무 개가 우선순위를 놓고 싸웁니다. 브라우저는 지휘자를 요청했어요.","당신 덕분에 정보가 빨리 돌아요. 사실 확인보다 먼저 돌 때도 있죠. 사무실 복도는 반론권을 요구합니다.","즉흥 발표 능력은 놀랍습니다. 발표 도중 결론을 바꿔 버리니까요. 슬라이드는 따라가기를 거부했어요."],"love":["당신의 매력은 너무 빠르게 말해서 침묵이 자기소개할 틈도 없어요. 미소 하나에도 음성 해설이 붙습니다.","질문을 열정적으로 던지고 상대가 할 답변까지 직접 해요. 연애 면접에서 사회자가 실종됐습니다.","짧은 대화도 세 갈래로 나뉩니다. 맞은편 사람은 탭을 닫을 창을 찾고 있어요.","진심으로 어떻게 생각하냐는 질문에 정반대 답 두 개를 똑같은 미소로 내놓습니다. 심사위원단이 중재자를 요청합니다.","낭만적인 나들이도 다른 아이디어가 나타날 때까지만 마음에 들어요. 달력은 지금 누가 누구를 만나는지 묻습니다.","당신의 열정적인 고백 뒤에는 다음 일화가 대기하고 있어요. 현재의 감정에는 대기 번호표가 발급됐습니다.","당신의 작은 질문이라는 메시지는 자료집 한 권으로 끝나요. 휴대전화는 초과근무 수당을 요구합니다.","당신의 마음은 깊은 대화에 설레다가도 이웃집 강아지를 보고 산만해져요. 대화가 중간 휴식을 요청했습니다."],"wellbeing":["휴식 활동 하나를 고르려고 머릿속 탭 열다섯 개를 열었군요. 정작 휴식은 휴지통에 있습니다.","아무것도 하지 않기로 하고 아무것도 하지 않는 가장 좋은 방법을 검색합니다. 휴식은 브라우저를 닫아 버렸어요.","침묵이 당신을 끄는 시간은 딱 8초예요. 그러고는 새롭고 재미있는 소식이 없느냐고 묻습니다.","산책하다가 우회로 세 곳과 즉흥적인 대화 두 번을 거쳐 동네 전체를 순회 강연장으로 만들어요.","자극 없는 휴식은 수상하죠. 오늘 이용 가능한 생각 목록부터 확인합니다.","사교적인 에너지 뒤에서 담요가 당신을 묵묵히 기다려요. 정확한 예약 시간은 포기했답니다.","차분한 음악도 당신의 호기심을 견디지 못해요. 두 곡 뒤에는 피아노의 역사를 조사 중이니까요.","평온한 저녁은 책 한 권으로 시작했어요. 지금은 책갈피 제작법에 관한 영상 일곱 편을 보고 있군요."],"wisdom":["당신 머릿속엔 의견이 너무 많아서 거수투표도 일주일이 걸려요.","당신은 화제를 바꾸는 게 아니에요. 이전 토론을 종료하지 않은 채 새 토론을 설립하죠.","침묵도 때로는 답이에요. 당신은 거기에 자세히 설명해 달라고 요청했습니다.","아이디어 하나가 스쳐 지나갈 때 이미 반대 방향에서 셋이 달려오고 있어요.","우아하게 이야기했다고 정보가 소문이 아닌 건 아니에요. 복도가 증언하겠답니다.","당신의 짧은 문장 뒤에는 늘 부록이 있어요. 부록에도 별도의 서론이 있습니다.","모든 근거를 한자리에 소집하지 않으면 선택은 쉬워져요. 하지만 당신의 회의는 정족수 미달입니다.","모두를 아는 건 유용해요. 당신은 그들의 삶까지 드라마 시즌별로 저장했죠."],"roast":["짧게 말하겠다는 당신의 대화는 도입부가 끝나기도 전에 달력이 다음 달로 넘어갔어요.","서로 반대되는 의견 둘을 목줄에 묶인 개 두 마리처럼 끌고 갑니다. 개들은 서로 반대쪽으로 달리고 싶어 해요.","브라우저 탭이 서른 개예요. 어느 탭도 최초 검색어를 기억하지 못합니다.","일화에 세부 사항이 부족하면 직접 덧붙입니다. 목격자들은 자기 이야기를 알아보지 못해요.","간단한 질문 하나에 답 네 가지와 보너스 해설을 줍니다. 설문지는 회의장을 떠났습니다.","호기심 많은 당신 뒤에서는 다음 버튼이 완료 버튼보다 훨씬 잘 작동해요.","당신의 입을 거치는 소문은 급행열차만큼 빠릅니다. 비밀유지는 아직 플랫폼에서 기다려요.","당신의 집중력은 모든 방해 요소를 구독했어요. 공급업체조차 핵심 서비스가 뭔지 모릅니다."]},"roastMy":["쌍둥이자리인 당신은 의견 두 개를 가진 게 아닙니다. 불안정한 의견 연합을 이끌고 있죠. 아이디어마다 장관 자리를 요구하고 앞선 생각을 뒤집은 뒤 즉각 개혁을 발표합니다. 당신은 그걸 소리 내어 생각한다고 부르죠. 머릿속에서는 의회 운영 규칙을 요구하고 있어요.","당신은 짧은 일화를 국제 대서사시로 만들어요. 서막과 조연 네 명, 과거로 돌아가야 이해되는 장면까지 나옵니다. 친구들은 최초의 질문을 잊었죠. 당신은 중요한 세부 사항 하나가 더 남았다고 발표합니다.","당신의 브라우저에는 탭이 아니라 도시 하나가 들어 있어요. 창마다 흥미로운 발견을 약속하며 자리를 내주지 않죠. 아침에 열었던 페이지를 찾고 있습니다. 검색엔진마저 도시 지도를 요청합니다.","당신은 놀라운 효율로 금세 지루해져요. 첫 번째 활동에 열광하다가 두 번째, 세 번째를 동시에 시작합니다. 하루가 끝날 때는 스무 개의 시작과 내일 할 일 목록이 남죠. 끝나지 못한 프로젝트들이 권익보호협회를 만들었습니다.","당신의 호기심에는 국경도 정지 버튼도 없어요. 누군가 주말 어땠냐고 물었더니 3분 뒤 그 사람 동네의 역사를 탐구하고 있죠. 상대는 영화 이야기를 하려던 참이었어요. 당신의 인터뷰는 기록물 담당 부서의 승인을 기다립니다.","당신은 너무 유창하게 말해서 상대들이 자기 차례를 되찾으려고 고개만 끄덕여요. 그런데 당신은 그걸 더 설명해 달라는 신호로 받아들입니다. 모임에서는 발언 요청용 깃발을 도입하죠. 당신은 즉시 깃발 색깔을 두고 토론을 제안합니다.","당신은 한 의견을 열정적으로 지지하다가 커피가 식기도 전에 정반대 의견을 받아들여요. 변화를 지적하면 둘은 상호보완적이라고 설명하죠. 커피는 식어 갑니다. 사전은 합의라는 단어의 정의를 다시 찾고 있어요.","당신의 소문 감각은 동네 신문도 부러워할 수준이에요. 누가 화분을 바꿨는지, 이웃이 왜 의자를 옮겼는지, 동료 둘이 몇 시에 웃었는지 전부 알죠. 절대 퍼뜨리지 않겠다고 맹세합니다. 그러고는 이런 말부터 해요. 이건 말하면 안 되는데요.","당신은 오후 한 번에 온 세상을 발견하고 싶어 해요. 요리를 시작하고 먼 나라 기사를 읽고 서랍 수리 영상까지 틀죠. 저녁이 다가오는데 서랍은 열려 있고 여행은 상상 속에서 예약됐습니다. 일정표는 통역사를 요청합니다.","당신의 생각은 너무 빠르게 옮겨 다녀서 대화들이 상상 속 안전모를 써야 해요. 실용적인 질문이 철학 토론으로, 휴가 추억으로, 과자 비교로 이어집니다. 마지막엔 아무튼이라고 말하죠. 아무도 요약해 달라고 할 용기가 없습니다."]},"cancer":{"classic":{"career":["당신은 팀의 작은 긴장까지 잘 알아차려요. 그렇다고 분위기를 혼자 책임질 필요는 없어요.","동료가 어려운 하루를 보내고 있다면 당신의 경청이 큰 도움이 될 수 있어요. 자신의 여유도 소중히 지키세요.","업무상의 의견이 예상보다 오래 마음에 남을 수 있어요. 결론을 내리기 전에 맥락을 다시 살펴보세요.","지난 경험에 대한 기억은 선택에 도움이 돼요. 다만 오래된 실망이 새로운 시도까지 막게 두지는 마세요.","분위기가 변하면 직감적으로 알아차려요. 직접 대화해 그 느낌이 맞는지도 확인해 보세요.","다른 사람을 보호하려는 마음은 신뢰를 키워요. 각자가 직접 시도하고 결정할 자리도 남겨 주세요.","팀 프로젝트가 소중하다면 기대하는 바를 분명하게 말해 주세요. 말하지 않아도 알아주기를 바라지 마세요.","따뜻한 근무 환경은 당신에게 중요해요. 요청이 지나치게 많을 때는 경계를 세우는 연습도 필요합니다."],"love":["당신의 깊은 애착은 수많은 작은 배려로 표현돼요. 상대방이 직접 말하는 필요도 존중해 주세요.","행복한 추억이 떠오르면 현재를 평가하는 기준 대신 소중한 선물처럼 나눠 보세요.","서툰 한마디가 오래 마음에 남을 수 있어요. 침묵으로 물러서기 전에 뜻을 물어보는 편이 나을 수 있어요.","가족과 가까운 관계는 당신의 삶에서 큰 자리를 차지해요. 각자 자기 방식대로 함께할 공간을 마련해 주세요.","잠깐의 거리감에도 상상력이 빈칸을 채울 수 있어요. 간단히 물어보면 분명해지는 경우가 많아요.","위로가 필요하다는 마음을 솔직히 말해 보세요. 서로가 눈치로 맞히지 않아도 될 때 다정함을 전하기 쉬워집니다.","이해받지 못한다고 느낀다면 실망 속에 숨기보다 무엇이 마음을 건드렸는지 이야기해 보세요.","누군가를 돌보는 건 아름다운 사랑의 방식이에요. 모든 것을 직접 챙기지 않아도 다른 사람의 배려를 받아들여 보세요."],"wellbeing":["분위기에 민감한 당신에게는 익숙한 장소에서 보내는 휴식이 특히 소중해요.","감정이 쌓일 때 잠시 조용한 시간을 가지면 그 감정에 휩쓸리지 않고 바라볼 수 있어요.","좋아하는 장소 근처를 산책하면 편안한 연속성을 느낄 수 있어요.","향수는 때로 따뜻하게 다가와요. 추억을 즐기되 지금의 기쁨도 놓치지 마세요.","소중한 사람들의 부탁 앞에서도 자신을 위한 시간을 남겨 둘 권리가 있어요.","집을 아늑하게 꾸미는 일이 마음을 달래 줄 수 있어요. 다만 의무로 만들지는 마세요.","많이 지친 날이라면 속도를 늦추고 소박하고 편안한 저녁을 보내 보세요.","다른 사람의 안부를 묻는 일은 자연스럽죠. 오늘 자신에게 필요한 것도 물어보세요."],"wisdom":["다정함은 거절할 줄 알 때 더욱 단단해집니다.","과거는 마음을 따뜻하게 할 수 있지만 모든 선택을 지휘할 필요는 없어요.","감정은 귀 기울일 가치가 있지만 혼자 결정을 내려야 하는 건 아닙니다.","다른 사람을 보호한다고 그들의 침묵까지 짊어질 필요는 없어요.","기대하는 바를 분명히 말할 때 신뢰가 자라납니다.","안락한 집에도 각자가 숨 쉴 공간이 필요합니다.","직관에 귀 기울이되 현실과 맞춰 볼 때 더 정확해집니다.","자신을 돌본다고 다른 사람을 향한 사랑이 줄어들지는 않습니다."],"roast":["감정과 연결된 기억이 오래된 사소한 일을 현재를 판단하는 고정 기준으로 만들 수 있어요.","어떤 말에 상처를 받았을 때 말없이 있으면 다른 사람은 설명이 필요한 이유를 추측해야 해요.","소중한 사람을 너무 열심히 돌본 나머지 그들이 실제로 도움을 원하는지 묻지 않을 때가 있어요.","향수가 과거를 지나치게 아름답게 만들어 새로운 것을 실제보다 덜 반갑게 보게 할 수 있어요.","평범한 거리감에도 존재하지 않는 숨은 뜻을 찾을 때가 있어요.","자기 세계를 지키려는 마음이 관계를 위협하지 않는 변화까지 경계하게 할 수 있어요.","주변의 긴장을 감지하면 자신이 책임질 필요 없는 감정까지 떠안기도 해요.","다른 사람을 잘 위로하지만 정작 자신에게 무엇이 필요한지 말하기는 더 어려울 때가 있어요."]},"funny":{"career":["당신의 감정 레이더는 닫힌 문 너머 동료의 한숨까지 포착해요. 벌써 차와 상상 속 담요를 들고 달려갑니다.","상사가 느낌표 없이 고마워요라고 쓰면 오전 내내 그 메시지의 열정 수준을 분석하죠.","오래된 팀 사진 한 장이면 이직과 생일, 환영회까지 전부 돌아보는 추억 여행이 시작됩니다.","커피머신이 고장 났나요? 당신은 기계보다 팀의 사기가 걱정돼 휴게실에 위로 모임을 열어요.","새 인턴이 오면 너무 세심하게 환영해서 첫날부터 과자와 휴지의 위치까지 모두 알게 됩니다.","완료된 문서가 벌써 그리워요. 지난 파일 이름을 혹시 몰라서 보관합니다. 함께한 모험의 흔적이니까요.","누군가 괜찮아요라고 하면 두 단어 사이에 숨은 한숨까지 듣고 바로 면담을 제안해요.","직장 분위기를 돌보는 게 당신답죠. 심지어 새잎이 나올 때마다 팀과 함께 축하하는 화분도 있어요."],"love":["당신의 마음은 국립도서관처럼 추억을 분류해요. 첫 영화관 티켓에는 아마 전용 보호 커버가 있을 거예요.","메시지에 이모지가 없으면 애정 서비스가 잠시 점검 중인지 걱정합니다.","완벽한 로맨틱한 저녁은 첫 데이트 영화를 다시 보고 상대가 잊은 모든 장면을 설명하는 거예요.","당신의 다정함은 밥 충분히 먹었어요라는 질문에서도 드러나요. 놀라운 확신으로 여러 번 묻죠.","나중에 봐요라는 말에는 나중의 공식 정의와 정서적 온도가 몇 도인지 알고 싶어 해요.","손수 만든 선물을 받으면 포장지까지 간직해요. 그 종이에도 아름다운 사연이 있었으니까요.","익숙한 노래가 나오자마자 처음 들었던 장소와 날씨, 감정까지 줄줄이 설명합니다.","누군가 중요한 날짜를 잊어도 아무 말 하지 않아요. 대신 눈빛이 단독 강연을 시작할 듯하죠."],"wellbeing":["당신이 생각하는 위로는 부드러운 담요, 따뜻한 음료, 이미 줄거리까지 외운 영화 한 편이면 충분해요.","서랍을 정리할 때 오래된 종이마다 대체 불가능한 추억이라는 직함을 달고 등장합니다.","옛 학교 앞을 지나면 머릿속에서 서정적인 음악이 흐르는 다큐멘터리가 즉시 상영돼요.","쉬는 건 어렵지 않아요. 다만 다른 사람들도 나만큼 편안한지 걱정하기 시작하면 이야기가 달라지죠.","바쁜 하루 끝에는 집에 있자고 제안합니다. 소파는 오랜 여행에서 돌아온 가족처럼 반겨 주죠.","사진첩을 5분만 보려 했어요. 두 시간 뒤에도 케이크 사진 한 장에 감동하고 있습니다.","혼자 쉬는 시간이 낯설어서 누군가에게 간식을 만들어 줄 사람부터 찾습니다.","애니메이션을 볼 때는 휴지를 가까이 두세요. 잃어버린 장난감이 주인에게 돌아와도 눈시울이 뜨거워지니까요."],"wisdom":["당신의 직관은 가끔 알겠다는 말 한마디에서 드라마를 듣습니다.","소중한 추억이라고 꼭 상자 세 개를 채울 필요는 없어요.","다정함이 모든 감정에 간식을 준비해 줘야 하는 건 아닙니다.","가까운 사람의 침묵이 비극의 첫 장면인 건 아니에요.","담요는 추위를 막아 주지만 계획 변경까지 막아 주진 못해요.","영화표를 간직한다고 모든 실망도 간직해야 하는 건 아닙니다.","사랑은 상대가 자기 수프를 고르도록 두는 데서도 드러납니다.","다른 사람을 돌보는 일은 그 사람의 말이 끝날 때까지 기다리는 데서 시작될 수 있어요."],"roast":["당신은 너무 오래된 생일 카드를 보관해서 봉투가 친구들보다 당신의 역사를 더 잘 알 지경이에요.","누군가 알겠어라고 답하면 무슨 일이 생긴 건지 머릿속에서 시나리오 세 편이 바로 시작됩니다.","냉장고에는 단체 사진과 장보기 목록 두 장이 붙어 있어요. 그중 하나는 추억이라 남겨 둔 겁니다.","옛 애니메이션 주제가만 들려도 오늘은 눈물 나는 날이 될 거라고 선언합니다.","처음 보는 소파 앞에서도 담요와 부드러운 조명, 추억을 나눌 최적의 자리를 찾습니다.","소중한 사람의 음성 메시지는 고작 지금 가요라고만 해도 지우기가 어려워요.","가족 모임에 갈 때마다 사진을 더 찍고 모두 즐거웠는지 확인하는 임무를 스스로 맡습니다.","누군가 별일 없다고 하면 그 말 뒤에 숨은 감정을 확신하고 수사를 시작해요."]},"piquant":{"career":["당신의 섬세함은 세 단어짜리 이메일에서 숨은 뜻을 찾아냈어요. 보낸 사람은 시간만 확인하려던 겁니다.","문서의 옛 버전을 가족사진처럼 보관합니다. 서버는 별도의 기록 보관실을 요청했어요.","팀의 작은 변화에도 거창한 작별식을 열어요. 옮겨진 의자는 기념 앨범을 받았습니다.","누군가 인사를 잊으면 예의 위반 조사위원회를 머릿속에 소집합니다. 그 사람은 통화 중이었어요.","별뜻 없는 말 한마디도 밤까지 따라다녀요. 감정 일지의 공식 항목으로 등록됐습니다.","모두를 돌보고 싶은 마음 뒤에는 담요를 나눠 주고 감사 인사까지 확인하는 작은 행정실이 있어요.","직장 습관은 당신에게 소중해요. 화분 위치가 바뀐 날에는 추모식까지 생각합니다.","당신의 직장 기억에는 옛 사무실 시절 이야기가 가득해요. 프린터조차 감동적인 조연이었죠."],"love":["당신의 향수는 영화표를 국가 문서처럼 보존해요. 추억 서랍은 증축을 요청했습니다.","이모지 없는 알겠어를 싸늘한 외교 선언으로 해석합니다. 휴대전화는 위기가 발생한 줄도 몰라요.","조그만 다정한 추억도 머릿속 상설 전시관으로 들어갑니다. 관람객은 손대면 안 돼요.","누군가 작은 기념일을 잊어도 아무것도 아니라고 말해요. 침묵은 이미 알림 열네 개를 보냈습니다.","조용한 저녁도 상대가 어떤 담요를 원하는지 정확히 알아맞혀야 완벽해요. 담요는 협조를 거부합니다.","당신의 세심한 배려 뒤에서는 애정 표현이 제대로 인정받았는지 확인하는 감시실이 작동합니다. 기록부가 열렸어요.","사랑 때문에 옛 대화를 휴대전화에 간직한다면서요. 내면의 기록관리자는 10년 단위 분류를 준비합니다.","당신의 마음은 누구든 따뜻하게 맞아들이지만 현관의 감정 장식을 알아봐 주지 않으면 서운해합니다."],"wellbeing":["당신의 휴식은 옛 영화를 다시 보며 예전에 느낀 감정을 정확히 재현하는 일이에요. 엔딩 크레딧은 당신을 이미 알아봅니다.","기념품을 모으는 당신에게는 오래된 지하철표도 보존해야 할 유산이에요. 서랍은 건물 증축을 요청합니다.","소파가 당신을 너무 잘 이해해서 외출 수락 전에 의견을 묻습니다. 소파는 언제나 담요에 표를 던져요.","옛 노래가 시작되면 10년 치 기억을 한꺼번에 펼칩니다. 음악 플레이어는 사전 경고를 요청했어요.","집에서 보내는 평화로운 하루가 사진과 상자, 추억 어린 컵 사이를 도는 성지 순례가 됩니다. 먼지는 방명록에 서명해요.","아늑한 공간을 원하는 마음 뒤에는 한숨까지 지키는 쿠션 요새가 있어요. 손님은 감정 검문을 통과해야 입장합니다.","산책하다가 벤치 하나가 옛 대화를 떠올리게 하면 그 벤치는 대하드라마의 주인공이 됩니다.","한 시간 쉬려던 계획이었죠. 그런데 사연 있는 담요를 찾는 데만 40분을 썼어요."],"wisdom":["당신의 향수는 지나간 일요일 박물관을 확장할 예산을 신청했어요. 현재는 밖에서 기다립니다.","당신은 삐친 게 아니에요. 글자는 없고 숨은 뜻은 부록에 가득한 성명서를 발표하는 거죠.","과거는 추억으로 남아야지 거실 열쇠까지 가져선 안 돼요. 당신은 복제 열쇠도 줬군요.","누군가 아무것도 아니라고 말하면 감정 수사 네 장을 시작합니다.","애니메이션을 보고 눈물을 흘렸다고 기자회견까지 할 필요는 없어요. 이미 자료집을 준비했지만요.","당신의 다정함 뒤에서 감시관은 누가 적절한 순간에 고맙다는 말을 잊었는지 기록합니다.","추억은 아름다운 손님이에요. 당신 집에서는 영구 임대 계약까지 얻었군요.","남을 돌본다고 감정 일정표까지 짜서 선물할 필요는 없어요."],"roast":["당신의 감정 기억은 아무 일도 없었던 날의 영수증까지 보관해요. 기록관리자는 업무 과중을 호소합니다.","당신은 삐치는 기술이 너무 섬세해서 동네 전체가 정확한 이유를 추측해야 해요. 구청은 수사 요청을 거절했습니다.","최근 애니메이션에서 물건이 주인과 재회했다고 눈물을 쏟았군요. 물건은 조용히 넘어가 달라고 부탁합니다.","이모지 없는 메시지가 오면 마음속 법정이 의전 위반을 의심해요. 키보드는 보증을 요구합니다.","옛 단골 카페에 들른 일은 역사적 기념행사가 됩니다. 직원은 그냥 주문을 받으려던 건데요.","사랑스러운 배려 뒤에는 모두가 노력을 알아봤는지 확인하는 보이지 않는 체크리스트가 있어요. 도장만 남았습니다.","작은 속상함에도 쿠션과 담요, 하룻밤 묵을 방을 마련해 줍니다.","당신의 거실엔 추억이 너무 많아서 새 물건은 체류 허가부터 받아야 해요."]},"roastMy":["게자리인 당신은 추억을 간직하는 게 아닙니다. 평범한 감정들로 사립 박물관을 운영하죠. 구겨진 표와 리본, 옛 장보기 목록마다 설명문이 붙어 있어요. 그 중요성을 20분 동안 설명합니다. 서랍이 마침내 매표소를 열었습니다.","당신은 이유를 알리지 않은 채 협상을 끊어 버리는 외교부처럼 삐쳐요. 괜찮냐는 질문에는 완벽히 괜찮다고 대답하죠. 그 뒤 당신의 침묵이 성명서 세 장을 작성합니다. 쿠션들이 평화 특사로 파견됐어요.","애니메이션에서 헤어진 두 인물이 재회하면 잘 울어요. 장면을 외우면서도 휴지를 준비하죠. 친구가 왜 또 보느냐고 묻습니다. 당신은 줄거리 때문이라고 답하고 엔딩 크레딧은 한숨을 쉽니다.","당신의 휴대전화에는 마음을 울린 화면 캡처가 도서관만큼 많아요. 평범한 메시지도 중요한 날에 왔다며 보관하죠. 누군가 정리를 제안합니다. 기록물 위원회가 즉시 제안을 반려했어요.","당신은 24시간 운영하는 특급 안내 데스크처럼 사랑하는 사람을 챙깁니다. 담요와 음료, 응원 쪽지를 준비하죠. 그런데 아무도 냅킨을 완벽하게 접은 걸 알아봐 주지 않아요. 내면의 감사 담당 부서가 항의서를 제출합니다.","당신에게 집은 단순한 인테리어가 아니에요. 쿠션마다 추억이 있고 컵마다 사연이 있고 소파 구석마다 감정적 가치가 있죠. 손님이 스탠드를 옮기자고 합니다. 당신은 방의 문화유산을 존중해 달라고 요청해요.","당신은 모든 것을 기억해요. 특히 남들이 잊은 사소한 말들을요. 오래전 점심에 나온 농담 하나를 날짜와 메뉴까지 곁들여 다시 꺼냅니다. 말한 사람은 무슨 이야기인지도 몰라요. 당신의 기억이 회의록을 제출합니다.","당신은 가까운 사람들과 아늑한 저녁을 보내는 걸 좋아해요. 누군가 조금 일찍 가야 한다고 말하기 전까지는 모든 게 따뜻하죠. 당신은 웃으며 빈 의자를 영화 장면처럼 바라봅니다. 의자는 슬픈 배경음악 좀 꺼 달라고 요청해요.","당신의 감정 레이더는 문장부호만 보고 기분 변화를 알아챕니다. 느낌표 없는 고맙다는 말에 원인 조사가 시작돼요. 3주치 대화를 다시 읽으며 의미를 찾습니다. 상대는 그냥 배터리가 부족했던 거예요.","당신은 과거를 너무 좋아해서 오래된 과자 상자에도 거주권을 줍니다. 상자 하나하나가 소중한 순간을 떠올리게 한다고 설명하죠. 새 과자를 넣을 공간은 없습니다. 부엌은 감성 도시계획을 수립하기 시작해요."]},"leo":{"classic":{"career":["주목받고 싶은 마음은 팀의 성과도 함께 빛낼 때 큰 힘이 됩니다.","눈에 띄는 일을 먼저 맡는 것을 좋아하죠. 드러나지 않는 동료의 기여까지 살피면 영향력이 커질 거예요.","자신감은 아이디어를 자연스럽게 소개할 기회를 열어 줍니다.","즉각적인 인정에 얽매이지 않고 창의력을 발휘할 때 생각이 더 깊어집니다.","앞장서는 역할에 끌리지만 무대 뒤에서 쌓이는 노력의 가치도 알아봐 주세요.","당신의 당당함 뒤에는 진정한 책임감이 있어요. 말보다 행동으로 보여 주세요.","직장에서 보여 주는 너그러움이 팀에 새로운 활력을 줄 수 있어요.","프로젝트에 쏟는 열정에는 끊임없는 칭찬보다 명확한 방향이 더 도움이 돼요."],"love":["당신의 따뜻함은 나누는 만큼 상대의 말에도 귀 기울일 때 더욱 특별해집니다.","관심받는 것을 좋아하죠. 보답을 기대하지 않는 배려도 친밀함을 키웁니다.","관계에서 인정받고 싶은 마음과 상대를 향한 호기심을 함께 품어 보세요.","감동을 줘야 한다는 부담을 내려놓으면 더 부드러운 애정이 드러나요.","너그러운 사랑은 거창한 고백보다 작은 행동에서 빛날 수 있어요.","자존심 뒤에는 더 조용한 언어로 전하고 싶은 진심이 숨어 있어요.","칭찬도 기쁘지만 솔직한 대화에서 더 오래가는 행복을 얻을 수 있어요.","당신의 사랑은 관계에서 각자가 충분한 자리를 가질 때 더 큰 의미를 얻습니다."],"wellbeing":["넘치는 에너지에도 무언가를 증명할 필요 없는 순간이 필요해요.","다른 사람의 시선에서 벗어난 고요함 속에서도 힘을 회복할 수 있어요.","누구에게 보여 주기 위해서가 아니라 자신을 위해 창작하는 기쁨을 느껴 보세요.","일정 속에서 늘 중심에 서 있다면 조용한 휴식으로 균형을 되찾아 보세요.","목표 없는 산책은 성과를 요구하지 않는 공간을 열어 줍니다.","열정이 넘치는 당신에게도 쉬어야 할 이유는 충분해요.","소중한 사람들과 함께할 때 꼭 분위기를 이끌지 않아도 마음을 채울 수 있어요.","삶을 즐기는 마음에 스스로 선택한 평온한 시간도 곁들여 보세요."],"wisdom":["자신의 빛으로 다른 사람도 빛나게 할 때 그 빛은 더 강해집니다.","박수받지 않아도 당신의 가치는 사라지지 않습니다.","소박해질 용기는 더 오래가는 품격을 보여 줍니다.","자존심이 경청을 배우면 자신감이 됩니다.","진심 어린 존재감은 화려한 과시보다 더 멀리 비춥니다.","눈에 보이는 성공 뒤에는 작은 행동을 이어 온 성실함이 있습니다.","아름다운 열정에 언제나 무대가 필요한 것은 아닙니다.","빛난다는 건 다른 사람과 공간을 나눌 줄 아는 일이기도 해요."],"roast":["이끌고 싶은 마음이 너무 강하면 다른 사람은 문장을 끝내기조차 어려워져요.","주목받는 것을 좋아하지만 주변이 조용하다고 반드시 당신을 인정하지 않는 건 아니에요.","계속 칭찬받고 싶은 마음이 진정 자랑스러운 것을 가릴 수도 있어요.","모든 대화를 설득의 기회로 만들면 자연스러움이 사라져요.","눈에 띄게 등장하는 것만으로 세심한 존재감을 대신할 수는 없어요.","너그러움 뒤에 좋은 일을 했다는 사실을 반드시 누가 봐 주길 바라는 마음은 없는지 살펴보세요.","다른 사람의 시선만으로 관계의 가치를 모두 알 수는 없어요.","마지막 말을 포기한다고 당신의 매력이 줄어드는 건 아니에요."]},"funny":{"career":["당신의 사무실은 무대예요. 서류 정리 하나에도 앙코르 박수가 필요하죠.","회의에서 새로운 파일명 하나를 제안하면서 세기의 발견을 발표하듯 말합니다.","동료가 당신을 칭찬하면 즉시 부서에서 가장 좋아하는 사람 1위가 돼요. 순위는 매시간 갱신됩니다.","자원자를 모집하면 질문이 끝나기도 전에 손을 듭니다. 손은 곧 마이크도 요구해요.","문서에 서명하는 일도 당신에게는 공식 기념식이 됩니다.","모니터 뒤에서 경영진을 방송 오디션 심사위원처럼 여기며 발표를 연습합니다.","팀이 성과를 내면 너무 기뻐서 단체 사진부터 제안해요. 물론 가운데는 당신 자리죠.","당신의 명함에는 잊지 못할 순간 담당자라고 적어도 돼요. 사실 이미 비공식적으로 맡고 있거든요."],"love":["당신의 매력은 큰 몸짓을 좋아해요. 과자 하나를 건네면서도 소개 연설이 필요합니다.","칭찬을 기다릴 때는 태연한 표정이지만 머릿속에는 답변 세 가지가 준비돼 있어요.","어떤 데이트든 영화제처럼 등장해야 한다고 믿어요. 레드카펫은 선택 사항이죠.","상대가 하루 이야기를 할 때 진지하게 듣다가도 슬쩍 새 옷을 알아봤는지 확인합니다.","둘이 찍는 사진은 몇 번이고 다시 찍어야 마음에 들어요. 주로 당신의 미소가 가장 잘 나올 때까지요.","당신의 다정한 너그러움 뒤에서는 언제 멈춰야 할지 모르는 작은 악단이 연주 중이에요.","다정한 말 한마디에 마음이 녹아요. 예쁜 스웨터네요라는 칭찬 하나로 저녁까지 행복해집니다.","당신의 마음은 활짝 열려 있지만 인테리어를 칭찬해 달라는 안내판도 근처에 있어요."],"wellbeing":["당신의 이상적인 휴식에는 선베드와 햇빛, 그리고 얼마나 편안해 보이는지 확인해 줄 관객이 포함돼요.","조용히 쉬려고 했는데 2분 뒤 휴식 후기를 게시할까 생각합니다.","현관 거울은 편안한 날에도 당신에게서 미소를 받아요.","혼자 산책하면서 나무들에게 정중한 관객인 양 인사를 건넵니다.","일정 없는 저녁도 좋지만 엔딩 음악만큼은 직접 고르고 싶어 해요.","바깥 활동을 좋아하지만 때로는 소파와 품격에 맞는 담요 한 장이면 충분해요.","고요한 시간도 마음에 들어요. 다만 아무도 고요함을 칭찬 부족과 혼동하지 않는다면요.","해 질 녘 노을을 보면서도 노을과 경쟁하지 않는 것이 오늘의 휴식 과제일 수 있어요."],"wisdom":["당신의 겸손이 늦는 이유는 더 극적인 입장을 찾고 있기 때문이에요.","다른 사람과 빛을 나누는 건 좋아요. 스위치는 계속 본인이 잡으려 하지만요.","태양은 박수를 요구한 적 없어요. 배울 점이 있군요.","아무도 지켜보지 않을 때 사자자리도 드디어 따뜻한 커피를 끝까지 마실 수 있어요.","좋은 아이디어에 꼭 당신 사진이 들어간 포스터가 필요한 건 아니에요.","거창한 연설 뒤에 숨어 있는 바람이 사실은 과자 한 조각일 때도 있어요.","칭찬은 회의 안건으로 올라오지 않았을 때 더 달콤해요.","함께 빛나면 조명을 전부 혼자 들 필요가 없어요."],"roast":["당신이 방에 들어오려면 예고편이 필요해요. 그냥 열쇠 가지러 들어오는 건데 말이죠.","당신은 시간을 묻는 게 아니라 시계에 답변할 영광을 베풀어요.","당신의 사전에서 조용히라는 말은 기립박수와 앙코르 사이에 있어요.","누군가 일화를 이야기하면 당신은 현장에 없었어도 더 극적인 버전을 내놓습니다.","당신 없는 단체 사진은 당신 기준으로 구도가 잘못된 사진이에요.","왕 같은 미소 뒤에는 칭찬 부족 전담 고객센터가 운영되고 있어요.","남의 생일도 즐거워요. 드디어 당신의 등장을 위해 장식된 장소가 생겼으니까요.","선물을 주는 마음은 진심이에요. 다만 선물 안에 당신에 대한 감사 프로그램이 들어 있기도 하죠."]},"piquant":{"career":["당신의 야망은 직책이 아니라 회사를 향해 손을 흔들 발코니를 찾고 있어요. 인사팀은 조명 설치를 고민합니다.","회의에서 자신의 기여를 꼭 알아봐 달라고 합니다. 의자 하나를 옮겼을 뿐인데 연례 보고서가 나올 판이에요.","팀의 작은 성공도 당신의 기자회견이 됩니다. 다른 동료들은 단체 사진에서 자신을 찾아야 해요.","발표 뒤 박수가 없으면 모두의 예술 감각에 단체 고장이 났다고 의심합니다.","승진도 직함을 충분히 번쩍이는 명패에 새길 수 있어야 마음에 들어요. 사무실 가구들이 생존 협상을 시작했어요.","당신의 지도자다운 열정 뒤에서 모든 동료는 자기도 모르게 엑스트라로 캐스팅됐어요. 동의 없는 오디션이 시작됐죠.","익명 업무는 개인적인 모욕입니다. 증인 없는 업적이 무슨 소용인가요? 프린터는 사인 요청을 거절합니다.","리더십이 너무 눈부셔서 업무 대시보드가 선글라스를 요구해요. IT 부서는 장애 신고를 접수했습니다."],"love":["칭찬을 향한 갈망이 조용한 저녁을 시상식으로 바꿔요. 메뉴에는 올해의 특별한 존재라는 부문까지 생겼습니다.","애정을 아낌없이 주고 나서 감사 인사 시상식을 기다려요. 수상 소감에는 꼭 당신 이름이 들어가야 합니다.","칭찬 하나를 놓치면 국가적 사건이 돼요. 새 재킷을 왜 아무도 알아보지 못했는지 조사위원회가 열립니다.","관심을 끌고 싶지 않다고 말하면서도 누가 그 선언을 들었는지 이미 확인하고 있어요.","수수한 고백은 오히려 수상해요. 사진기자와 바이올린 연주자는 어디에 숨었나요?","화려한 매력 뒤에는 반응을 감시하는 작은 검사실이 있어요. 미지근한 미소 하나도 감사 대상입니다.","소박한 로맨틱한 행동은 이해하기 어려워요. 막이 오르는 커튼은 어디에 설치하죠? 소파는 공연 허가를 요청합니다.","당신의 마음은 넓어요. 특히 본인 액자를 걸 자리에는요. 상대에게는 액자 테두리를 고를 권한을 줍니다."],"wellbeing":["당신의 휴식에는 관객이 필요해요. 평온함을 목격할 팬이 없으면 정식 민원을 고려합니다.","침착함조차 공개 행사처럼 연출해요. 의상과 조명, 등장 장면까지 완벽합니다. 침묵도 지쳤어요.","소파에서 잠시 쉴 생각이었는데 어느새 자서전 열 권을 펼쳐 놓았어요. 쿠션들이 저작권료를 요구합니다.","명상하면서 집중력에 대한 박수를 상상해요. 우주는 마이크를 꺼 버렸습니다.","혼자 산책한다더니 쇼윈도 앞에서 퍼레이드를 열어요. 마네킹들이 경쟁을 멈춰 달라고 요청했습니다.","바쁜 하루 뒤에 무대 조명 없는 1분을 찾았어요. 그리고 그 1분에 본인 이름을 붙였습니다.","조용한 목욕도 좋지만 성과를 발표하고 싶어지자 심사위원단까지 소집했어요.","당신에게 휴식이란 휴대용 거울에게 감탄 업무를 위탁하는 일입니다. 쉬는 시간에도 매니저가 붙어 있어요."],"wisdom":["당신의 자존심은 왕좌조차 필요 없어요. 이미 이사회 전체를 예약했거든요.","당신은 카리스마라고 불러요. 벽들은 쉬는 시간 없는 강연이라고 부릅니다.","침묵은 당신의 재능에 대한 비판이 아니에요. 법정 휴식 시간일 뿐이죠.","다른 사람에게 주인공 자리를 양보하는 날이면 기적 관리 부서가 특별 개장합니다.","보이지 않는 왕관도 소품일 뿐이에요. 그런데 당신은 보험부터 들었군요.","당신의 선언된 겸손 뒤에는 아직도 개막식을 기다리는 연단이 있어요.","칭찬은 확성기로 재배할 수 없어요. 당신의 정원은 동의하지 않지만요.","빛난다고 태양과 독점 계약을 맺을 필요는 없어요."],"roast":["당신의 자존심은 식탁에 의자 하나를 더 요청해요. 식당은 단체 손님으로 등록했습니다.","스스로 소박하다고 하죠. 그 소박함에는 로고와 슬로건, 홍보팀까지 있어요.","거울은 당신이 오기도 전에 알아봅니다. 결국 휴가를 신청했어요.","친구가 성공하면 축하한 뒤 시상식 사회자를 자청해요. 초청받지도 않았는데요.","당신이 중심이 아닌 대화가 시작되면 비상 절차가 발동됩니다. 교환실은 전화를 받지 않아요.","너그러움 뒤에는 열두 쪽짜리 감사 인사 내규가 있어요. 서명자는 물론 당신이죠.","셀카가 외장 기억 장치가 됐어요. 휴대전화는 풍경이 뭔지도 잊어버렸습니다.","당신의 겸손이 책을 냈어요. 헌사만으로 표지 전체를 채웠습니다."]},"roastMy":["사자자리인 당신은 방에 들어가는 게 아닙니다. 개관식을 여는 거죠. 조명과 시선의 각도, 관객 반응까지 살핍니다. 가족 점심 식사도 연례 기자회견이 돼요. 친척들은 의무적인 칭찬을 동시통역해 달라고 요청했습니다.","당신은 칭찬받기를 좋아하지만 이제 잘했어요만으로는 부족해요. 근거와 날짜, 증인 두 명의 서명이 필요하죠. 칭찬이 도착하자 표현이 마음에 안 든다고 이의를 제기합니다. 당신의 법무팀 이름은 바로 나예요.","당신의 너그러움은 무척 커요. 특히 홍보 포스터가 붙어 있을 때요. 디저트를 사고 사진을 찍고 감사에 관한 연설을 합니다. 상상 속 박수 속에서 케이크는 식어 가죠. 제과점은 다음 후원자에게는 조용히 해 달라고 요청했어요.","당신은 관심받는 걸 싫어한다고 주장해요. 그런데 문을 닫기도 전에 단체 채팅방에 자신의 도착을 알리죠. 자리에 앉자 자기가 없을 때 분위기가 달랐냐고 물어요. 침묵은 별 다섯 개짜리 평가로 기록됩니다.","당신의 셀카는 순간을 담는 게 아닙니다. 왕조의 역사를 기록하죠. 풍경이 뒤에서 나오려 하자 침입자라며 잘라 버립니다. 노을마저 당신 미소의 배경이 됐어요. 노을은 불공정 경쟁에 대한 이의 신청을 준비합니다.","당신의 자존심은 보통 회의실에 들어가지 않아요. 의사일정과 연단, 개회 1분 기립박수를 요구하죠. 안건은 종이컵 고르기였어요. 종이컵들이 위원회를 탈퇴했습니다.","당신은 소박함을 꿈꾸지만 우아하고 눈에 띄는 소박함이어야 해요. 편한 옷차림을 정하는 데 세 번 입어 보고 공식 발표까지 하죠. 낡은 스웨터에도 홍보팀이 있습니다. 세탁소는 더 이상 인터뷰를 받지 않아요.","당신이 있는 파티는 환해져요. 직접 조명 밝기를 올리기 때문이죠. 일화를 하나 얘기한 뒤 대사까지 맞춰 재연합니다. 친구들은 대본을 외워 버렸어요. 한 친구는 웃음 연기 대역을 요청합니다.","당신은 칭찬을 국빈 방문처럼 맞이해요. 의전과 미소, 짧은 감사 연설, 잊힌 공적을 다시 강조하는 순서까지 있습니다. 상대는 그냥 화분이 예쁘다고 말했을 뿐이에요. 화분이 대통령 자리를 요구했어요.","당신의 리더십은 의심할 여지가 없어요. 길을 아는 사람에게도 방향을 알려 주니까요. 매장 출구를 알려 준 뒤 효율성을 인정받았는지 확인합니다. 경비원이 상징적인 임무를 맡겼어요. 당신은 즉시 대관식으로 바꿨습니다."]},"virgo":{"classic":{"career":["세부 사항을 살피는 능력 덕분에 프로젝트를 발표하기 전에 더 단단하게 다듬을 수 있어요.","명확한 방식을 좋아하지만 뜻밖의 아이디어가 들어올 여지도 남겨 보세요.","매 단계에 기울이는 정밀한 관심은 동료들에게 신뢰를 줍니다.","기준이 너무 높아질 때는 중요한 것과 사소한 것을 구별하면 한결 수월해져요.","복잡한 업무도 체계적으로 살펴보면 일관된 방향을 찾을 수 있어요.","정리하려는 마음 뒤에는 다른 사람에게 도움이 되고 싶은 진심이 있어요.","당신이 발견하는 작은 개선점은 팀 전체에 큰 변화를 가져올 수 있어요.","분석 능력에 다른 사람을 향한 믿음을 더하면 그 가치가 더욱 커져요."],"love":["세심한 눈길 덕분에 말하지 않은 필요까지 알아차릴 때가 있어요.","소중한 사람의 일상을 더 편하게 만드는 방식으로 애정을 표현하는 편이군요.","잘하고 싶은 마음도 관계에서 예상 밖의 일을 받아들일 때 한결 부드러워져요.","완벽한 말을 찾으려는 노력을 내려놓으면 진심이 더 쉽게 전해져요.","관계는 미완성의 작은 몸짓들이 아름다운 추억이 되면서 만들어지기도 해요.","조심스러운 모습 뒤에는 세심한 경청과 깊은 성실함이 숨어 있어요.","상대의 미묘한 변화를 느낄 때 반드시 분석하기보다 그대로 받아들여 보세요.","잘해 주려는 마음이 즉흥적인 행동도 허락할 때 당신의 다정함이 온전히 드러납니다."],"wellbeing":["정리정돈은 도움이 되지만 휴식까지 과제로 만들지는 마세요.","하루 중 아무 목표 없이 보내는 시간을 조금 남겨 보세요.","최적화한 동선 없이 그저 걷는 즐거움이 시선을 새롭게 할 수 있어요.","모든 게 수정이 필요해 보일 때 잠시 쉬면 관점이 달라질 수 있어요.","화면에서 벗어난 짧은 휴식은 엄격한 생각에 여유를 줍니다.","책임감 강한 당신에게도 고요함을 누릴 자리가 필요해요.","물을 마시거나 자기 속도로 숨을 쉬는 단순한 행동도 일상의 균형에 도움이 됩니다.","행복은 체크한 항목 수로 측정되는 것이 아니에요."],"wisdom":["정확함은 삶에 숨 쉴 공간을 남길 때 더 유익합니다.","세부 사항 하나를 정성껏 살피되 전체를 고치려 할 필요는 없습니다.","균형은 아직 완성되지 않은 것들도 받아들입니다.","방법과 유연함이 만나면 노력은 가벼워집니다.","목록을 전부 끝냈다고 하루의 가치가 정해지지는 않습니다.","완벽하지 않은 것 뒤에도 새로운 가능성이 숨어 있을 수 있어요.","단순한 것은 개선하지 않아도 아름다울 수 있습니다.","끝나지 않은 일을 인정하는 것도 하나의 능숙함입니다."],"roast":["모든 것을 확인하려는 습관이 생각보다 간단한 결정을 무겁게 만들 수 있어요.","아주 작은 차이도 잘 알아차려서 주변 사람들은 쉴 틈이 없을 때가 있어요.","잘 정리하고 싶은 마음 때문에 결과를 즐길 시점을 자꾸 미룰 수 있어요.","어색한 문장을 보면 본래 뜻보다 고치는 일이 더 중요해질 때가 있어요.","지나치게 자세한 목록은 왜 만들었는지조차 잊게 할 수 있어요.","효율성을 중시하는 마음에도 예상 밖의 일이 들어올 여지를 남겨 보세요.","당신의 조언은 매우 구체적이지만 상대가 그만큼 구체적으로 부탁한 것은 아닐 수 있어요.","흠잡을 데 없는 결과를 추구하되 이미 충분히 훌륭한 것을 인정하는 능력도 필요해요."]},"funny":{"career":["당신의 진행 상황표에는 진행 상황을 추적하는 표가 또 있어요. 그 표마저 색상 코드가 필요하답니다.","동료의 이메일을 다시 읽으며 쉼표 세 개를 대상으로 정밀 평가를 실시합니다.","파일을 정리하면 시끄러운 응원단 없는 스포츠 경기에서 우승한 것처럼 조용히 기뻐해요.","누군가 즉흥적으로 하자고 하면 일정표가 상징적으로 모든 창을 닫습니다.","15분 회의도 번호를 잘못 매긴 문서에서 세상을 구할 절호의 기회예요.","흠잡을 데 없는 책상 뒤 서랍에는 아마 서랍 정리의 미래라는 제목의 파일이 숨어 있을 거예요.","통화 중 적은 메모가 너무 상세해서 상대방이 복사본을 주문하고 싶어 해요.","가장 좋아하는 펜은 아무에게나 빌려주지 않아요. 철저한 비교 끝에 선택한 펜이니까요."],"love":["당신의 사랑 고백은 잘 정리된 서비스 같아요. 우산과 버스 시간표까지 미리 생각해 뒀거든요.","누군가 집의 작은 장식 하나를 바꿔도 즉시 알아차립니다. 상대는 당신이 재고 목록을 작성한 줄도 몰라요.","낭만적인 저녁이 잘 흘러가다가 식기 정리 방식을 개선하자고 제안하면서 흐름이 바뀝니다.","꽃을 선물받으면 감동한 뒤 즉시 가장 알맞은 꽃병을 찾습니다.","깜짝 이벤트는 정말 좋아해요. 단, 달력에 미리 등록하는 예의를 지켰다면요.","진지한 모습 뒤에는 사랑한다는 말을 찬장 문을 고쳐 주는 것으로 표현하는 사람이 있어요.","다정한 문자도 두 번씩 검토해요. 감정 표현의 문법 오류까지 피하려고요.","당신의 배려에는 수건을 올바르게 접는 법에 관한 작은 안내문도 포함될 수 있어요."],"wellbeing":["당신의 휴식은 목록으로 시작해요. 첫 단계는 목록을 없애기. 그런데 그 항목은 아직 진행 중입니다.","산책하려고 하면서 가장 단순한 길을 고르기 위해 경로 세 개를 비교합니다.","담요를 덮고 앉아야 할 때 정확히 접어 제자리에 놓고 있어요.","잠시 쉴 때도 예정 시간보다 2분 늦게 시작했다는 사실을 머릿속에 적어 둡니다.","차 한 잔도 당신 손에서는 받침 접시의 위치까지 정확한 실험이 돼요.","정리하고 싶은 마음 뒤에서 소파는 첨부파일 없는 초대장을 보냅니다.","산책이 도움이 돼요. 나뭇잎 하나가 제자리에 없어도 괜찮다는 걸 받아들인다면요.","당신의 평온함에는 모든 알림을 분류했다는 만족감도 포함됩니다."],"wisdom":["행복에 표는 필요 없어요. 열 없이도 찾아올 수 있거든요.","인생이 목차를 빼먹어도 믿어 볼 수 있어요.","어지러움이 늘 비상사태인 건 아니에요. 가끔은 쿠션 하나가 옮겨졌을 뿐이죠.","체크칸 하나가 비었다고 우주가 자동으로 조사에 착수하진 않아요.","쉼표가 잘못 찍혀도 커피 맛은 좋을 수 있어요.","완벽함 뒤에는 그냥 앉아도 되는 의자 하나가 숨어 있을 때가 있어요.","돌발 상황들은 당신의 절차서를 읽지 않아요. 예의가 없죠.","중요한 일이라도 나중에 확인이라는 폴더를 받아들일 수 있어요."],"roast":["당신의 비판적인 눈은 쉬지 않아요. 휴가 포스터마저 레이아웃 수정 의견을 받습니다.","찬장을 정리하는 게 아니에요. 독자적인 법률을 가진 문명을 건설하죠.","대충이라는 말만 들어도 수평계를 꺼내고 싶어집니다.","누군가 이 정도면 됐다고 하면 당신은 협상 시작 신호로 받아들입니다.","메시지에서 오타 하나를 발견하면 공범이 더 있는지 전체를 다시 읽어요.","공손한 미소 뒤에서는 보이지 않는 평가표가 사람들에게 점수를 매깁니다.","부엌 서랍은 박물관 목록보다도 분류 기준이 많아요.","당신의 휴식에는 출퇴근 기록까지 필요할 만큼 정확한 일정이 있습니다."]},"piquant":{"career":["당신의 완벽주의는 간단한 이메일 하나를 허가받아야 하는 공사장으로 만들었어요. 첫 인사말은 아직 건축 허가를 기다립니다.","동료의 쉼표를 판사처럼 엄숙하게 고칩니다. 키보드는 변호사를 요청했어요.","프로젝트 관리표의 탭 수가 참가자 수보다 많습니다. 탭들은 이제 당신 없이 자체 회의를 열어요.","업무가 끝나도 다시 열어 정말 완료라고 불러도 되는지 확인해요. 완료라는 단어가 사표를 냈습니다.","불완전한 공지가 최우선 업무가 됐어요. 아무도 당신에게 세미콜론을 구해 달라고 하지 않았는데요.","완벽한 업무 방식 뒤에서는 감사위원회가 감사위원회를 감시합니다. 감사 담당자는 또 당신이죠.","마감 기한을 존중하려면 여유 시간과 경고, 경고에 대한 경고 계획까지 있어야 해요. 일정표는 숨어 버렸습니다.","제목 글꼴 때문에 회의가 멈췄어요. 정작 회의 안건이던 긴급한 일은 이미 지나갔습니다."],"love":["당신의 다정함은 은근한 교정으로 나타나요. 꽃다발은 꽃병 심사를 받기 전까진 아름다웠습니다.","고민을 들어주면서 품질관리 책임자처럼 행동해요. 상대는 위로를 원했는데 개선 계획서를 받았습니다.","로맨틱한 문자에 감동한 뒤 오류 두 개를 찾아냅니다. 사랑의 신은 재교육 통보를 받았어요.","깜짝 계획이 있으면 시간과 장소, 준비 수준을 묻습니다. 신비감은 참석을 취소했습니다.","쿠션이 대칭으로 놓여 있으면 둘만의 저녁은 성공입니다. 감정들은 외투 보관소에서 기다려요.","세심한 배려 뒤에는 다정한 행동의 일관성을 평가하는 보이지 않는 양식이 있어요. 즉흥성 칸은 비활성화돼 있습니다.","상대의 귀여운 결점도 다섯 단계로 해결할 수 있으면 참을 수 없어요. 로맨스는 기술 지원 요청을 열었습니다.","당신의 마음은 닫힌 게 아닙니다. 주제와 날짜, 우선순위별로 분류돼 있을 뿐이죠. 열쇠는 공유 폴더에 있습니다."],"wellbeing":["휴식 계획에는 성공한 휴식을 기록하는 표가 있어요. 첫 휴식은 신뢰할 자료가 없어서 취소됐습니다.","누워 있기 전에 쿠션을 정리하고 정렬 상태를 확인합니다. 소파는 중재자를 요청했어요.","침묵에 마음이 편안해졌다가 살짝 기운 시계를 발견합니다. 평온함은 연기됐어요.","산책하면서 거리와 보도를 비교하고 경로를 최적화합니다. 신선한 공기마저 점수를 받아요.","따뜻한 음료로 쉬려 했는데 컵 비교 분석을 시작합니다. 심사하는 동안 음료는 식었습니다.","좋은 의도 뒤에서 휴식은 불시 점검으로 변해요. 담요는 신분증이 없습니다.","할 일 없는 주말은 불안해요. 즐거움을 어디에 배치할지 적힌 칸이 없거든요. 일요일은 직무기술서를 기다립니다.","휴식하려는 의지는 훌륭해요. 다만 잊지 않으려고 알림을 세 개나 설정했군요."],"wisdom":["놓아 버릴 일 목록에 벌써 열일곱 가지 하위 분류가 있어요. 내려놓는 마음은 달아났습니다.","당신은 완벽함을 찾는 게 아니에요. 결점의 이웃집까지 추적하는 거죠.","혼란이란 가끔 양말 하나가 옮겨진 일일 뿐이에요. 당신의 보고서는 스무 쪽이지만요.","사소한 것 하나만이라고 말하는 순간 기술팀은 현장에서 대피합니다.","쉼표 하나가 세상을 지배하지는 않아요. 쉼표는 아직 그걸 모르는 모양입니다.","마음의 평화 뒤에서 검사관 하나가 구름의 접힌 모양까지 확인합니다.","실수는 인간적인 일이에요. 당신은 인간 인증 양식을 먼저 검토하자고 했어요.","예상 못 한 일은 설문지를 작성하지 않았어요. 그래서 출입을 거절합니다."],"roast":["당신의 완벽주의가 할머니의 요리법까지 고쳤어요. 할머니는 밥값을 환불해 달라고 했습니다.","당신은 목록을 그만 만들 이유까지 목록으로 작성했어요. 코팅까지 마쳤죠.","비스듬한 액자 하나를 보면 조사위원회가 열립니다. 못은 무죄를 주장해요.","누군가 틀린 표현을 쓰면 마음속에서 외교 관계를 중단합니다.","즉흥적인 저녁은 물류 체계 파괴 행위예요. 보드게임은 허가서를 기다립니다.","겉으로 차분한 모습 뒤에서 검사관이 수건들의 출석부 서명을 확인하고 있어요.","남들은 쉬고 있는데 당신은 그 휴식의 품질을 평가하고 수정안을 제안합니다.","잡동사니 서랍도 잡동사니 종류별로 정리돼 있어요. 무질서마저 권리를 잃었습니다."]},"roastMy":["처녀자리인 당신은 집을 정리하는 게 아닙니다. 하나의 영토를 통치하죠. 모든 물건에는 주소와 기능, 이동했을 때의 처벌이 있어요. 손님이 엉뚱한 곳에 외투를 놓습니다. 디저트가 나오기도 전에 징계위원회가 열렸어요.","당신은 이웃에게 인사하듯 자연스럽게 오타를 고쳐요. 애정 어린 메시지에 작은 오류가 있으면 왜 감동했는지 거의 잊을 지경이죠. 하트를 보낸 뒤 수정본을 전달합니다. 키보드는 행정적 분리를 요청했어요.","당신의 할 일 목록에는 표지와 장, 하위 목록 부록까지 있어요. 체크 한 번으로 세계 질서를 회복한 듯 뿌듯해하죠. 그 순간 새 업무 두 개가 나타납니다. 목록이 독자적인 관료 조직을 세웠어요.","당신은 제대로 하는 걸 좋아한다고 말합니다. 다른 사람들은 의자 하나 옮기려면 서류를 제출해야 한다고 말하죠. 절차를 간단하게 만들겠다며 짧은 양식을 새로 제안합니다. 열네 쪽짜리예요.","당신은 모든 메시지를 너무 깊게 분석해서 간단한 알겠어요도 수수께끼가 됩니다. 왜 완벽하다는 말이 아닐까, 왜 마침표를 찍었을까, 왜 이 시간일까? 대화는 끝났지만 당신은 이제 의회 조사위원회를 열었어요.","당신이 생각하는 즉흥성이란 예정된 활동 두 개의 순서를 바꾸는 거예요. 잠시 설레다가 일정을 원래대로 돌려놓죠. 운명조차 회의록을 받습니다. 운명은 수신 확인을 요청한 적이 없어요.","당신은 남을 돕는 걸 좋아해요. 특히 애초에 어떻게 했어야 하는지 설명할 수 있을 때요. 도움은 효율적이고 자세하며 문서와 도표까지 첨부돼 있죠. 사람들은 진심으로 고마워합니다. 그리고 자기 서랍을 숨겨요.","아무 의무 없는 하루를 꿈꾸나요? 먼저 일정을 비우고 의무 없는 활동 목록을 만든 뒤 그 시간을 즐기라는 알림을 설정합니다. 정오에는 휴식 효율을 감사합니다. 해먹은 소송을 예고했어요.","당신의 부엌은 너무 잘 정리돼서 숟가락 하나가 없으면 전국 경보가 울릴 지경이에요. 그런데 숟가락은 제자리에 조금 돌아가 있을 뿐이죠. 누군가 일부러 그랬다고 의심합니다. 식기세척기는 정치적 망명을 요청했어요.","당신은 누구도 판단하지 않는다고 엄숙하게 말해요. 단지 관찰하고 분류하고 비교하고 머릿속으로 건설적인 평가를 작성할 뿐이죠. 친구는 발표가 명확했는지 한마디만 물었어요. 당신은 프로젝터 사용 시간을 연장해 달라고 합니다."]},"libra":{"classic":{"career":["당신의 균형 감각은 직장에서 의견이 부딪힐 때 한 발 물러서서 보는 힘이 됩니다.","서로 다른 관점을 하나로 모으는 데 능숙해요. 명확한 방향을 결정하는 능력도 더해 보세요.","조화를 추구하는 마음은 유용한 의견 차이까지 없애지 않는다면 프로젝트에 도움이 됩니다.","여러 해법이 좋아 보일 때 중요한 기준부터 정하면 앞으로 나아가기 쉬워요.","신중한 표현은 어려운 결정을 둘러싼 협력을 도울 수 있어요.","외교적인 태도 뒤에는 자기 생각을 우아하게 지킬 수 있는 힘이 있어요.","모든 대안을 비교하지 않아도 된다고 받아들이면 업무 선택이 한결 가벼워집니다.","미적 감각은 세련된 발표와 독창적인 비전에 힘을 더할 수 있어요."],"love":["조화를 바라는 마음은 서로 존중받는다고 느끼는 대화를 만들어 줍니다.","아름다운 순간을 만드는 걸 좋아하지만 그 순간의 소박함도 소중할 수 있어요.","모두에게 좋은 인상을 주려는 마음을 내려놓으면 자기 취향을 더 자유롭게 표현할 수 있어요.","솔직해야 하는 대화에서도 당신의 부드러움은 진심을 전하는 데 도움이 돼요.","균형 잡힌 관계는 받아들이는 차이 속에서도 자라납니다.","은은한 매력 뒤에는 상대를 깊이 이해하려는 마음이 있어요.","일상의 작은 망설임보다 함께하는 사람을 향한 관심이 더 중요해요.","공정함에 대한 감각은 다정함을 통해 더욱 개인적인 의미를 얻어요."],"wellbeing":["균형을 찾는 마음이 자신의 필요를 존중하는 생활 리듬으로 이끌 수 있어요.","아름다운 장소를 좋아하지만 편안함을 느끼는 데 꼭 화려한 공간이 필요한 건 아니에요.","모두를 만족시키려는 마음 대신 자신의 평온함을 먼저 살펴도 괜찮아요.","선택지가 너무 많아질 때 잠시 자극에서 벗어나면 원하는 것이 분명해질 수 있어요.","조화로운 장소를 걷다 보면 작은 것들을 새롭게 바라보게 돼요.","다른 사람에게 늘 열려 있는 당신에게도 혼자만의 시간은 소중해요.","부드러운 음악이나 밝은 공간처럼 아름다움을 느끼는 작은 즐거움이 휴식에 도움이 됩니다.","마음의 평화를 위해 주변 모두가 같은 의견일 필요는 없어요."],"wisdom":["절대적인 확신 없이도 선택할 용기를 낼 때 균형이 자랍니다.","모든 목소리를 듣되 자신의 목소리를 잊지 마세요.","아름다움이 진실을 대신할 수는 없지만 진실로 가는 문을 열 수는 있습니다.","평화를 위해 침묵해야 할 때도 솔직함의 자리를 남겨 두세요.","완벽하지 않은 결정도 끝없는 기다림보다 나을 수 있어요.","망설임 뒤에는 잘하고 싶은 진심이 있을 때가 많아요.","차이가 조화를 없애는 건 아니에요. 오히려 깊이를 더합니다.","부드럽게 고른 선택도 분명한 선택입니다."],"roast":["비교를 지나치게 좋아하면 단순히 취향을 말하면 될 선택까지 미루게 돼요.","모두를 배려하려다 자기 생각이 잘 들리지 않을 때가 있어요.","좋은 분위기를 지키고 싶은 마음 때문에 꼭 필요한 대화를 피할 수 있어요.","두 선택지가 비슷할 때 즐기는 시간보다 비교하는 시간이 더 길어질 수 있어요.","지나치게 공손한 태도는 원치 않는 일에도 동의하는 듯 보이게 할 수 있어요.","매력적인 모습 뒤에는 분명한 답이 필요한 진짜 망설임이 있어요.","주변의 의견은 생각을 풍부하게 하지만 결정을 대신할 필요는 없어요.","대화가 조금 불편해져도 조화를 사랑하는 당신의 가치는 변하지 않아요."]},"funny":{"career":["당신의 이상적인 회의는 모두가 동의할 때 끝나요. 그러니 다음 분기까지 계속될 수 있겠군요.","발표 자료 디자인 두 개를 비교한 뒤 색상 선택에 대한 세 번째 의견까지 구합니다.","동료들이 다투면 곧바로 중재자가 돼요. 화해를 위한 음료까지 이미 준비했죠.","팀 식당을 정해 달라는 부탁에 설문조사를 만듭니다. 그 설문조사를 위해 또 다른 설문조사가 필요해요.","빨리 결정해 달라는 요청은 당신에게 거의 운동 경기 같은 도전이에요.","외교적인 미소 뒤에는 아마도라는 말로 시작하는 이메일 초안 열두 개가 있어요.","표의 색상에 너무 관심이 많아서 숫자들이 조금 소외감을 느낍니다.","모든 의견을 듣는 재능은 엄청나요. 시계마저 자기 의견을 내기 시작합니다."],"love":["당신의 로맨스는 촛불 저녁과 산책 사이에서 망설여요. 마음속으로 둘 다 예약합니다.","상대에게 볼 영화를 골라 달라고 하죠. 답을 듣고 나면 새로운 후보 네 개가 떠올라요.","선물 하나를 고르는 과정이 너무 정교해서 전시회를 열어도 될 지경이에요.","어디서 먹을지 정해 달라는 말을 들으면 깜짝 시험을 치르는 사람처럼 품위 있게 웃습니다.","예쁜 선물에 감동하지만 포장지와 리본, 색깔의 조화에도 똑같이 감탄해요.","타고난 매력 뒤에서는 좋은 밤 인사를 어떤 방식으로 할지 보이지 않는 위원회가 토론 중이에요.","다툼이 싫어서 정반대 의견 둘을 모두 놀라울 만큼 부드럽게 설명합니다.","당신의 마음은 미적 감각이 뛰어나요. 다만 메뉴를 볼 때 원하는 것이 좀처럼 정해지지 않죠."],"wellbeing":["당신의 휴식은 분위기 선택에서 시작해요. 향초 세 개를 켠 뒤에도 조명이 마음에 드는지 고민합니다.","산책을 계획하고 아름다운 공원 두 곳 중 어디가 더 좋을지 10분 동안 비교해요.","소파의 쿠션은 절대 완벽한 위치에 있지 않아요. 마음속에서 쿠션과 협상합니다.","친구가 뭘 하고 싶냐고 물으면 진심으로 편한 대로 하라고 답합니다. 무서운 말이죠.","잔잔한 음악을 틀려다 똑같이 훌륭한 곡들 사이에서 어려운 결정을 내려야 해요.","평화를 사랑하지만 꽃병의 의견까지 물어보지 않고 결정할 때도 있어야 해요.","예쁜 물건은 마음을 쉬게 해 줍니다. 그러다 머릿속에서 방 전체를 다시 배치하죠.","완벽한 오후라면 어떤 결정도 할 필요가 없겠죠. 그 오후를 어떻게 보낼지부터 결정해야 하지만요."],"wisdom":["균형을 맞춘다고 과자 하나마다 투표할 필요는 없어요.","두 가지 다 좋아해도 가게 문 닫기 전에 하나는 고를 수 있어요.","좋은 취향을 증명하는 데 증인 열두 명은 필요 없습니다.","평화를 사랑하다 결정을 못 하겠다면 이번엔 메뉴에게 맡겨 보세요.","개인의 의견 하나가 자동으로 국제회의를 부르지는 않아요.","모든 망설임 뒤에는 가끔 소파가 기다리고 있을 뿐이에요.","서로 다른 생각은 공존할 수 있지만 굳이 버스를 운전할 필요는 없어요.","무작위로 고르는 것도 선택이에요. 주사위라면 당신보다 잘 설명하겠죠."],"roast":["당신의 가장 빠른 결정은 의견을 하나 더 묻겠다는 결정이에요.","다툼을 피하는 솜씨가 너무 좋아서 길을 막는 문에게도 사과합니다.","식당 메뉴는 당신을 잘 알아요. 여러 결말이 있는 소설처럼 읽으니까요.","취향을 물으면 두 가지의 장점을 다 설명하고 정작 질문은 잊어버려요.","주변에서 다툼이 시작되면 중재팀을 출동시키고 냅킨부터 나눠 줍니다.","매력적인 미소 뒤에서 상상 속 고문들이 쿠션 색깔 하나를 두고 회의 중이에요.","예쁜 물건을 너무 좋아해서 클립마저 우아한 선을 가져야 해요.","당신의 배려는 전설적이에요. 거울이 잘못 비춘다는 말도 아주 정중하게 전할 수 있죠."]},"piquant":{"career":["당신의 우유부단함은 스테이플러 고르기를 외교 정상회담으로 만들었어요. 대표단은 폐회 날짜를 요구합니다.","세 단어짜리 이메일을 보내기 전에 동료 여덟 명의 의견을 구해요. 답장이 질문보다 먼저 도착했습니다.","작은 의견 충돌에도 조화위원회를 만들고 싶어 해요. 아무도 거절할 용기가 없었죠.","상사가 결정을 요구하면 어느 쪽에도 기울지 않은 비교표를 제출합니다. 표의 열들마저 결론을 거부해요.","발표 자료의 색들이 서로 존중하는지가 가장 중요해요. 예산은 복도에서 기다립니다.","모두에게 동의하는 미소 뒤에서 부서 전체가 당신의 진짜 생각을 찾고 있어요. 사건은 미학 분야로 분류됐습니다.","협상을 너무 좋아해서 문제 자체의 장점까지 찾아냅니다. 문제는 승진을 요구해요.","당신의 외교 실력은 완벽해요. 아무것도 결정하지 않기로 모두의 합의를 얻었죠. 회의록이 감사 인사를 보냅니다."],"love":["당신의 매력은 길을 묻는 사람에게까지 작동해요. 그 사람은 가상의 초대장 세 장을 들고 돌아갑니다.","데이트 장소 두 곳에서 망설이다가 세 곳, 다섯 곳으로 늘려요. 달력은 주말 양육권을 요청했습니다.","낭만적인 저녁은 편한 대로 하세요라는 말로 시작해요. 마흔 번 제안하는 사이 식당이 문을 닫았습니다.","진짜 의견을 묻는 질문에 가구 하나도 상처받지 않을 표현을 내놓아요. 안락의자가 박수를 칩니다.","다툼이 생길 것 같으면 놀라운 우아함으로 화제를 바꿔요. 방금 스탠드를 칭찬했군요.","조화를 향한 열망 뒤에서 당신의 취향은 행정 격리 조치 중이에요. 면담을 신청했습니다.","칭찬이 너무 자연스러워 카페 직원은 자기 생일 파티에 초대받은 건지 헷갈려요.","당신의 마음은 완벽하게 균형 잡힌 동화를 꿈꿔요. 등장인물들은 표지 고르기가 끝나길 기다립니다."],"wellbeing":["평온함을 찾다가 향초 향 두 가지 앞에서 멈춰 섰어요. 향초 평의회는 입장을 정하지 못했습니다.","휴식을 준비하느라 쿠션을 40분 동안 비교했어요. 휴식은 예약을 취소했습니다.","공원에서 벤치 하나 고르는 일도 조명과 전망, 조화에 관한 연구가 됩니다. 비둘기들은 두 벤치를 다 차지했어요.","깜짝 산책을 제안받자 어느 경로도 서운하지 않게 대안을 모두 보여 달라고 요청합니다.","차 한 잔으로 쉬려다가 컵 선택 문제가 생겨요. 찬장은 미적 괴롭힘으로 민원을 냅니다.","전설적인 다정함 뒤에서 편안한 음악 두 목록이 내전을 벌여요. 침묵이 부전승을 거뒀습니다.","계획 없는 휴가를 꿈꾸면서 계획 없는 휴가를 고르는 계획표를 만들었어요.","평온한 순간을 위해 커튼과 꽃, 담요의 동의가 필요해요. 고양이가 거부권을 행사했습니다."],"wisdom":["조화를 바라는 마음이 동전의 양면까지 소집했어요. 양측은 아직 중재 중입니다.","의견이 없는 게 아니에요. 너무 많아서 각자 자리를 배정할 수 없죠.","타협은 훌륭해요. 식사 메뉴를 두고 화분들에게 투표시키는 건 조금 덜 훌륭합니다.","길 두 개가 열리면 건축가를 불러 세 번째 길을 만들게 해요.","결정을 미룬다고 더 우아해지는 건 아니에요. 리본만 하나 더 달릴 뿐이죠.","외교적인 태도 뒤에는 월요일부터 기다린 투표용지 한 장이 있어요.","거울은 있는 것을 비출 뿐이에요. 그런데 당신은 아직도 어느 거울이 맞느냐고 묻습니다.","선택한다고 나머지 후보들을 공격하는 게 아니에요. 후보들도 잘 견딜 겁니다."],"roast":["당신의 우유부단함에는 자문위원회와 대리위원 세 명까지 있어요.","물 한 잔을 놓고 직원 의견을 물었어요. 직원은 수원지까지 소집하자고 제안합니다.","메뉴는 결말 페이지로 넘어가길 당신이 거부하는 추리소설이에요.","다툼이 시작되면 너무 환하게 웃어서 의자들까지 협상에 나설 의무를 느낍니다.","자기 취향 하나가 머릿속을 스쳐 갑니다. 당신은 즉시 공개 의견수렴에 부치죠.","상냥한 태도 뒤에서 보이지 않는 고문 열두 명이 쿠션 하나를 두고 싸웁니다.","칭찬을 너무 많이 나눠 줘서 주차장마저 자기가 아름다운 줄 압니다.","당신의 긴급 대응이란 결정을 미루기로 신속히 결정하는 일이에요. 회의록은 벌써 준비됐습니다."]},"roastMy":["천칭자리인 당신은 식당을 고르는 게 아닙니다. 주민 공청회를 여는 거죠. 모든 사람의 의견을 모아 비교표를 만들고 마지막 순간 새 후보까지 추가합니다. 결국 일행은 각자 집으로 돌아가요. 당신은 적어도 분위기는 좋았다고 평가합니다.","당신의 외교술이라면 상상 속 적군 둘도 화해시킬 수 있어요. 하지만 디저트 두 개 중 하나는 못 고르죠. 가격과 모양, 식감, 직원 기분까지 따져요. 직원이 진행을 위해 둘 다 권합니다. 당신은 세 번째 선택지가 있느냐고 묻습니다.","당신은 아름다움을 너무 사랑해서 쿠션 하나가 삐뚤어져도 협상이 실패했다고 생각해요. 쿠션을 옮기면 다른 쿠션이 균형을 잃죠. 한 시간 뒤 소파는 전시장이 됩니다. 아무도 앉을 허가를 받지 못했어요.","당신은 취향이 없다고 완벽한 미소로 말해요. 사람들이 여러 의견을 내면 각각의 장단점을 설명하죠. 결국 누군가 제발 싫다고만 말해 달라고 부탁합니다. 당신은 그렇게 거절해도 예의에 어긋나지 않느냐고 묻습니다.","당신의 매력은 대량 평화 무기예요. 서비스와 장식, 영수증까지 칭찬하죠. 가게 주인이 친절하게 답하자 너무 적극적이었나 걱정합니다. 영수증 하나를 두고 중재 위원회가 생겨요.","당신은 다툼을 피하는 전문가예요. 친구 둘이 논쟁하면 똑같은 확신으로 번갈아 동의하죠. 결국 누구 편인지 묻습니다. 당신은 세 계절 동안 계속될 차 마시는 휴식을 제안합니다.","옷을 고르는 모습은 박물관의 상설 전시를 준비하는 것 같아요. 옷마다 장점과 분위기, 관람 대상이 정해져 있죠. 결국 첫 번째 옷을 고르고는 정말 최선이었는지 다시 묻습니다. 옷장은 과도한 자문에 대한 배상을 요구해요.","당신은 공정함을 너무 추구해서 마지막 케이크 조각에게 먹히고 싶은지 나뉘고 싶은지 물어요. 누구도 케이크 대신 답하지 못하죠. 그래서 공평한 순환 배분제를 만듭니다. 케이크가 신속한 결정을 요구해요.","모두에게 좋은 인상을 주고 싶어 서로 반대되는 의견 둘에도 동의합니다. 그다음 두 입장을 양립시키려 다시 설명하죠. 사전마저 증언을 거절합니다. 당신은 사전이 지나치게 단정적이라고 생각해요.","당신은 갈등도 불편한 선택도 없는 조화로운 삶을 꿈꿔요. 하지만 매일 아침 똑같이 예쁜 컵 두 개와 마주합니다. 찬장 앞에서 두 컵의 장점을 끝없이 비교하죠. 주전자는 다른 부서로 옮겨 달라는 신청서를 냈습니다."]},"scorpio":{"classic":{"career":["당신의 통찰력은 다른 사람들이 아직 말하지 않은 핵심을 알아차리는 데 도움이 돼요.","의미 있다고 느끼는 프로젝트에는 강한 집중력을 쏟습니다.","사람들의 동기를 이해하려는 마음은 전략적인 강점이 될 수 있어요.","신뢰를 주기로 결정하면 함께하는 일에 깊이 헌신해요.","강한 직관도 사실과 맞춰 본 뒤 결정에 활용하면 더 좋아요.","조용한 모습 뒤에는 어려운 상황을 체계적으로 헤쳐 나가는 끈기가 있어요.","복잡한 상황일수록 겉모습 너머를 살피려는 마음이 강해져요.","다른 사람도 자기 방식으로 나아가도록 허락하면 결단력이 더 큰 힘을 발휘합니다."],"love":["당신의 깊은 감정은 진실하고 깊이 있는 관계를 바라게 해요.","신뢰를 신중하게 주는 편이죠. 서로에 대한 믿음도 각자의 속도로 자라납니다.","관계에서 진실을 추구하는 마음과 부드러운 경청은 함께할 수 있어요.","감정이 찾아왔을 때 말로 표현하면 멀어지기보다 가까워질 수 있어요.","단단한 관계를 위해 상대의 모든 생각을 알아야 하는 것은 아니에요.","겉으로는 절제해 보여도 깊이 함께할 수 있는 사람이에요.","함께한 추억을 소중히 여기되 현재를 거기에 묶어 두지는 마세요.","당신의 성실함은 서로의 자유를 존중할 때 진정한 의미를 얻습니다."],"wellbeing":["강렬한 마음에도 당장 답을 내지 않아도 되는 공간이 필요해요.","주변을 이해하려는 걸 좋아하지만 산책만큼은 해석 없이 즐겨도 괜찮아요.","익숙한 장소의 고요함은 발을 땅에 딛고 있다는 느낌을 줄 수 있어요.","생각이 멈추지 않을 때 잠시 대화에서 벗어나 숨 쉴 틈을 주세요.","창의적인 활동은 깊은 내면에 평화로운 출구를 마련해 줍니다.","경계심 많은 당신에게도 아무것도 감시하지 않는 기쁨이 필요해요.","가까운 사람들과의 솔직한 대화가 무거운 침묵을 가볍게 할 수 있어요.","혼자 있는 시간은 선택일 때 더 건강한 의미를 가집니다."],"wisdom":["무엇을 놓아줄지 선택하는 순간에도 강함이 드러납니다.","진실을 찾되 모든 것을 알아야 한다고 생각하지 않아도 됩니다.","비밀은 지켜 줄 때도 있지만 신뢰는 사람을 가깝게 합니다.","직관이 대화에 열릴 때 이해로 자라납니다.","깊은 감정이 모든 결정을 지배할 필요는 없어요.","의심 뒤에는 진심 어린 연결을 바라는 마음이 기다릴 수 있어요.","가장 의미 있는 침묵은 무언가 숨기지 않고 편안함을 줄 때 찾아옵니다.","이해한다는 것은 통제한다는 뜻이 아닙니다."],"roast":["말하지 않은 뜻을 알아채는 재능이 아무 의미 없는 곳에서도 의미를 찾게 할 수 있어요.","내면을 철저히 감추다 보면 자신의 의도를 주변에 전하기 어려워져요.","오래된 의견 충돌을 이야기하지 않은 채 간직하면 마음속에서 차지하는 자리가 커져요.","모호한 대답을 받으면 호기심이 심문처럼 들릴 위험이 있어요.","직관이 아무리 확신에 차도 언제나 증거가 되는 건 아니에요.","모든 것을 이해하려는 마음이 지나친 통제로 이어지면 대화가 지칠 수 있어요.","지키고 있는 비밀마다 자물쇠를 하나씩 더 달 필요는 없어요.","한번 내린 인상을 지키려는 마음에도 새 설명을 받아들일 여지가 필요해요."]},"funny":{"career":["회의 중 당신의 눈빛은 복사기에게 종이가 부족하다는 자백까지 받아냅니다.","일정이 바뀐 이유를 조사하는 모습은 국제적인 미스터리 사건을 맡은 것 같아요.","기밀 문서 한 장도 은행 금고에 들어갈 만큼 엄중하게 다룹니다.","동료가 나중에 설명할게요라고 하면 벌써 왜 나중인가라는 사건 파일을 열었어요.","서류가 잘못 분류된 사소한 실수 하나에서 옛 회의 세 번으로 이어지는 단서를 찾아냅니다.","조용한 책상 뒤에서 머릿속은 탐정처럼 끈기 있게 단서를 짜 맞추고 있어요.","복도에서 들리는 작은 대화가 너무 궁금해서 화분마저 수상해 보입니다.","관찰력이 뛰어나서 누군가 펜을 제자리에 놓기도 전에 누가 옮겼는지 알고 있어요."],"love":["당신의 강렬한 눈빛은 오늘 뭐 먹을까라는 질문도 긴장감 넘치는 장면으로 만들어요.","대화의 작은 부분까지 기억하는 솜씨는 기록관리자도 놀랄 수준이에요.","진실을 알고 싶어 너무 일찍 온 지금 가요 메시지까지 수사할 때가 있어요.","비밀을 털어놓으면 머릿속의 여러 겹 잠금장치가 있는 금고에 보관해요.","깜짝 이벤트를 좋아하죠. 사흘 전에 이미 단서를 다 찾아냈어도요.","신비로운 표정 뒤에서는 적절한 순간에 들었던 칭찬을 다정하게 기억하고 있어요.","아주 짧은 메시지를 보면 고민에 빠져요. 당신에게 알겠어 한마디도 거대한 줄거리가 될 수 있거든요.","당신의 사랑은 끝을 이미 아는 조용한 주인공이 등장하는 흥미진진한 소설 같아요."],"wellbeing":["산책길에 벤치 두 개가 수상할 만큼 비어 있으면 갑자기 수사가 시작됩니다.","조용한 저녁을 보내려는데 옆집에서 의자를 옮기는 소리가 들려요. 새로운 음모가 탄생했습니다.","쉬려고 고른 소설에 비밀이 열 개나 나와요. 당신은 아주 편안함을 느낍니다.","구름을 보면서도 어느 구름이 뭔가를 숨기고 있는지 알아내려 해요.","따뜻한 차 한 잔이 생각을 도와줘요. 차는 자신이 조용히 심문받는다는 걸 모릅니다.","혼자 있고 싶은 마음 뒤에는 담요와 오래된 드라마로 이뤄진 믿음직한 팀이 있어요.","퍼즐은 마음을 편안하게 해요. 아무도 마지막 조각을 일부러 숨기지 않았다면요.","완벽한 휴식에는 놀라운 일이 없어야 해요. 그래서 쿠션 밑을 두 번 확인하죠."],"wisdom":["직관에도 휴가가 필요해요. 토스터는 용의자가 아닙니다.","질문 하나를 하기 위해 심문실부터 준비할 필요는 없어요.","미스터리는 매력적이지만 모든 봉투에 음모가 들어 있는 건 아니에요.","오래된 불만을 내려놓으면 사건 파일 서랍 하나를 비울 수 있어요.","비밀을 들었다고 꼭 여섯 자리 암호를 정할 필요는 없습니다.","침묵마다 폭로가 숨어 있는 건 아니에요. 그냥 누군가 씹고 있는 중일 때도 있어요.","단서는 유용해요. 단서를 뒷받침하려고 지어 낸 증거는 그렇지 않죠.","신뢰한다고 매번 금고의 자물쇠를 확인할 필요는 없습니다."],"roast":["당신의 눈빛만으로 삐걱거리는 의자가 알리바이를 확인합니다.","비밀을 너무 철저히 지켜서 주인조차 털어놓은 사실을 잊어버릴 정도예요.","읽음만 뜨고 답장이 없는 메시지는 즉시 첩보소설 1장이 됩니다.","누군가 아무 일 아니라고 하면 용의자 관계도를 바로 그립니다.","오래된 서운함은 날짜가 정확히 적힌 상자에 보관돼 있어요.","당신의 차분함 뒤에서는 화요일에 사라진 과자 한 봉지에 관한 조사가 아직 진행 중이에요.","당신에게 깜짝 선물은 어려워요. 포장지의 리본까지 벌써 심문하고 있으니까요.","신비로운 모습이 너무 강해서 추리소설 속 수상한 이웃마저 당신을 무뚝뚝하다고 생각해요."]},"piquant":{"career":["당신의 의심은 함께 마시는 커피를 정보 작전으로 바꿉니다. 설탕은 잠재적 공범으로 등록됐어요.","단순한 시간 변경을 비밀 권력 이양처럼 조사합니다. 일정표는 변호사를 요구했어요.","내일 얘기하자는 동료의 말로 열두 시간짜리 수사가 시작됩니다. 내일은 아직 오지도 않았어요.","모르는 정보가 하나라도 있으면 특별수사반을 꾸립니다. 비밀은 과자 고르기였어요.","비공개 회의 하나가 탐정 본능을 깨워요. 회의실에서는 의자 유지보수를 이야기하고 있었습니다.","전략적인 침착함 뒤에서 보이지 않는 파일이 팀원들의 한숨을 분류합니다. 복사기가 1위예요.","직장 내 경쟁 관계가 보고서 숫자보다 더 흥미로워요. 보고서는 제발 자신을 읽어 달라고 부탁합니다.","날카로운 시선은 그래프의 막대 밑에서도 진실을 찾으려 해요. 막대들은 증언을 거부합니다."],"love":["당신의 강렬함은 단순한 나중에 보자를 민감한 사건으로 만들어요. 나중이라는 단어가 감시 대상이 됩니다.","믿는다고 말하면서 준비 중인 깜짝 선물이 정말 깜짝 선물인지 확인합니다. 포장지는 변호사를 요청했어요.","마침표가 없는 메시지도 수상하고 있는 메시지도 수상해요. 문장부호는 어느 쪽이든 소환됩니다.","누군가 아무 생각 안 했다고 하면 마음속 법정은 사건의 전말을 재현하라고 요구합니다.","옛말 한마디를 기억 속 기록물에 보관해요. 사건 번호와 재검토 날짜까지 붙어 있습니다.","매력적인 신비감 뒤에는 어제 어디 있었느냐고 침묵을 심문하는 조사관이 있어요. 침묵은 답변을 거부했습니다.","비밀을 털어놓는 일은 감동적이지만 당신의 엄숙한 표정 앞에서 곧바로 국가기밀로 격상돼요. 다정함은 보안 인가를 기다립니다.","당신의 마음은 깊이를 좋아해요. 그래서 날씨 이야기조차 가끔 구름에 대한 심문으로 끝나죠."],"wellbeing":["통제 욕구 때문에 평화로운 산책도 순찰 업무가 됩니다. 비둘기들은 조직적으로 움직였다는 의심을 받아요.","빈 방에서 평온함을 찾았다가 왜 비어 있는지 의심합니다. 의자는 알리바이를 제출해야 해요.","쉬고 싶어도 오래된 알림 하나가 종결된 사건을 다시 엽니다. 쿠션은 평화를 누리지 못해요.","눈을 감고 쉬려는데 상상력은 수사실을 열어요. 휴식은 아직 경찰서에 있습니다.","조용히 차를 마시는 순간도 지나치게 조용해서 수상해요. 티백은 정밀 심문을 받습니다.","침묵 뒤에서는 이웃이 마지막으로 왜 한숨을 쉬었는지 가설들이 싸우고 있어요. 시계는 증언을 거부합니다.","아무 일 없는 날이 오히려 더 불안해요. 달력은 이불 밑에 숨었습니다.","당신의 내려놓기란 내려놓은 물건을 가까이서 계속 지켜보는 일이에요. 자유는 호위대를 요구합니다."],"wisdom":["당신의 서운함 기록 보관소는 관청보다 자료가 많아요. 서류철들은 사면을 거부합니다.","당신은 답을 찾는 게 아니에요. 우연을 심문대에 올리는 거죠.","신비감이 항상 배신을 숨기는 건 아니에요. 가끔은 그냥 닫힌 서랍입니다.","다 잊었다고 말하면 그 사건 파일에는 보안 도장이 하나 더 찍힙니다.","빛나는 직감이 자동으로 믿을 만한 증인이 되는 건 아니에요. 배심원은 증거를 기다립니다.","당신은 침묵마다 전략을 상상해요. 침묵은 단지 조용히 쉬고 싶었을 뿐입니다.","비밀은 스스로도 잘 지켜져요. 그런데 당신은 전용 벙커까지 지었습니다.","믿는다는 말이 믿음을 감시할 탐정까지 고용한다는 뜻은 아니에요."],"roast":["당신의 앙금은 너무 잘 분류돼서 기록보관소와 민원 창구까지 갖췄어요.","당신의 신뢰는 잃어버린 열쇠를 대하는 금고만큼 조심스러워요.","옆방의 웃음소리 하나가 사건이 됩니다. 이웃들은 그냥 애니메이션을 보고 있었어요.","깜짝 선물이라는 말에 즉시 정보 유출 경로부터 찾습니다. 선물은 아직 포장도 안 풀렸어요.","평범한 대화도 당신의 교차검증 자료 파일로 들어가요. 쉼표들마저 보호를 요청합니다.","신비로운 눈빛 뒤에서 누군가는 지난 화요일 사라진 과자를 아직도 조사 중이에요.","비밀은 당신과 있기를 좋아해요. 명패와 암호, 면회 시간까지 제공받으니까요.","당신의 용서는 조건부 석방과 같아요. 옮겨진 의자마저 보호관찰 대상입니다."]},"roastMy":["전갈자리인 당신은 대화를 듣는 게 아닙니다. 사건 기록을 작성하는 거죠. 잠깐의 멈춤과 눈빛, 빠진 쉼표 하나가 모두 증거가 됩니다. 누군가 냅킨이 어디 있냐고 물어요. 당신은 증인 이름부터 요구합니다.","당신의 서운함 기억은 국립 기록보관소 같아요. 다만 종결되는 사건이 하나도 없다는 점이 다르죠. 비 오는 화요일 누군가 플레이리스트에 대해 했던 말도 기억해요. 그 사람은 자신이 조사 대상인 줄도 모릅니다. 용서 담당 부서는 재고 조사로 휴업 중이에요.","당신은 미스터리를 좋아한다고 말해요. 사실은 미스터리 뒤의 또 다른 미스터리, 그 뒤에 숨은 무엇인가를 의심하는 거죠. 닫힌 문 하나를 조사하기 시작합니다. 알고 보니 찬장이었어요. 이제 찬장은 증인이 없으면 당신을 만나지 않겠답니다.","당신의 강렬한 눈빛은 카페 직원이 심문받고 있는 듯 느끼게 해요. 직원은 창가에 앉고 싶은지만 물었죠. 당신은 출입구 위치를 확인한 뒤 답합니다. 직원은 계산대로 전근을 신청했어요.","당신은 공휴일의 은행 금고만큼 너그럽게 신뢰를 나눠 줘요. 비밀을 나누려면 열쇠와 암호, 추천장이 필요하죠. 일단 가까워지면 누구보다 성실하게 관계를 지킵니다. 금붕어마저 비밀유지 계약에 서명해야 해요.","당신은 누구도 숨기는 게 없을 때조차 모든 것을 이해하려 해요. 상대가 네라고 답하자 말투와 답변 시간, 이모지 부재를 조사하죠. 결론은 중대한 비밀의 존재입니다. 상대는 그냥 네라고 한 거였어요.","당신의 침착함 앞에서 물건들도 긴장해요. 쏟아진 커피잔을 국제 수사관처럼 바라보죠. 테이블은 심문받고 행주는 용의자가 되며 커피는 현장 재현을 거부합니다. 고양이는 증거 불충분으로 면책됐어요.","당신은 지난 일을 넘겼다고 말해요. 맞아요, 페이지를 넘기고 책갈피를 꽂은 뒤 사본까지 보관했죠. 세 시즌 뒤 비슷한 말을 들으면 사건 파일이 다시 열립니다. 추억 법정은 비공개로 열려요.","당신의 비밀 사랑은 깜짝 간식 파티를 기밀 작전으로 만들어요. 시간도 장소도 접시 색깔도 알려 주지 않죠. 손님들은 암호화된 지시를 받고 따로 도착합니다. 케이크는 그냥 초대장 한 장을 요청해요.","당신은 깊은 관계를 좋아하지만 가벼운 질문조차 역사적인 사건으로 만들어요. 하루 어땠냐는 말에 의미심장한 침묵으로 답합니다. 상대는 계속 기다려요. 침묵마저 공인 통역사를 요구합니다."]},"sagittarius":{"classic":{"career":["자유를 사랑하는 마음은 익숙한 틀을 벗어나야 하는 프로젝트에 새로운 바람을 불어넣어요.","큰 아이디어도 목표에 닿으려면 때로는 더 자세한 경로가 필요해요.","솔직함은 적절한 때를 골라 표현할수록 힘을 얻어요.","반복되는 업무에 의욕이 떨어진다면 배울 수 있는 부분을 찾아보세요.","당신의 열정적인 낙관은 팀이 더 넓은 가능성을 보게 만들 수 있어요.","빨리 나아가고 싶은 마음 뒤에는 동떨어진 생각들을 잇는 귀한 능력이 있어요.","업무에서는 자율성을 바라는 마음과 명확한 약속이 함께할 때 조화로워져요.","새로운 방식을 탐색하면 노력을 분산하지 않으면서도 창의력을 키울 수 있어요."],"love":["혼자만의 공간이 필요하다고 소중한 사람에게 진심을 다하지 못하는 것은 아니에요.","솔직한 말은 상대방에게도 이야기할 여지를 남길 때 관계를 더 가깝게 해요.","자발적인 성향은 애정 어린 대화에 신선함을 더해요.","멀리 떠나고 싶어질 때 그 바람을 나누면 더 깊은 대화가 열릴 수 있어요.","타고난 낙관은 관계를 밝게 하지만 잔잔한 감정도 소중히 받아들여 보세요.","모험을 사랑하는 마음 뒤에서는 그 자유를 존중하는 관계도 찾고 있어요.","관계 속 신뢰는 끊임없이 설명하지 않아도 각자 숨 쉴 공간을 줍니다.","상대방의 다른 속도를 받아들이면 이미 소중한 친밀함이 더 깊어질 수 있어요."],"wellbeing":["여행을 좋아하는 에너지는 정해진 목적지 없는 산책에서 균형을 되찾을 수 있어요.","두 프로젝트 사이의 휴식은 열정을 오래 이어가게 합니다.","자유란 아무 일정도 없는 오후의 모습일 수도 있어요.","생각이 내일로 달려갈 때 지금 주변에 있는 것에도 주의를 기울여 보세요.","새로운 곳을 찾고 싶다면 가까이 있지만 잘 모르는 장소를 탐험해 보세요.","움직이고 싶은 마음이 커도 평온한 잠자리에는 자기 자리가 필요해요.","수많은 가능성 속에서 사랑하는 사람과 나누는 소박한 순간을 선택해 보세요.","스스로 속도를 늦춘다고 시야가 좁아지지 않아요. 오히려 풍경을 감상할 시간이 생깁니다."],"wisdom":["자유는 한 약속을 지킬 때 더 넓어집니다.","먼 지평선을 향하는 길도 눈앞의 한 걸음에서 시작됩니다.","솔직함은 돌아올 수 있는 문을 남길 때 더 소중합니다.","모든 모험은 돌아오는 시간을 받아들일 때 깊이를 얻어요.","낙관에는 큰 약속보다 분명한 기준이 도움이 됩니다.","탐험은 꼭 떠나는 것만이 아니에요. 귀 기울이는 것만으로도 충분할 수 있습니다.","진정한 추진력은 함께 걷는 이들의 속도도 존중합니다.","세상을 이미 다 안다고 믿는 것만큼 시야를 좁히는 일은 없습니다."],"roast":["자유를 갈망하다 보면 모든 계획을 불필요한 구속으로 착각할 때가 있어요.","열정적으로 한 약속도 희미한 기억으로만 남아서는 안 돼요.","진실을 말하는 건 쉽지만 그 진실을 포장하는 배려가 부족할 때가 있어요.","대화가 진지해지면 마음속에서 다른 창을 열고 싶어져요.","감탄스러운 낙관도 실무적인 세부 사항은 종종 빠뜨립니다.","새로운 것을 바라는 마음 뒤에서 몇몇 프로젝트는 여전히 결론을 기다려요.","빡빡한 일정표를 보면 비상구부터 찾고 싶어지는군요.","새로운 아이디어를 향해 떠나는 일이 어제 시작한 일을 마치는 것보다 더 즐거워요."]},"funny":{"career":["모험을 좋아해서 책상 두 개 사이를 오가는 일도 원정이 됩니다. 복도에는 이미 발견의 길이라는 이름을 붙였어요.","계획 회의가 잡히면 기발한 생각이 떠올라요. 회의가 시작하기 전에 떠나자는 거죠. 달력은 기분이 상했습니다.","솔직함 덕분에 발표에 슬라이드가 40장이나 많다고 말해요. 첫 두 장만 보고도 다 셌다고 주장하죠.","실행 계획을 요청받으면 세계지도를 보여 줍니다. 팀은 그냥 프린터를 옮기려던 건데요.","열정에 휩쓸려 점심 전에 프로젝트 다섯 개를 수락합니다. 오후에는 여행 안내자로 이직할까 고민해요.","책상 뒤에는 언제든 떠날 준비가 된 여행가방이 있어요. 요즘은 긴급 문서 보관함으로 쓰입니다.","절차라는 말을 듣자마자 반사적으로 출구를 살펴요. 사내 규정조차 지나치게 극적이라고 생각합니다.","가능성을 탐색하는 게 너무 즐거워서 업무 목록표를 상상 속 여행지 안내 책자로 바꿔 놓았어요."],"love":["자유를 향한 당신의 낭만은 저녁 초대장에도 목적지 미정이라는 선택지를 넣어요.","사랑을 고백한 바로 다음 순간 이번 주말 다른 대륙으로 가 보자고 제안합니다.","솔직함 때문에 저녁 요리를 심사위원처럼 평가해요. 상대는 맛있었느냐고만 물었는데요.","즉흥적으로 하자고 말하면 가까운 사람들이 몰래 여권 유효기간을 확인합니다.","낙관적인 당신에게 비 오는 나들이도 아름다운 모험이에요. 다른 사람들은 아직 비를 피할 곳을 협상 중입니다.","조용한 데이트를 하다가도 아무도 부탁하지 않은 동네 구석을 탐험할 기회라고 생각해요.","식당에서 꿈꾸는 미래를 이야기합니다. 넓은 공간과 반복 없는 일상, 나눌 디저트가 포함돼요.","놀라움 없는 저녁을 약속하는 건 괜찮아요. 식사 뒤의 비밀 활동을 예약했을 뿐이니까요."],"wellbeing":["이상적인 휴식이 즉흥적인 등산처럼 보여요. 소파는 자기도 참여할 기회를 달라고 합니다.","10분 산책이 세 동네 탐험으로 변해요. 그 길이 흥미로워 보였다는 이유로 우회도 하죠.","낮잠은 너무 정적이에요. 기차 안에서 자면 한 번에 두 가지를 할 수 있다고 제안합니다.","속도를 늦추라는 말을 들으면 즉시 어느 방향으로요라고 묻습니다.","아침의 열정으로 창문을 활짝 열며 위대한 모험의 시작을 선포하는 듯해요.","탈출을 꿈꾸는 마음 뒤에는 단순한 진실이 있어요. 안락의자 위치만 바꿔도 기분이 달라질 수 있죠.","쉬려고 앉았다가 먼 나라 영상을 틀어요. 세 시간 뒤에는 여행 일정이 완성돼 있습니다.","바람을 쐬고 돌아오면 여행 아이디어는 여섯 개 생기지만 지금 몇 시인지는 몰라요."],"wisdom":["설거지를 피하는 데 비행기표까지 필요한 건 아니에요.","약속은 떠나기 전에 적어 둬야 잃어버리지 않는 추억이에요.","진실은 뛰어들지 않고 들어올 때 더 아름답게 들려요.","모든 지평선은 방문할 가치가 있죠. 빨랫감도 자기 차례를 기다립니다.","당신의 낙관은 산도 옮길 수 있지만 열쇠를 찾아 주지는 못해요.","세상 탐험은 고귀해요. 충전기를 찾는 일도 마찬가지죠.","모험은 가끔 약속 시간을 읽는 데서 시작됩니다.","열린 일정표가 즉흥성을 막는 법은 없어요."],"roast":["여행가방이 일정표보다 더 안정적이에요. 언제나 같은 자세로 준비돼 있거든요.","정확한 시간이 적힌 초대장은 이미 너무 권위적으로 느껴져요.","솔직함을 명함처럼 내밀어요. 사람들은 가끔 필터 있는 버전이 있느냐고 묻습니다.","5분이면 된다고 말하면 모두 이번 분기 안에는 되겠지라고 이해합니다.","당신의 낙관이라면 폭풍 한가운데 소풍을 예약하고 현장 체험이라고 부르겠죠.","반복을 거부하는 마음 뒤에는 아주 규칙적인 습관 하나가 있어요. 반복을 피하는 반복이죠.","잠깐 조용해지면 자유의 의미에 관한 강연을 시작해요. 고양이는 잠을 자고 싶었을 뿐인데요.","어디로 가는지 몰라도 떠나는 걸 좋아해요. 장을 보지 않고 돌아오는 건 다른 사람들에겐 덜 즐겁죠."]},"piquant":{"career":["일정표를 싫어해서 모든 지각을 창의적 자유라고 부릅니다. 마감 기한이 신분 도용으로 고소했어요.","정확한 지시를 받으면 부서를 혁명하고 싶어져요. 파일 이름만 바꾸면 됐는데 파일은 망명을 신청했습니다.","솔직함이 특기라 프로젝트 첫 장을 읽기도 전에 터무니없다고 선언해요. 첫 장은 공식 답변을 준비합니다.","문서 하나를 맡으면 열정이 즉시 다른 문서를 찾으러 떠나요. 첫 문서는 작전 중 실종 처리됐습니다.","낙관 덕분에 빼곡한 달력도 멋진 가능성의 들판이 됩니다. 가능성들은 이미 변호사를 찾고 있어요.","당신의 원대한 꿈 뒤에는 물류 문제가 하나 있어요. 약속들이 일정표에서 거주 허가를 받은 적이 없습니다.","첫 회의록을 보자마자 책상 독립을 선언합니다. 문구용품들은 주민투표를 요구해요.","끝내는 것보다 탐색하는 일이 고상하다고 생각해요. 반짝이는 아이디어 폴더는 미완성 결론 박물관을 열었습니다."],"love":["자유는 언제나 약속보다 우선입니다. 달력조차 당신에게 접근하려면 예약해야 해요.","낭만적인 약속은 공식 연설처럼 자연스럽게 쏟아져요. 약속관리부는 당신의 주소를 찾고 있습니다.","솔직함으로 저녁 식사를 차량 검사처럼 평가합니다. 디저트는 다른 테이블로 옮겨 달라고 했어요.","관계에서 만날 시간을 정하자고 하면 국제 조약처럼 받아들여요. 협상은 아직 목요일이라는 단어에 머물러 있습니다.","연애에서도 낙관적이라 상대가 놀라움을 좋아하는지 확인하지 않고 여행을 제안해요. 서프라이즈 위원회는 반대표를 던졌습니다.","모험가다운 매력 뒤에는 깨알 같은 조항이 있어요. 날씨와 당일 기분에 따라 이용 가능.","습관이라는 말만 들어도 비상대책반을 떠올립니다. 이야기는 함께 아침을 먹자는 것이었는데요.","5분만 예측 가능하게 행동하겠다는 약속조차 힘들어요. 타이머는 3분이 되기 전에 도망쳤습니다."],"wellbeing":["가만히 있지 못해 쉬는 시간도 정찰 임무로 바꿉니다. 공원 벤치는 방해 배상을 청구해요.","일정 없는 하루는 수상하죠. 자유로운지 확인하려고 별도의 동선을 짭니다.","휴식은 다른 장소에서 할 때만 흥미로워요. 안락의자는 주인을 찾으려고 탐정을 고용했습니다.","평온하게 걸으라는 제안에 가장 먼 길로 돌진해요. 평온하다는 단어가 배지를 반납했습니다.","아침부터 열두 가지 활동을 발표해요. 커피는 노조 대표를 요청합니다.","먼 곳만 찾는 마음 뒤에서는 열린 창문 하나도 영토 확장 작전처럼 보입니다.","잠자리에 들어서 지도를 보며 머리를 식힌다고 해요. 베개는 여권을 신청했습니다.","속도를 늦추면 체면이 상하니 휴식을 수평 탐험이라 부릅니다. 소파는 공식 성명을 거부해요."],"wisdom":["당신의 자유에는 조항이 너무 많아서 바람마저 계약서를 요구합니다.","주인 없이 여행하는 약속은 결국 분실물 보관소로 갑니다.","배려 없는 솔직함은 스스로를 나침반이라 믿는 확성기예요.","모든 길이 좋아요. 특히 책임을 피해 가는 길이요.","당신의 낙관은 세계지도는 있지만 돌아올 주소는 없어요.","끝내지 않고 탐험하는 것은 시작만 유리 진열장에 모으는 일이에요.","모험은 당신을 피하지 않아요. 약속 시간만 확인해 달라고 기다립니다.","당신을 가장 옭아매는 것은 시간표를 극적으로 거부하는 습관입니다."],"roast":["당신의 개인적 자유가 헌법을 만들었어요. 제1조는 다른 사람이 맞춘다. 제2조는 제1조를 따른다입니다.","예약 하나도 기본권 침해로 받아들여요. 식당은 사건을 상상 속 당국에 넘겼습니다.","솔직함은 배려가 현관에 도착하기도 전에 입 밖으로 튀어나와요. 배려는 실종 신고를 냈습니다.","제가 갈게요라고 말하면 시계도 웃음을 터뜨려요. 시간대는 감정을 요청했습니다.","낙관이 너무 커서 끝나지 않은 프로젝트 네 개도 탐험가 경력으로 인정하려 해요. 프로젝트들은 대장을 요구합니다.","언제나 준비된 여행가방 뒤에서 책임감이 메모를 남겼어요. 저를 기다리지 마세요.","서식 하나만 봐도 행정 독재라고 외칩니다. 이름만 쓰면 되는 서식이었는데요.","떠나는 건 좋고 머무는 건 불안하고 돌아오는 건 지루하죠. 현관 매트마저 주인을 알아보지 못합니다."]},"roastMy":["사수자리인 당신은 자유를 너무 사랑해서 알람 시계조차 허가를 받아야 해요. 초대장 세 장에 역사적인 열정으로 답합니다. 정작 당일에는 직감이 이끈다며 다른 곳으로 떠나죠. 초대장들이 당신의 일정표에 버림받은 이들의 협회를 만들었습니다.","당신의 여행가방은 언제든 준비됐는데 장보기 목록은 늘 미완성이에요. 누군가 빵을 사 오라고 하면 상상 속 여행을 계획하죠. 돌아올 때는 샛길에 관한 이야기만 가져옵니다. 빵집이 수배 전단을 만들고 있어요.","당신의 솔직함은 예약 없이 들이닥치는 이삿짐 트럭 같아요. 생각을 그대로 말한 뒤 20분 동안 그게 얼마나 용감했는지 설명합니다. 다른 사람들은 식탁보가 어떤지만 물었는데요. 식탁보는 반론권을 요구합니다.","사수자리인 당신은 역사적인 연설처럼 진심으로 약속해요. 두 시간 뒤 새로운 열정을 발견하고 방향을 바꾸죠. 당신의 약속들은 매달 모여 당신의 위치를 찾으려 합니다. 최근 출석은 선택 사항으로 바꿨어요.","당신의 낙관이라면 닫힌 문 앞에서도 좋은 소식이라고 선언할 거예요. 창문과 다른 길, 새로운 모험을 찾겠죠. 하지만 문에는 당기세요라고 적혀 있을 뿐입니다. 당신의 실용성에 관한 조사위원회가 열렸어요.","당신은 특히 어제 스스로 만든 규칙을 싫어해요. 오늘 계획은 영감을 따르기 한 줄뿐이죠. 정오가 되자 영감은 말도 없이 떠났습니다. 할 일 목록은 이제 실종 일정표를 발행합니다.","자유를 향한 욕구는 작은 약속도 외교 사건으로 만들어요. 저녁 참석을 확인해 달라는 말에 정신의 독립을 이야기하죠. 아무도 당신을 가두려는 게 아닙니다. 네 명이 먹을 식당을 예약하려는 것뿐이에요.","오븐에서 알림음이 울리는 동안 인생의 의미를 철학적으로 설명해요. 자유와 운명, 잊힌 문명까지 강연이 이어집니다. 식사는 30분째 기다리고 있죠. 방금 비자발적 청중 자격을 얻었습니다.","당신은 새로운 출발과 낯선 길, 거대한 아이디어를 사랑해요. 무언가를 끝내는 일은 훨씬 덜 낭만적이죠. 책장에는 쓰다 만 노트 스무 권과 다 써 버린 펜 하나가 있습니다. 펜은 공로 훈장을 요구합니다.","사수자리인 당신의 즉흥성에는 공식 구호가 있어요. 아무것도 계획하지 않았고 모든 게 가능하다. 늦게 도착해 다른 장소를 제안하고 멋진 우회로까지 발표하죠. 친구들에게 필요한 건 가이드가 아닙니다. 이동 조정 본부예요."]},"capricorn":{"classic":{"career":["당신의 끈기는 복잡한 프로젝트에 모두가 의지할 수 있는 구조를 만들어 줘요.","큰 목표일수록 현실적인 단계로 나누고 함께하는 사람들에게 분명히 알려 주세요.","철저한 태도는 중요한 것과 일시적인 급한 일을 구별하는 데 도움이 돼요.","성과가 늦게 나타날 때는 지금까지 걸어온 길의 가치도 떠올려 보세요.","책임감은 신뢰를 불러오지만 다른 사람의 제안이 들어올 자리도 남겨 두세요.","진지한 모습 아래에는 오래 남을 무언가를 만들겠다는 깊은 포부가 있어요.","업무에서 세부 사항 일부를 맡기면 중요한 결정을 위한 여유가 생길 수 있어요.","프로젝트를 차근차근 세우는 데는 규율만큼 유연함도 필요할 수 있어요."],"love":["절제된 감정 표현 뒤에는 일상에서 오래 이어지는 성실함이 숨어 있어요.","튼튼한 관계도 목표 없이 즐기는 즉흥적인 순간들로 풍요로워집니다.","약속을 지키는 마음은 소중한 관계에 깊이를 더해요.","말로 다 전하기 어렵다면 진심 어린 작은 배려가 많은 것을 전달할 수 있어요.","안정감이 필요하더라도 상대의 새로운 면을 발견하는 즐거움을 함께 누릴 수 있어요.","겉으로 조용해 보여도 감정에는 숫자로 잴 수 없는 자리가 필요합니다.","가까운 사람이 고민을 말할 때 항상 해결책을 내놓아야 하는 건 아니에요.","계획 없이 함께 보내는 시간이 곁에 있는 사람과 더 가까워지게 할 수 있어요."],"wellbeing":["의무감이 강한 당신에게 휴식은 얻어야 하는 보상이 아니에요.","눈에 보이는 성과가 없어도 평온한 순간은 소중합니다.","규칙적인 태도가 도움이 되지만 하루의 모든 순간을 채워야 하는 것은 아니에요.","마음속에서 일주일을 미리 계산할 때는 지금의 호흡으로 천천히 돌아와 보세요.","정리하는 능력을 활용해 진짜 휴식 시간을 지켜 보세요.","야망을 품은 당신에게도 특별한 쓸모 없는 즐거움을 누릴 권리가 있어요.","할 일 사이에 시계 없이 걷는 산책을 마련해 보면 시간의 다른 모습이 보여요.","속도를 늦춰도 결의는 사라지지 않아요. 오히려 더 차분하게 이어질 수 있어요."],"wisdom":["당신의 가치는 성취 목록만으로 설명할 수 없습니다.","정상에 오르는 기쁨은 경치를 바라볼 때 더 깊어집니다.","튼튼한 계획은 변화할 수 있을 때 더욱 견고합니다.","모든 일에는 자기 자리가 필요해요. 휴식도 마찬가지입니다.","야망은 삶의 모든 지평선을 차지하지 않고도 자랄 수 있어요.","미래를 만든다고 현재를 놓칠 필요는 없습니다.","신뢰는 끊임없는 점검이 아닌 다른 방식으로도 자라납니다.","함께 걷는 사람을 잊은 채 오래갈 것을 만들 수는 없어요."],"roast":["모든 것을 관리하고 싶은 마음이 작은 돌발 상황까지 긴급한 문제로 만들 때가 있어요.","개인적인 목표가 삶을 즐길 공간까지 차지할 수 있어요.","철저함은 강점이지만 작은 오차를 받아들이기가 어려워질 때가 있죠.","누군가 즉흥적인 외출을 제안하면 가장 먼저 달력을 확인합니다.","효율성을 따지는 습관 때문에 취미까지 업무처럼 평가할 수 있어요.","진지한 모습 뒤에서 언제 정말 쉬는지 알기 어려울 때가 있어요.","계획이 조금만 바뀌어도 누가 일정표를 수정할지부터 찾습니다.","모든 세부 사항을 정리하면 마음은 놓이지만 즐거운 우연이 들어올 자리는 줄어들어요."]},"funny":{"career":["당신의 업무용 달력에는 내년 휴가 일정도 이미 들어 있어요. 휴가가 동의하기만 기다립니다.","동료가 즉흥적인 아이디어를 내면 예산과 위험 요소, 즉흥성의 납기일을 묻습니다.","회의에는 목표가 세 개였는데 당신은 목표를 추적할 표와 그 표를 추적할 표까지 준비했어요.","사무실에 펜이 부족하면 분기별 소모량 조사를 시작합니다. 파란 펜은 증언을 거부해요.","업무 보고서가 너무 좋아서 손님에게 보여 주려고 제본할까 고민합니다.","모니터 아래 메모지들은 우선순위대로 정렬돼 있어요. 긴급이라는 단어조차 일련번호를 가집니다.","모두가 프로젝트 완료를 축하하는 순간 파티 개선 회의를 제안합니다.","진로를 계획하면 마음이 편안해져요. 10년 뒤 목표 직책이 이미 즐겨찾기에 있거든요."],"love":["당신의 낭만은 확인된 예약과 예비 우산, 최적화된 이동 경로로 표현됩니다.","깜짝 이벤트가 좋아요. 최소 사흘 전에 달력 초대를 받는다면요.","사랑하는 마음이 커서 선물 후보들의 보증 조건까지 이미 비교했어요.","무슨 감정인지 물으면 일단 진지한 마음이라고 답합니다. 나머지는 승인 뒤에 나와요.","촛불 저녁에 영감을 받아 최적의 식당 비교표를 만듭니다. 디저트에도 독립된 열이 있어요.","차분한 모습 뒤에서 감동적인 고백을 준비 중이에요. 파일 이름은 최종본 7이에요.","새로운 관계가 시작되자마자 주말 일정을 고민합니다. 상대는 그냥 외투를 찾고 있었는데요.","소파를 나눠 쓰는 건 큰 신뢰의 표시예요. 팔걸이에 자리를 하나 비워 줬거든요."],"wellbeing":["당신의 휴식은 오후 2시 정각에 시작됩니다. 2시 3분에는 계획대로 진행되는지 점검하죠.","목적 없는 산책은 수상해요. 결국 앱으로 이동 성과를 측정합니다.","낮잠을 자고 싶지만 효율을 위해 15분과 20분 중 어느 쪽이 나을지 아직 비교 중이에요.","쉴 때도 할 일 목록에 휴식 완료라는 항목을 뿌듯하게 체크합니다.","휴식을 위해 알림 두 개와 체크박스 하나가 필요해요. 쿠션은 그냥 앉아 달라고 합니다.","담요 아래 누워서도 내일 일정을 머릿속으로 검토해요. 베개가 폐회를 선언합니다.","공원에서는 그늘과 조용함, 출구 접근성을 모두 고려해 가성비 좋은 벤치를 고릅니다.","속도를 늦추는 일이 너무 힘들어서 주간 보고서에 칭찬 한 줄을 넣을까 생각해요."],"wisdom":["대시보드는 마음껏 웃는 순간의 품질을 측정하지 못해요.","성과 없는 일요일도 완벽한 일요일입니다.","열정은 늘 목표 달성이라는 칸에 들어맞지는 않아요.","정상은 간식을 다 먹을 때까지 기다려 줄 수 있어요.","당신의 야망은 셈을 잘하죠. 안락의자는 품어 주는 법을 알아요.","튼튼한 미래를 만든다고 양말 하나 잃는 일이 금지되지는 않아요.","점심 식사마다 공식 회의록이 필요한 건 아닙니다.","휴식이 증빙 서류를 제출해야 한다는 증거는 어디에도 없어요."],"roast":["당신의 휴가 계획표에는 즉흥적 휴식이라는 잠긴 탭이 있어요.","예상 못 한 선물을 받으면 웃으며 보증 양도가 가능한지 묻습니다.","어떻게든 되겠지라는 말은 당신에게 스릴러 영화보다 무서워요.","지금을 즐기라는 말을 들으면 평가 기간이 언제부터 언제까지인지 묻습니다.","장보기 예산에는 과자 가격도 한 푼까지 계산돼 있어요. 과자는 협상을 원합니다.","책임감 있는 사람이라는 외투 아래에서 마음속 아이는 아직 회계팀 승인을 기다려요.","연말 파티에서 즐거움에 관한 연례 결산을 제안합니다. 손님들은 못 들은 척해요.","당신 집에서는 즉흥성이 예정된 날에만 작동합니다."]},"piquant":{"career":["당신의 야망에는 아이디어가 생기기도 전에 조직도가 있어요. 아이디어들은 이제 사전 면접을 봐야 합니다.","동료가 주말 이야기를 꺼내자 즉시 생산성을 물어요. 토요일은 사직서를 냈습니다.","노을보다 수익성에서 더 많은 시를 느낍니다. 예산에 보내는 사랑 고백에는 부록이 여섯 개예요.","간단한 업무 하나를 맡아도 운영위원회를 만듭니다. 업무는 보석을 신청해 풀려나고 싶어 해요.","5개년 계획에는 즉흥적인 행동까지 예정돼 있어요. 즉흥성은 명예훼손으로 이의를 제기했습니다.","진지함 뒤에서 커피 시간은 삭감할 비용 항목이에요. 커피는 희망퇴직을 준비합니다.","예상 밖의 일이 생기면 책임자를 찾습니다. 우연은 인사팀 면담을 기다리고 있어요.","회사를 정리하는 일을 너무 좋아해서 미소까지 사용 빈도별로 분류했어요. 행복은 접속 권한을 잃었습니다."],"love":["당신의 로맨스는 타당성 검토부터 시작해요. 상상 속 설렘조차 추천서 세 장을 제출해야 합니다.","관계가 분기별 목표를 지킬 때 가장 마음에 들어요. 달력은 연애 가능 여부를 고민합니다.","당신의 다정함은 신중하게 협상된 제안서 같아요. 꽃다발은 법무팀 면담을 요청했습니다.","예상 못 한 저녁 초대를 받으면 의사일정부터 요구해요. 촛불들이 파업에 들어갔습니다.","조심스러운 마음은 문을 여는 대신 입찰을 진행해요. 지원서 접수는 지난 화요일에 끝났습니다.","조용한 감정 뒤에는 신뢰 계약서 열두 조항이 있어요. 즉흥성은 자격 기준에 미달합니다.","칭찬을 들으면 객관적으로 검증 가능한지부터 확인합니다. 로맨스가 회의장을 떠났어요.","함께할 미래를 나누는 일이 자연스럽죠. 디저트를 고르기도 전에 예측 자료를 출력했으니까요."],"wellbeing":["당신의 휴식에도 측정 가능한 목표가 필요해요. 베개는 제대로 일했다는 걸 증명할 독립 감사를 요청합니다.","자유로운 산책은 비효율적이죠. 나무 두 그루 사이의 경로를 최적화하자고 제안합니다. 나무들은 합병을 거절해요.","당신 집의 휴식은 출입증과 엄격한 운영 시간을 가지고 도착합니다. 증빙 서류가 없으면 입장 불가예요.","컴퓨터를 끄자 머릿속에서 다른 표를 엽니다. 침묵은 경업 금지 조항을 요청했어요.","조용한 일요일도 분 단위로 계획돼 있어요. 하품마저 참석을 확인해야 합니다.","담요 밑에서 쉬는 시간을 제대로 쓰는지 평가합니다. 담요는 장기휴가를 신청했어요.","지루함이 찾아오자마자 휴식 개선 프로젝트를 시작합니다. 휴식은 단체 채팅방을 나갔습니다.","속도를 늦추는 일도 실적 보고서를 받을 수 있다면 허용해요. 안락의자는 인증을 거절했습니다."],"wisdom":["당신의 야망은 산을 오른 뒤 정상에서 승진을 요구해요.","측정 지표 없는 즐거움은 연례 보고서에 실리지 못합니다.","신중함이 당신 머릿속에 컨설팅 회사를 차렸어요.","모든 것은 협상 대상이죠. 예산안을 거부한 소파만 빼고요.","당신의 진지함은 미소에게 경비 청구서를 쓰라고 요구했습니다.","미래를 만드는 건 고귀해요. 미래에 청구서까지 보내는 건 조금 덜 고귀합니다.","즉흥성도 있긴 해요. 예상 못 한 사고라는 폴더에 넣어 뒀죠.","당신은 휴식이 효율적인지 확인할 때 가장 편안해져요."],"roast":["당신의 달력에서 생일은 기념일이 아니라 계약상 마감일이에요. 촛불은 청구서를 기다립니다.","친구들과 저녁을 먹으면 진행 상황 회의가 됩니다. 디저트는 지표 발표를 거부했어요.","소파를 산 뒤로는 사용 시간 대비 수익성을 걱정합니다. 소파는 초과근무 수당을 요구해요.","즉흥적으로 하자는 말에 비상대책위원회가 소집됩니다. 돌발 상황은 비상구로 도망쳤어요.","조심스러운 마음에는 은행망보다 방화벽이 많아요. 칭찬은 수상한 활동으로 차단됩니다.","진지함 속에 품질관리 담당자가 숨어 있어 깜짝 이벤트도 평가합니다. 깜짝 이벤트들은 부서 이동을 신청해요.","생일 촛불을 끄는 순간 행사에 쓰인 에너지 비용을 계산합니다. 케이크는 계산 중단을 요청했어요.","행복을 표로 관리하는 게 합리적이라고 생각했죠. 기쁨이라는 셀에서 수식 오류가 발생했습니다."]},"roastMy":["염소자리인 당신은 휴가를 떠나는 게 아닙니다. 작전 계획을 실행하는 거죠. 이동과 휴식, 낮잠까지 모두 색상 코드가 있어요. 가족이 바다를 바라보자고 합니다. 당신은 그 활동의 전략적 목표가 무엇인지 묻습니다.","당신의 야망은 자서전 제목까지 이미 정해 놨어요. 장과 부록, 출간일도 계획했죠. 빠진 부분은 즐겁게 놀았던 순간이라는 장이에요. 편집부는 당신의 일정이 비기를 기다립니다.","당신은 안전과 숫자, 확실한 결정을 좋아해요. 누군가 즉흥적인 저녁을 제안하면 기쁨에 숨은 비용을 분석합니다. 일행은 당신 없이 출발해요. 당신은 나중에 사고 보고서를 요청합니다.","염소자리인 당신의 달력엔 빈칸이 없어요. 빈칸마저 예약돼 있죠. 두 개의 결산 사이에 즉흥성을 위한 시간을 잡았습니다. 즉흥성은 참석을 확인하지 않았어요. 마지막 독촉장을 보내는 중입니다.","당신의 돈에 대한 태도는 모든 물건과 끊임없이 협상하는 모습 같아요. 마음에 드는 램프를 발견하고 사용 횟수당 미소가 몇 번 생길지 계산합니다. 직원이 색깔을 고르라고 하죠. 당신은 5개년 전망표를 요구합니다.","당신은 코미디를 보면서도 진지해 보여요. 장면 구성과 시간 운영을 분석하거든요. 다른 사람들은 웃고 있어요. 당신은 유머 생산성을 개선할 여지가 있다고 기록합니다.","당신의 로맨스는 믿음직하지만 행정적인 구조를 갖고 있어요. 예약과 비교, 확인과 시간 검증을 모두 마치죠. 상대가 다정하다고 말합니다. 당신은 수령 확인 서명을 해 줄 수 있느냐고 물어요.","염소자리인 당신은 휴식을 최고 수준의 규율로 바꿨어요. 산책 시간과 주말 목표를 정합니다. 돌아와서는 결과 보고서를 작성해요. 의자는 당신과 떨어진 곳으로 휴가를 가고 싶어 합니다.","당신의 끈기는 존경스럽지만 일을 절반만 하고 멈추지 않아요. 문제는 끝난 일도 끝났다고 인정하지 않는다는 거죠. 장보기 목록마저 위원회 승인을 받아야 합니다. 위원회는 장보러 갈 시간이 없어요.","생일에도 회의록이 필요하다고 믿는 사람은 당신뿐일 거예요. 장식은 승인됐고 일정은 지켜졌으며 과자는 정확히 배분됐죠. 손님들이 생일 노래를 불러 줍니다. 당신은 종료 보고서에 예정에 없던 열정이라고 적습니다."]},"aquarius":{"classic":{"career":["기존 습관이 가능성을 가로막을 때 당신의 독창성은 새로운 길을 열어 줍니다.","대담한 아이디어도 다른 사람이 따라올 수 있는 단계로 구체화할 때 힘을 얻어요.","관습에서 한 걸음 떨어져 보는 태도는 당연한 것에도 질문하게 합니다.","불필요해 보이는 규칙이 있다면 그 배경을 이해할수록 더 나은 변화를 제안할 수 있어요.","독립적인 정신은 모두가 자유롭게 기여하는 협력 속에서 더 강해집니다.","남다른 관점 뒤에는 공동체를 발전시키고 싶은 진심이 있어요.","직장에서 다르게 생각하는 능력은 막힌 상황을 풀어내는 데 귀중해요.","새로운 직감을 인내심 있게 공유하면 독특한 생각도 자리를 찾을 수 있어요."],"love":["독립성을 바라는 마음과 스스로 선택한 다정한 관계는 함께할 수 있어요.","뜻밖의 대화에서 서로의 공통점을 발견하며 관계가 자라기도 해요.","다른 사람을 향한 호기심에 세심한 관심을 더하면 대화가 더욱 깊어져요.","감정을 잘 드러내지 않을 때는 소박한 말 몇 마디가 애정을 알아보기 쉽게 해 줍니다.","차이를 좋아하는 태도는 상대방을 습관으로만 판단하지 않고 발견하게 합니다.","겉으로는 거리를 두는 듯해도 당신의 성실함은 독특한 방식으로 나타나요.","관계의 중심에는 정해진 틀보다 진정한 모습이 중요해요.","서로 다른 속도를 존중하면 각자가 자유롭고 인정받는 공간이 만들어져요."],"wellbeing":["새로운 것을 만들어 내는 정신에도 아무 아이디어도 요구받지 않는 시간이 필요해요.","익숙한 장소를 산책하는 일도 일상을 새로운 시선으로 바라보게 할 수 있어요.","탐험할 자유만큼 속도를 늦출 자유도 당신에게 있어요.","생각이 많아질 때 단순한 활동 하나가 현재로 시선을 되돌려 줍니다.","새로움을 향한 마음과 스스로 선택한 편안한 휴식 습관은 균형을 이룰 수 있어요.","지적인 움직임을 좋아하는 마음 뒤에도 고요함이 들어올 자리가 있어요.","바쁜 하루에는 화면에서 떨어져 있을 시간을 지키는 것도 좋아요.","혼자만의 시간과 진심 어린 대화 중 무엇이 힘이 되는지 자신의 마음에 따라 선택해 보세요."],"wisdom":["다름의 가치는 다른 사람의 다름도 받아들일 때 완성됩니다.","규칙은 바꾸기 전에 이해해 볼 가치가 있어요.","새로움은 삶을 더 풍요롭게 할 때 소중합니다.","자유로운 정신도 자신을 잃지 않고 경청할 줄 알아야 합니다.","독립적이라고 다른 사람을 멀리해야 하는 건 아니에요.","다르게 생각한다고 잘 작동하는 것까지 버릴 필요는 없습니다.","미래는 현재를 돌보는 사람들의 것이기도 해요.","독창성 때문에 소박함을 잊을 필요는 없습니다."],"roast":["관습을 싫어하다 보면 사실 불편하지도 않았던 습관에 반대할 수 있어요.","빛나는 아이디어도 새 생각 세 개가 바로 뒤따르면 다른 사람들이 따라오기 어려워져요.","감정적 거리를 두면 편할 수 있지만 가까운 사람들은 혼란스러울 수 있어요.","모두가 같은 해결책을 고르면 그 해법의 문제부터 찾으려 해요.","반항심이 제안을 끝까지 듣기도 전에 일어날 때가 있어요.","독창성에 대한 애착 뒤에서 단순한 해법들은 검토받기를 기다립니다.","어떤 유행이 널리 알려지는 순간 갑자기 관심을 잃을 때가 있어요.","다른 사람을 따르지 않는 것을 너무 좋아해서 자기 조언까지 거부하기도 해요."]},"funny":{"career":["당신의 상상력은 회의를 연결된 수족관으로 대체하자고 제안해요. 동료들은 그냥 커피 휴식을 원했는데요.","세 단계짜리 절차도 낡았다고 생각해요. 그래서 없애려고 화면 열다섯 개짜리 앱을 만듭니다.","상사가 절차를 따르라고 하자 정중히 묻습니다. 그 절차는 누가 허가했나요?","사무실 의자가 바뀌면 자율주행 가구를 제안해요. 의자는 벌써 제자리에서 빙빙 돌고 있습니다.","미래의 일하는 방식을 상상하는 건 즐겁죠. 오늘 해야 할 일은 아직 받은 편지함에서 기다립니다.","회의 중 조용히 있는 건 키보드를 새롭게 발명할 생각을 하기 때문이에요. 정상이라는 키는 이미 삭제했습니다.","아이디어 회의에서 너무 독특한 해결책을 내놔서 그에 맞는 문제부터 새로 만들어야 해요.","발견한 것을 공유하기 좋아해서 동료들은 존재하는 줄도 몰랐던 주제의 강연을 듣습니다."],"love":["당신만의 애정 표현은 특별해요. 평범한 다정한 문자 대신 해파리에 관한 놀라운 기사를 보내죠.","낭만적인 저녁으로 미래형 가구 전시회를 제안해요. 상대방은 스마트 의자를 처음 만납니다.","거리를 유지하는 게 자연스러워요. 단체 메시지엔 열정적으로 답하면서 개인 메시지는 잊어버립니다.","즉흥적인 애정 표현을 부탁받으면 맞춤형 칭찬을 나눠 주는 기계를 만듭니다.","독립심이 강해도 진심 어린 관계를 좋아해요. 소파에 리모컨 두 개가 각각 있어야 한다는 조건으로요.","무심한 표정 뒤에는 사랑스러운 깜짝 이벤트가 준비돼 있어요. 다만 작은 로봇을 조립해야만 즐길 수 있죠.","식당에서 메뉴 선택도 식생활의 미래에 관한 토론으로 바꿉니다. 감자튀김은 자기 차례를 기다려요.","함께 드라마를 보는 게 즐거웠다가 모두가 그 드라마를 좋아한다고 하자 갑자기 생소한 다큐멘터리를 추천합니다."],"wellbeing":["이상적인 휴식은 화면을 끄는 일이에요. 먼저 화면을 끄라고 알려 주는 앱부터 개발합니다.","공원 산책이 비둘기의 사회생활에 관한 연구로 변해요. 가설도 이미 세 개나 있어요.","혼자 있는 시간이 힘이 되지만 휴대전화에는 자유의 의미를 논하는 단체 채팅방이 여덟 개나 있습니다.","아무것도 하지 않기로 결정하면 더 효율적으로 아무것도 하지 않는 새로운 방법을 설계합니다.","발명가다운 정신이 차 한 잔도 최적의 음용 온도를 찾는 실험으로 바꿔요.","연구자 같은 호기심 뒤에서 쿠션은 원래 기능을 시험해 주기만을 기다립니다.","잠들려는 순간 혁명적인 아이디어가 떠오릅니다. 베개는 내일 특허를 신청하자고 제안해요.","속도를 늦추는 것도 스마트워치로 효과를 측정할 수 있다면 매력적이에요. 시계는 휴식을 요청합니다."],"wisdom":["독창적이라는 걸 증명하려고 커피를 받침 접시에 마실 필요는 없어요.","미래의 아이디어도 리모컨을 찾는 일에서 시작할 수 있어요.","반항은 실제로 규칙이 있을 때 더 멋져 보여요.","모든 사람은 독특해요. 매 식사마다 입증할 필요는 없지만요.","자유는 잘 작동하는 요리법을 받아들인다고 줄어들지 않아요.","혁신이 반드시 숟가락을 바꾸는 걸 뜻하지는 않습니다.","미래는 내일 시작돼요. 빨랫감은 어제부터 기다립니다.","다른 사람이 옳다면 그들과 똑같이 행동해도 괜찮아요."],"roast":["평범함을 거부하는 일이 너무 규칙적이어서 가족 전통처럼 보이기 시작했어요.","잘 작동하는 아이디어라도 두 번째 사람이 쓰기 시작하면 지루해해요. 즉시 이해할 수 없는 버전을 만듭니다.","날씨를 이야기하던 중 당신은 떠다니는 도시 이론을 발표합니다.","아무도 나를 이해하지 못한다고 말하면 모두가 그림을 다시 설명해 달라고 합니다.","반항심에 가장 독특한 길을 골라요. 청소도구 보관실로 이어지는 길일지라도요.","무심한 태도 뒤에서는 멀리서 사랑하는 친구들의 알림 마흔 개가 쌓여 있습니다.","식당에서 가장 신기한 음식을 주문하고는 진짜 신기해서 놀랍니다.","꼬리표를 싫어하는 게 특기라 새 꼬리표를 만들었어요. 꼬리표 거부 전문가라는 꼬리표죠."]},"piquant":{"career":["다르고 싶은 욕구로 잘 작동하는 도구를 다시 발명해요. 새 도구는 교육 세 번과 개막식이 필요합니다.","기본 규칙 하나도 당신의 천재성을 모욕하는 듯 느껴져요. 더 복잡한 대안을 제안하죠. 기존 규칙이 복직을 신청합니다.","아무도 안 쓸 때만 새로움에 끌려요. 팀이 당신의 아이디어를 채택하자 곧바로 구식이라고 선언합니다. 팀은 중재자를 요구해요.","상사가 절차를 설명하면 절차를 허가하는 절차부터 보여 달라고 해요. 법무팀은 커튼을 닫았습니다.","선견지명이 뛰어나서 10년 뒤의 일을 하고 있어요. 금요일 마감 문서는 실종 신고를 했습니다.","공동체를 사랑한다는 연설 뒤에는 조건이 있어요. 공동체가 먼저 당신이 옳다고 인정해야 합니다. 민주주의는 점검 중이에요.","합의가 이뤄지면 바로 반대파가 됩니다. 방금 낸 자신의 제안까지 스스로 반대했어요.","혁신에 너무 몰두해 클립을 개념적인 무언가로 교체합니다. 서류들은 보호 조치를 요청했어요."],"love":["당신의 독립성은 감정용 방 두 개와 비상구, 제한된 감정 접근 권한을 예약했어요. 다정함은 출입증을 기다립니다.","사랑 고백보다 평범한 질문이 더 당황스러워요. 저 생각해 봤어요라는 물음에 머릿속이 강연을 준비합니다.","감정적 거리는 매력적으로 보일 수 있어요. 그러다 사람들이 가끔은 메시지 답장을 더 원한다는 걸 깨닫죠.","누군가 독특하다고 칭찬하면 과학적 인증을 받은 듯 행동해요. 칭찬은 입 밖에 나온 것을 후회합니다.","다름을 사랑한 나머지 찾을 수도 없는 곳에서 데이트를 잡아요. 지도 앱도 주소를 거절합니다.","신비로운 미소 뒤에는 평범한 이유가 숨어 있어요. 발명품을 생각하고 있었죠. 로맨스는 알지 못했어요.","늘 하던 대로 하자는 말이 나오자 가정 혁명을 소집합니다. 저녁에 접시를 쓰자는 이야기였는데요.","감정을 나누려면 개념 발표 자료부터 준비하고 싶어 해요. 마음은 슬라이드 없는 버전을 요구합니다."],"wellbeing":["당신의 머릿속은 평범한 휴식을 거부해요. 휴식을 실험실로 바꿉니다. 쿠션은 과도한 실험으로 고소했어요.","조용한 산책도 너무 관습적이라 평소 경로를 거꾸로 걸어요. 지도는 감정을 요청합니다.","다 함께 쉬자는 말은 답답해요. 혼자 있기 위한 모임을 설립합니다. 모임은 총회를 요구해요.","다른 사람들이 휴대전화를 끄면 당신은 다시 켤 새로운 이유를 발명합니다. 비행기 모드는 사표를 냈어요.","미래지향적인 정신이 수면을 개선할 혁신을 찾고 있어요. 스탠드는 그냥 불을 끄라고 제안합니다.","무심한 태도 뒤에서는 집단을 따르지 않는 법을 논하는 모임 세 곳을 감시하고 있어요. 모순이 정기 구독을 신청했습니다.","신선한 공기를 마시려다가 공원의 환기 이론부터 제시합니다. 나무들은 기밀 유지를 요청해요.","남들처럼 속도를 늦추는 건 너무 단순해요. 대안적 휴식에 특허를 냅니다. 침묵은 로열티를 요구합니다."],"wisdom":["당신의 독창성은 얼마나 유일한지 확인해 줄 관객이 필요해요.","이해할 수 없는 생각이라고 자동으로 시대를 앞선 건 아니에요.","열린 문을 향한 반란은 꽤 극적인 입장 방식이군요.","모두가 당신을 따라 하는 건 아니에요. 어떤 사람은 그냥 의자를 샀어요.","당신의 독립성은 관계를 거부하면서도 단체 채팅방은 즐겨찾기에 넣습니다.","지시를 피하려고 혁신하다가 그 지시를 위한 궁전까지 지었군요.","미래가 궁금하겠지만 현재는 아직도 당신의 답장을 기다립니다.","특별히 자신만을 위한 규정을 만들어야 진짜 반항아라고 생각하나요?"],"roast":["당신의 차별성은 너무 중요해서 공식 독창성 증명서를 요구해요. 신청서는 모두에게 똑같습니다.","평범한 발명도 당신에게는 패러다임 전환이에요. 상자에 라벨 하나 붙였을 뿐인데요.","감정적으로 가까워지는 건 수상해요. 인류 전체를 사랑하지만 대화할 때는 2미터 거리 유지가 조건이죠.","다른 사람들이 좋아하는 음악을 발견하면 그 곡을 바로 버립니다. 재생기는 안정적인 정체성을 요구해요.","자유로운 당신은 표지판을 따르지 않아요. 그런데 책상을 정리하는 규칙은 스무 개나 만들었죠. 표지판이 해명을 요구합니다.","별난 아이디어 사랑 뒤에서는 단순함에 대한 개인적인 전쟁이 벌어지고 있어요. 숟가락은 이웃집으로 피신했습니다.","모두가 동의하자 즉시 반대편으로 이동합니다. 옛 의견들은 공식 야당을 결성했어요.","소파에서 세계를 혁명하는 일로 바빠요. 소파는 먼저 리모컨부터 찾아 달라고 합니다."]},"roastMy":["물병자리인 당신은 단순히 남다른 게 아닙니다. 남다름을 정기 구독 서비스로 만들었죠. 인기 있는 취향을 거부하고 자기 취향까지 유행하면 버립니다. 당신의 정체성은 매주 목요일 진열장을 바꿔요. 독창성마저 계약을 해지했습니다.","당신의 머릿속은 아무도 겪지 않는 문제의 해결책을 발명해요. 스위치를 앱으로 바꾸고 앱을 실험용 시제품으로 다시 바꿉니다. 방은 계속 어두워요. 그런데도 역사적인 기술 성공을 선언합니다.","당신은 모두를 좋아하지만 법정 거리만큼 떨어져서 좋아해요. 친구가 하루 이야기를 하면 사회의 진화에 관한 링크로 답합니다. 친구는 다정한 한마디를 기다려요. 당신은 수정된 링크를 또 보냅니다.","물병자리인 당신은 규칙을 읽기도 전에 반대해요. 자유롭고 혁신적이며 완전히 새로운 체계를 제안합니다. 세 쪽 뒤에는 규칙 열일곱 개와 감독 위원회가 생겨 있어요. 옛 규칙이 복권을 요구합니다.","당신의 미래는 놀라운 발명품으로 가득해요. 현재는 잃어버린 충전기와 쌓인 서류뿐이죠. 물질적인 물건은 낡은 개념이라고 설명합니다. 서류들은 기록관리자를 요구해요.","당신은 독립성을 거의 의식처럼 선언해요. 커피를 권받으면 모두가 마신다는 이유로 거절합니다. 그러고는 이상한 컵에 똑같은 음료를 만들어 마셔요. 커피는 평범함에 지원서를 내고 싶어 합니다.","당신의 무심한 눈빛은 우주의 비밀을 아는 것처럼 보여요. 사실 냉장고에 미니 정원을 만드는 생각을 하고 있죠. 괜찮냐는 질문에 수직 농업에 관한 강연으로 답합니다.","물병자리인 당신은 분류당하는 걸 싫어해요. 그런데 평범한 사람과 대담한 사람, 당신을 이해하지 못하는 사람을 구분하는 체계를 이미 만들었죠. 누구도 천재라는 정의에 맞지 않아요. 신기하죠. 그 칸은 자신을 위해 비워 뒀거든요.","당신은 시대보다 늘 5년 앞서 있다고 믿어요. 아무도 이해하지 못하는 프로젝트를 제시하고 쉽게 설명하길 거부한 뒤 남들이 뒤처졌다고 말하죠. 하지만 프로젝트는 혁명적인 게 아니에요. 내비게이션 화면이 달린 토스터입니다.","새로움을 향한 욕구는 저녁 식사를 미래에 관한 강연으로 바꿉니다. 아이디어 여덟 개와 시제품 세 개, 습관 없는 세상을 발표하죠. 손님들은 그냥 소금을 찾고 있어요. 당신은 소금이 월요일부터 탈중앙화된다고 선언합니다."]},"pisces":{"classic":{"career":["풍부한 상상력은 지나치게 딱딱한 방식이 놓치는 가능성을 보여 줄 수 있어요.","직감도 함께 결정하기 전에 차분히 살펴볼 가치가 있어요.","대화 속에서 보여 주는 섬세함은 팀의 기대를 더 잘 이해하는 데 도움이 됩니다.","아이디어가 여러 개 떠오를 때 현실적인 첫걸음을 정하면 창의력이 형태를 갖추기 시작해요.","분위기를 알아차리는 능력 덕분에 상황을 부드럽게 다룰 수 있어요.","몽상적인 모습 뒤에는 멀리 떨어진 생각들을 특별하게 연결하는 능력이 숨어 있기도 해요.","업무에서 명확한 경계를 세우면 중요한 프로젝트에 쓸 여유를 지킬 수 있어요.","영감을 행동으로 옮기려면 약간의 시간과 구조가 필요해요."],"love":["당신의 섬세함은 대화 속 미묘한 감정을 따뜻한 마음으로 받아들이게 해 줍니다.","조용한 배려도 거창한 낭만적인 행동만큼 많은 것을 전할 수 있어요.","다른 사람에게 베푸는 다정함에 자신의 필요를 듣는 마음도 함께해 주세요.","상상력이 너무 커질 때는 실제로 오간 말들을 되짚으면 생각을 분명히 할 수 있어요.","풍부한 애정은 각자가 자기 모습으로 자유롭게 지낼 수 있는 관계를 만들게 합니다.","조화를 꿈꾸는 마음 뒤에서도 소박하고 진실한 관계의 아름다움을 발견할 수 있어요.","친밀한 관계에서 두려움 없이 질문하는 일도 신뢰를 키워요.","상대의 감정을 받아들인다고 모든 문제의 해결책까지 찾아야 하는 건 아니에요."],"wellbeing":["섬세한 당신에게는 생각을 부담 없이 내려놓을 수 있는 조용한 장소가 잘 어울려요.","부드러운 음악이나 잠깐의 침묵은 자기 리듬을 되찾는 데 도움이 됩니다.","꿈꾸는 시간도 소중하지만 지금의 순간을 즐길 자리는 남겨 두세요.","주변의 요청이 많아질 때 소박한 휴식이 자신만의 공간을 되찾아 줄 수 있어요.","풍부한 상상력은 노트 한 권이나 산책, 익숙한 풍경에서도 자라납니다.","다른 사람에게 쏟는 관심만큼 자신을 기쁘게 하는 일에도 시간을 주세요.","하루 중 따뜻한 대화 하나가 마음을 편안하게 붙잡아 줄 수 있어요.","쉬고 싶은 마음에 귀 기울여도 너그러움이 줄어드는 건 아니에요."],"wisdom":["섬세함은 자신의 경계도 존중할 때 강점이 됩니다.","꿈은 현실의 작은 행동을 만날 때 더 깊어집니다.","부드러운 마음으로 모두의 걱정을 짊어질 필요는 없어요.","모든 느낌은 귀 기울일 가치가 있지만 긴 이야기까지 만들 필요는 없습니다.","직관은 몇 가지 질문도 받아들일 때 더욱 명확해집니다.","곁을 지켜 준다는 것이 모든 어려움을 해결한다는 뜻은 아닙니다.","상상력은 문을 열고 현실은 걸어갈 길을 보여 줍니다.","다정하다는 이유로 다른 사람을 위해 자신을 잊을 필요는 없습니다."],"roast":["상상력이 평범한 대화를 실제 사실보다 훨씬 복잡한 이야기로 바꿀 수 있어요.","사소한 도움을 부탁받아도 자신의 필요를 뒤로 미루곤 해요.","몽상에 자주 빠져서 현실적인 일들은 당신이 돌아오기를 기다릴 때가 있어요.","감정 하나가 찾아오면 마음의 모든 자리를 내어 주는 경우가 있어요.","모두를 이해하고 싶은 마음 때문에 다른 사람의 서툰 행동을 너무 쉽게 용서할 수 있어요.","아름다운 직감 뒤에서도 몇몇 세부 사항은 실제로 확인해야 해요.","간단한 결정을 할 때조차 상상력이 수많은 가능성을 보여 줍니다.","머릿속에서 이미 이야기가 시작됐다면 대화의 흐름을 다시 찾기 어려울 때가 있어요."]},"funny":{"career":["당신의 창의력은 공지문을 소설 첫 장으로 바꿉니다. 공지문에는 창문을 닫으라고만 적혀 있었는데요.","평범한 회의도 탁자 위 화분의 비밀스러운 삶을 상상하면 흥미진진해져요.","착한 마음으로 동료 세 명을 동시에 돕습니다. 자기 업무 파일은 조심스럽게 알림을 보냅니다.","모니터 앞에서 멍하니 있을 때 천재적인 프로젝트를 구상 중일 수도 있어요. 아니면 상상 속 왕국의 이름을 짓고 있겠죠.","분위기가 바뀔 거라는 직감이 찾아옵니다. 바뀐 건 동료가 과자 상자를 연 것뿐이에요.","모든 걸 고쳐 주고 싶어서 아무 부탁도 하지 않은 사람의 책상까지 재정리하기로 동의했어요.","문서를 읽다가 한 문장에서 추억을 떠올리고 그다음엔 노래, 이어서 영화 아이디어까지 생각합니다. 커서는 여전히 기다려요.","이상적인 결과를 상상하는 건 즐거워요. 이제 단계별 목록을 어디에 뒀는지 찾고 있습니다."],"love":["당신의 로맨스는 단순한 안녕하세요 한마디로 영화 한 편을 씁니다. 상대는 올바른 버스 정류장을 찾고 있었어요.","라디오에서 노래가 나오면 소중한 추억이 떠올라요. 그 기억에 이미 영화음악 전체를 붙였죠.","메시지에 평소와 다른 마침표가 있다는 사실을 알아차립니다. 문장부호 조사가 시작돼요.","누군가 우산을 빌려주면 너무 감동해서 시를 써 줄까 고민합니다.","넘치는 다정함은 베란다의 화분들에게도 향해요. 행복해 보이면 잘했다고 칭찬하죠.","꿈꾸는 눈빛 뒤에서는 아름다운 로맨스 장면이 펼쳐집니다. 현실에서는 직원이 주문을 기다리고 있어요.","저녁 식사를 하며 나중에 나눌 행복한 추억 열 개를 미리 상상합니다. 전채 요리 고르는 일만 잊었어요.","함께 걷는 것만으로도 동네의 불 켜진 창문마다 이야기를 만들어 냅니다."],"wellbeing":["슬리퍼를 찾는 동안 당신의 정신은 벌써 휴가를 떠났어요. 슬리퍼들은 묵묵히 기다립니다.","조용한 산책이 상상 놀이로 바뀌어요. 구름마다 이름과 일대기를 만들어 주죠.","휴식이 너무 잘돼서 왜 앉으러 왔는지까지 잊어버립니다.","부드러운 음악을 들으면 자신이 주인공인 영화의 엔딩 크레딧을 머릿속에서 만들어요.","남을 돌보고 싶은 마음으로 안락의자에게 쿠션까지 권합니다. 의자는 이미 편안해 보이는데요.","평온한 모습 뒤에는 거대한 서사시가 숨어 있어요. 물을 두 모금 마시는 사이 왕국 세 곳을 통과했죠.","잠자리에 들자 애니메이션의 감동적인 장면이 떠오릅니다. 베개는 긴 밤을 예상해요.","현재로 돌아오려면 가끔 표지판이 필요해요. 10분째 찾고 있는 열쇠 바로 옆에 있습니다."],"wisdom":["당신의 상상력은 뭐든 만들어 내지만 열쇠의 위치만은 만들어 내지 못해요.","한숨 하나가 꼭 로맨스 3부작을 필요로 하는 건 아니에요.","친절하다고 동네 화분을 전부 구해야 하는 건 아닙니다.","신비로운 눈빛마다 특별한 이야기가 시작되는 건 아니에요.","직관도 가끔 받은 편지함을 확인해야 해요.","위로한다고 슬퍼 보이는 토스터를 입양할 필요는 없어요.","영감은 자유롭게 여행하지만 약속 시간은 그대로예요.","구름이 당신에게 개인적인 메시지를 보냈다는 증거는 없어요."],"roast":["당신의 상상력은 알겠어라는 메시지 하나로 여섯 편짜리 드라마를 씁니다.","살짝 기운 화분을 보고 위로의 대화를 시작해요. 화분은 햇빛이 필요했을 뿐인데요.","몽상에 너무 멀리 떠나서 식어 버린 차에도 버림받은 사연이 생깁니다.","서점에 들어가면 책을 펼치기도 전에 등장인물에게 정이 들어요.","당신의 세계적인 연민은 마지막 과자가 혼자 남았다는 이유로 그 과자를 변호하게 만듭니다.","생각에 잠긴 표정 뒤에서는 헤어진 양말 두 짝의 대화를 상상하고 있을 때도 있어요.","지하철에서 누군가와 눈이 마주치자 과거와 비밀, 마지막 반전까지 만들어 냅니다. 상대는 노선도를 보고 있었어요.","열쇠를 찾는 건 너무 평범해요. 사라졌을 때 열쇠가 무엇을 하는지 상상하는 편이 더 재미있죠."]},"piquant":{"career":["당신의 상상력은 프로젝트 제목도 정해지기 전에 벌써 12장까지 썼어요. 일정 담당자는 상상 속 왕국의 지도를 요청합니다.","사소한 의견 하나로 열두 가지 해석을 만듭니다. 회의록은 소설 분야로 분류됐어요.","너무 착해서 팀 전체의 문제를 떠안아요. 당신의 원래 업무는 공식적으로 주인이 바뀌었습니다.","결정을 내려 달라는 요청에 영화와 은유, 플레이리스트를 제안합니다. 결정은 회의실을 나가 버렸어요.","틀림없다던 직감이 팀의 긴장감을 에어컨 고장과 혼동했어요. 에어컨은 사과를 요구합니다.","영감 어린 눈빛 뒤에서 실제 프로젝트가 현실로 가는 길을 애타게 찾고 있어요. 나침반을 신청했습니다.","사무실의 모든 고민을 주인 잃은 물건처럼 모읍니다. 분실물 센터는 당신의 입사지원을 거절했어요.","꿈을 일정표로 바꾸는 건 지나치게 단순하다고 생각해요. 달력은 그저 월요일에 출근할지 알고 싶을 뿐입니다."],"love":["당신의 로맨스는 2초간 마주친 눈빛을 여덟 시즌짜리 드라마로 바꿉니다. 주연 배우는 촬영 사실도 몰라요.","짧은 답장을 받으면 비극적 대본을 쓰고 이어서 행복한 속편까지 만듭니다. 메시지는 고작 알겠어였는데요.","다정한 마음 때문에 친절한 사람 모두와 감정적으로 가족이 됩니다. 배달 기사도 머릿속 소설에 등장해요.","누군가 예의상 웃기만 해도 상상력이 예고편을 제작합니다. 미소는 초상권료를 요구해요.","당신의 섬세함은 쉼표 하나에서 숨은 뜻을 듣는 재능이에요. 쉼표는 법적 보호를 요청합니다.","소박한 사랑을 약속하는 말 뒤에는 시나리오 작가팀이 숨어 있어요. 화요일의 반전 세 개까지 이미 준비했습니다.","침묵이 찾아오면 머릿속에 대화 전체를 써 내려갑니다. 상대는 그냥 파스타를 만들고 있었어요.","감정을 나누는 건 전문이죠. 목차가 필요할 만큼 미묘한 메시지를 보냅니다. 마침표는 길을 잃었어요."],"wellbeing":["당신의 몽상은 5분 휴식을 상상 속 왕국으로의 망명으로 바꿉니다. 알람 시계는 통역사를 요구해요.","쉬려고 걸었다가 떨어진 나뭇잎 하나를 구하는 임무를 맡습니다. 나무는 부탁한 적이 없어요.","휴식하는 사이 쿠션의 이야기를 지어냅니다. 쿠션은 자서전의 저작권료를 요구해요.","조용해지고 싶어 구름의 기분부터 분석합니다. 하늘은 당신의 알림을 차단했어요.","모두를 위로하고 싶어서 화분들의 지지 모임을 만듭니다. 고무나무는 사생활을 요구해요.","평온한 표정 뒤에서 감정 법정이 화요일의 대화를 심판하고 있어요. 화요일은 궐석 상태로 무죄 판결을 받았습니다.","잠들려는 순간 정신이 따뜻한 추억들의 감독판을 틀어요. 베개는 정식 민원을 제기합니다.","현재의 감각으로 돌아가는 것이 합리적이죠. 그런데 방금 주전자의 감정부터 상상했군요."],"wisdom":["당신의 직관은 세 단어짜리 메시지에서 장편소설을 읽어 냅니다.","눈빛 하나가 약속이 되는 건 아니에요. 상상 속 음악이 깔려 있어도요.","연민 때문에 쿠션의 권리까지 변호할 의무는 없어요.","모든 침묵이 비극을 숨긴 건 아니에요. 가끔은 누군가 밥을 먹고 있죠.","당신의 몽상에는 영화관이 있어요. 현실은 입장권을 기다립니다.","우주 전체를 돕겠다고 나서면 일정표에는 주인이 없어져요.","상상력에는 증거가 하나도 없는데 증인들은 이미 소환됐어요.","단순한 고맙다는 말을 당신처럼 장엄하게 해석하는 사람도 드물 거예요."],"roast":["당신의 상상력은 안녕이라는 인사에 영화 3부작을 완성합니다. 보낸 사람은 영화 계약을 맺은 줄도 몰라요.","애니메이션을 보고 눈물 흘리는 것은 아주 자연스럽다고 생각해요. 이제 조연에게 사과 편지를 준비합니다.","연민이 넘쳐서 잘못 놓인 쿠션까지 도우려고 합니다. 쿠션은 독립을 요청했어요.","누군가 알겠어라고 답하면 숨은 의도 세 가지를 찾습니다. 그 단어는 무죄 추정의 원칙을 요구해요.","섬세함 때문에 날짜도 모르는 추억들을 수집해요. 식당 냅킨 하나가 역사적 유물로 지정됐습니다.","멍한 눈빛 뒤에서는 허가 없이 촬영 중인 내면의 감독이 있어요. 일상은 이의 신청을 준비합니다.","한숨 하나가 들리면 방 전체의 감정에 대한 조사가 시작됩니다. 의자는 단지 삐걱거렸다고 자백했어요.","현실로 돌아오는 일을 선택 과목처럼 여겨요. 열쇠들마저 상상 속 이야기로 이사 갔습니다."]},"roastMy":["물고기자리인 당신에게 이모지 없는 메시지는 여러 막으로 된 비극의 시작이에요. 문장부호를 다시 읽고 설명을 지어내고 화해 장면의 음악까지 고릅니다. 상대는 단지 손이 바빴던 거예요. 당신의 시나리오는 투자금을 잃었습니다.","당신의 상상력은 사실과 영화 예고편의 차이를 몰라요. 버스에서 누군가 쳐다보면 이야기를 한 편 통째로 만들죠. 그 사람이 시간을 묻습니다. 당신은 즉시 결말을 새로 씁니다.","당신은 아무도 도움을 부탁하지 않은 사람들까지 모두 구하고 싶어 해요. 살짝 기운 화분에 마음의 위로를 건넵니다. 창문을 열자 화분이 바로 섭니다. 당신은 공감 능력의 승리라고 선언해요.","물고기자리인 당신은 허구의 이야기를 너무 몰입해서 소파가 드라마 등장인물들을 모두 알 지경이에요. 오해받는 악당을 변호하고 상상 속 영웅을 위로하죠. 소파는 그 회차를 보지도 못했어요. 당신은 40분간 줄거리를 설명합니다.","당신은 열쇠와 컵, 때로는 왜 어디로 가려 했는지도 잃어버려요. 여기저기 찾으면서 멋진 이유를 상상합니다. 열쇠는 주머니에 있었어요. 당신은 운명이 숨겨 둔 거라고 결론 내립니다.","직관은 언제나 미묘한 차이를 해석할 준비가 돼 있어요. 동료가 정말 고맙습니다 대신 고맙습니다라고 쓰면 머릿속 비상대책반이 소집됩니다. 동료는 기차를 타러 급하게 가던 중이었어요.","당신은 추억을 너무 좋아해서 버스표 하나를 감정의 유물로 만들어요. 모든 물건에 사연과 분위기, 대략적인 날짜가 있죠. 낡은 종이 한 장도 버리지 않습니다. 그 종이는 당신을 기억하지도 못하는데요.","물고기자리인 당신은 쉬겠다고 약속한 뒤 누군가 사소한 걱정 하나를 말하면 곧바로 상담가와 중재자, 해결책 기획자가 됩니다. 상대는 우산에 관한 이야기를 하려던 것뿐이에요. 우산은 이제 자기계발 계획서를 가졌습니다.","당신의 정신은 말없이 대화에서 떠나 상상 속 도시를 지을 수 있어요. 돌아와서는 시적인 생각과 감정만 있고 원래 질문의 답은 없죠. 사람들이 뭘 마실지 묻습니다. 당신은 분수의 역사를 이야기해요.","당신은 지나가는 구름 하나에도 거대한 의미를 부여해요. 바라보며 여행을 상상하고 무슨 메시지를 싣고 있는지 궁금해하죠. 구름은 답 없이 흘러갑니다. 하늘 통역 담당 부서는 그래도 조사에 착수해요."]}}});
